	\begin{tabular}{lcc}
		\toprule
		\textbf{Metric} & \textbf{PwC} & \textbf{ChatPD} \\
		\midrule
		\textbf{\# Papers Extracted} & 14,353 & 35,310 \\
		\textbf{\# Dataset Descriptions Extracted} & 32,146 & 76,056 \\
