We introduce the operator
\begin{eqnarray}\label{eq:genAanal19e}
 \Phi_{{\mathcal U}_1}^{(i_3)} & \triangleq &  \mE_{{\mathcal U}_{1}} \frac{Z_{i_3}^{\m_1}}{\mE_{{\mathcal U}_{1}}Z_{i_3}^{\m_1}}  \triangleq  \mE_{{\mathcal U}_{1}} \lp \frac{Z_{i_3}^{\m_1}}{\mE_{{\mathcal U}_{1}}Z_{i_3}^{\m_1}}\lp \cdot \rp\rp,
 \end{eqnarray}
and set
\begin{eqnarray}\label{eq:genAanal19e1}
  \gamma_{00}(i_3) & = &
  \frac{
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p}    }{ \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp   }
\nonumber \\
  \gamma_0(i_1,i_2;i_3) & = &
\frac{(C_{i_3}^{(i_1)})^{s}}{Z_{i_3}}  \frac{A_{i_3}^{(i_1,i_2)}}{C_{i_3}^{(i_1)}} \nonumber \\
\gamma_{01}^{(1)}  & = &  \gamma_{00}(i_3)\Phi_{{\mathcal U}_1}^{(i_3)} (\gamma_0(i_1,i_2;i_3)) \nonumber \\
\gamma_{02}^{(1)}  & = &  \gamma_{00}(i_3)\Phi_{{\mathcal U}_1}^{(i_3)} (\gamma_0(i_1,i_2;i_3)\times \gamma_0(i_1,p_2;i_3)) \nonumber \\
\gamma_{1}^{(1)}   & = &  \gamma_{00}(i_3)\Phi_{{\mathcal U}_1}^{(i_3)}  \lp \gamma_0(i_1,i_2;i_3)\times \gamma_0(p_1,p_2;i_3) \rp \nonumber \\.
\gamma_{21}^{(1)}   & = &  \gamma_{00}(i_3)\Phi_{{\mathcal U}_1}^{(i_3)}   \gamma_0(i_1,i_2;i_3)  \times  \gamma_{00}(p_3) \Phi_{{\mathcal U}_1}^{(p_3)}  \gamma_0(p_1,p_2;p_3)
\nonumber  \\
\gamma_{22}^{(1)}   & = &  \gamma_{00}(i_3)\lp \Phi_{{\mathcal U}_1}^{(i_3)}   \gamma_0(i_1,i_2;i_3)  \times  \Phi_{{\mathcal U}_1}^{(i_3)}  \gamma_0(p_1,p_2;i_3) \rp.
\end{eqnarray}
It is relatively easy to check that all the above $\gamma$'s are valid measures. For example, we have
\begin{eqnarray}\label{eq:genAanal19f}
 \sum_{i_3=1}^{l}  \sum_{i_1=1}^{l}  \sum_{i_2=1}^{l} \gamma_{01}^{(1)}
  & = &
   \sum_{i_3=1}^{l}  \sum_{i_1=1}^{l}  \sum_{i_2=1}^{l} \gamma_{00}(i_3)\Phi_{{\mathcal U}_1}^{(i_3)} (\gamma_0(i_1,i_2;i_3))
   \nonumber \\
  & = & \sum_{i_3=1}^{l}   \sum_{i_1=1}^{l}  \sum_{i_2=1}^{l} \gamma_{00}(i_3)  \mE_{{\mathcal U}_1}\frac{Z_{i_3}^{\m_1}}{\mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}}\frac{(C_{i_3}^{(i_1)})^{s}}{Z_{i_3}}  \frac{A_{i_3}^{(i_1,i_2)}}{C_{i_3}^{(i_1)}} \nonumber \\
& = &
\sum_{i_3=1}^{l}  \gamma_{00}(i_3)  \mE_{{\mathcal U}_1}\frac{Z_{i_3}^{\m_1}}{\mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}}   \sum_{i_1=1}^{l} \frac{(C_{i_3}^{(i_1)})^{s}}{Z_{i_3}}  \sum_{i_2=1}^{l} \frac{A_{i_3}^{(i_1,i_2)}}{C_{i_3}^{(i_1)}}\nonumber\\
 & = &
\sum_{i_3=1}^{l}  \gamma_{00}(i_3)  \mE_{{\mathcal U}_1}\frac{Z_{i_3}^{\m_1}}{\mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}}  \nonumber \\
 & = &
\sum_{i_3=1}^{l}  \gamma_{00}(i_3)   \nonumber \\
 & = & 1,
 \end{eqnarray}
where the fourth equality follows by the definitions of $Z_{i_3}$ and $C_{i_3}^{(i_1)}$  from (\ref{eq:genanal7}). Keeping in mind that one trivially has $\gamma_{01}^{(1)}\geq 0$, (\ref{eq:genAanal19f}) ensures that $\gamma_{01}^{(1)}$ is indeed a measure. The proofs for other $\gamma$'s are identical and we skip them. As a convention, $\langle \cdot \rangle_a$ will denote the average with respect to measure $a$. Additionally, since each $\gamma$ measure (and $\Phi(\cdot)$ operator) defined above are also functions of $t$, all functions that depend on them will be functions of $t$ as well. We skip stating this explicitly to lighten the notation and facilitate writing.

Utilizing (\ref{eq:genAanal19e1}) we can rewrite (\ref{eq:liftgenAanal19d}) as
\begin{eqnarray}\label{eq:liftgenAanal19g}
\sum_{i_1=1}^{l}\sum_{i_2=1}^{l}\sum_{j=1}^{m} \lp
\sum_{i_3=1}^{l} \frac{
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}    }{ \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp   }
 \frac{\beta_{i_1}\Theta_1}{\sqrt{1-t}}\rp
&  = & \beta^2 \Bigg ( \Bigg. \langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(1)}}
\nonumber \\
& &
+  (s-1) \langle \|\x^{(i_1)}\|_2^2(\y^{(p_2)})^T\y^{(i_2)}\rangle_{\gamma_{02}^{(1)}} \Bigg ) \Bigg. .
