 \hspace{-.05in} \times
 \frac{Z_{i_3}^{\m_1}}{\mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}} \sum_{i_1=1}^{l}\frac{(C_{i_3}^{(i_1)})^s}{Z_{i_3}}\sum_{i_2=1}^{l}
\frac{A_{i_3}^{(i_1,i_2)}}{C_{i_3}^{(i_1)}} \nonumber \\
