 \hspace{-.05in}
\times
 \sum_{p_1=1}^{l} \frac{(C_{i_3}^{(p_1)})^s}{Z_{i_3}}\sum_{p_2=1}^{l}\frac{A_{i_3}^{(p_1,p_2)}}{C_{i_3}^{(p_1)}} \beta_{i_1}\beta_{p_1}(\y^{(p_2)})^T\y^{(i_2)} \Bigg.\Bigg)\nonumber \\
