 \times \lp \mE_{G,{\mathcal U}_2} \langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(1)}} +  (s-1)\mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2^2(\y^{(p_2)})^T\y^{(i_2)}\rangle_{\gamma_{02}^{(1)}} \rp \nonumber \\
& & - (\p_0-\p_1)s\beta^2(1-\m_1)\langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2(\y^{(p_2)})^T\y^{(i_2)} \rangle_{\gamma_{1}^{(1)}}.
\end{eqnarray}








