& = & \mE_{G,{\mathcal U}_2} \lp
\sum_{i_3=1}^{l} \frac{
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}    }{ \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp   }
\mE_{{\mathcal U}_1} \sum_{p_1=1}^{l}\mE_{{\mathcal U}_1}(\u^{(i_1,3,1)}\u^{(p_1,3,1)}) \frac{d}{d\u^{(p_1,3,1)}}\lp\frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)}}{Z_{i_3}^{1-\m_1}}\rp\rp \nonumber \\
& = &  \mE_{G,{\mathcal U}_2} \lp
\sum_{i_3=1}^{l} \frac{(\q_0-\q_1)
