& & \times
\Bigg ( \Bigg.
\sum_{p_3=1}^{l}
\frac{\lp \mE_{{\mathcal U}_1} Z_{p_3}^{\m_1} \rp^{p}}{\lp
\sum_{p_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{p_3}^{\m_1} \rp^p  \rp}
\nonumber \\
& & \times
\mE_{{\mathcal U}_1}  \frac{Z_{p_3}^{\m_1}}{\mE_{{\mathcal U}_1} Z_{p_3}^{\m_1}} \sum_{p_1=1}^{l}  \frac{(C_{p_3}^{(p_1)})^s}{Z_{p_3}}\sum_{p_2=1}^{l}
\frac{A_{p_3}^{(p_1,p_2)}}{C_{p_3}^{(p,1)}}\beta_{p_1}\y_j^{(p_2)}   \Bigg . \Bigg ) \Bigg. \Bigg)\nonumber\\
& = & -s\p_1\m_1 p \mE_{G,{\mathcal U}_2} \langle \beta_{p_1}\beta_{i_1}(\y^{(p_2)})^T\y^{(i_2)} \rangle_{\gamma_{21}^{(1)}} \nonumber \\
& = & -s\beta^2\p_1\m_1 p \mE_{G,{\mathcal U}_2} \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2(\y^{(p_2)})^T\y^{(i_2)} \rangle_{\gamma_{21}^{(1)}}.
\end{eqnarray}

To determine $T_{2,1,j}^e$ we start by observing
\begin{eqnarray}\label{eq:genDanal24aa0}
 \frac{d}{d\u_j^{(2,2)}}\lp
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}
\rp
=
 (p-1) \lp  \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-2}
\mE_{{\mathcal U}_1}\frac{d Z_{i_3}^{\m_1}}{d\u_j^{(2,2)}}.
\end{eqnarray}
Combining (\ref{eq:genDanal24aa0}) and (\ref{eq:genDanal21}) one then finds
\begin{eqnarray}\label{eq:genDanal24aa1}
 \frac{d}{d\u_j^{(2,2)}}\lp
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}
\rp
=
(p-1)  \lp  \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-2}
\mE_{{\mathcal U}_1}
\frac{\m_1}{Z_{i_3}^{1-\m_1}}s  \sum_{p_1=1}^{l}  (C_{i_3}^{(p_1)})^{s-1}\sum_{p_2=1}^{l}
\beta_{p_1}A_{i_3}^{(p_1,p_2)}\y_j^{(p_2)}\sqrt{1-t}.
\end{eqnarray}
Plugging (\ref{eq:genDanal24aa1}) in  (\ref{eq:genDanal19b})  first gives
\begin{eqnarray}\label{eq:genDanal24ab0}
T_{2,1,j}^e &  = &
\mE_{G,{\mathcal U}_2,{\mathcal U}_1}
\Bigg ( \Bigg.
\sum_{i_3=1}^{l}
\frac{\p_1 \lp(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)}\y_j^{(i_2)} \rp}{Z_{i_3}^{1-\m_1}  \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp  }
\nonumber \\
& & \times
(p-1)  \lp  \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-2}
\mE_{{\mathcal U}_1}
\frac{\m_1}{Z_{i_3}^{1-\m_1}}s  \sum_{p_1=1}^{l}  (C_{i_3}^{(p_1)})^{s-1}\sum_{p_2=1}^{l}
\beta_{p_1}A_{i_3}^{(p_1,p_2)}\y_j^{(p_2)}\sqrt{1-t}
\Bigg . \Bigg )
\nonumber \\
&  = &
\p_1 s \m_1 (p-1)\mE_{G,{\mathcal U}_2 }
\Bigg ( \Bigg.
\sum_{i_3=1}^{l}
\frac{\lp  \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p }
{ \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp  }
\nonumber \\
& & \times
\mE_{{\mathcal U}_1}
\frac{Z_{i_3}^{\m_1}}{ \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} }
\frac{ \lp (C_{i_3}^{(i_1)})^{s} A_{i_3}^{(i_1,i_2)}\y_j^{(i_2)} \rp}{Z_{i_3} C_{i_3}^{(i_1)} }
\nonumber \\
& & \times
\mE_{{\mathcal U}_1}
\frac{Z_{i_3}^{\m_1}}{ \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} }   \sum_{p_1=1}^{l}  \frac{(C_{i_3}^{(p_1)})^{s} }{Z_{i_3}}\sum_{p_2=1}^{l}
\frac{ \beta_{p_1}A_{i_3}^{(p_1,p_2)}\y_j^{(p_2)}\sqrt{1-t} } { C_{i_3}^{(p_1)} }
\Bigg . \Bigg ),
\end{eqnarray}
and then
\begin{eqnarray}\label{eq:genDanal24ab1}
\sum_{i_1=1}^{l}\sum_{i_2=1}^{l} \beta_{i_1}\|\y^{(i_2)}\|_2\frac{T_{2,2}^e}{\sqrt{1-t}}
     &  = &     s\beta^2\p_1\m_1 (p-1) \mE_{G,{\mathcal U}_2} \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2(\y^{(p_2)})^T\y^{(i_2)} \rangle_{\gamma_{22}^{(1)}}.
\end{eqnarray}
Combining  (\ref{eq:genDanal19a}), (\ref{eq:genDanal19b1}), (\ref{eq:genDanal24}), and (\ref{eq:genDanal24ab1}) we obtain
\begin{eqnarray}\label{eq:genDanal25}
 \sum_{i_1=1}^{l}  \sum_{i_2=1}^{l} \sum_{j=1}^{m}  \beta_{i_1}\frac{T_{2,1,j}}{\sqrt{1-t}}& = & \p_1\beta^2
 \lp \mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(1)}} +  (s-1)\mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2^2(\y^{(p_2)})^T\y^{(i_2)}\rangle_{\gamma_{02}^{(1)}} \rp\nonumber \\
& & - \p_1s\beta^2(1-\m_1)\mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2(\y^{(p_2)})^T\y^{(i_2)} \rangle_{\gamma_{1}^{(1)}}\nonumber \\
 &   &
  -s\beta^2\p_1\m_1\mE_{G,{\mathcal U}_2} \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2(\y^{(p_2)})^T\y^{(i_2)} \rangle_{\gamma_{21}^{(1)}}
  \nonumber
  \\
   &   &
   +  s\beta^2\p_1\m_1 (p-1) \mE_{G,{\mathcal U}_2} \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2(\y^{(p_2)})^T\y^{(i_2)} \rangle_{\gamma_{22}^{(1)}}.
\end{eqnarray}






%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\underline{\textbf{\emph{Determining}} $T_{2,2}$}
\label{sec:hand1T22}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

As earlier, we apply the Gaussian integration by parts to find
\begin{eqnarray}\label{eq:liftgenEanal20}
T_{2,2} \hspace{-.05in} & = &  \mE_{G,{\mathcal U}_2} \lp
\sum_{i_3=1}^{l} \frac{
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}    }{ \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp   }
\mE_{{\mathcal U}_1}\frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)} \u^{(i_1,3,2)}}{Z_{i_3}^{1-\m_1}} \rp \nonumber \\
& = &  \mE_{G,{\mathcal U}_2,{\mathcal U}_1} \lp
\sum_{i_3=1}^{l} \frac{
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}    }{ \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp   }
 \frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)} \u^{(i_1,3,2)}}{Z_{i_3}^{1-\m_1}}\rp\nonumber \\
& = & \mE_{G,{\mathcal U}_1} \lp
\sum_{i_3=1}^{l}
\mE_{{\mathcal U}_2} \lp \sum_{p_1=1}^{l}\mE_{{\mathcal U}_2}(\u^{(i_1,3,2)}\u^{(p_1,3,2)}) \frac{d}{d\u^{(p_1,3,2)}}\lp\frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)  } \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1} }  {Z_{i_3}^{1-\m_1}   \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp  }
   \rp\rp\rp \nonumber \\
& = & \mE_{G,{\mathcal U}_2,{\mathcal U}_1} \lp
\sum_{i_3=1}^{l} \frac{\q_1
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}    }{ \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp   }
  \sum_{p_1=1}^{l} \frac{\beta^2(\x^{(i_1)})^T\x^{(p_1)}}{\beta_{i_1}\beta_{p_1}}
  \frac{d}{d\u^{(p_1,3,2)}}\lp\frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)}}{Z_{i_3}^{1-\m_1}}\rp\rp \nonumber \\
& & + \mE_{G,{\mathcal U}_2,{\mathcal U}_1} \Bigg ( \Bigg.
\sum_{i_3=1}^{l}
\frac{ \q_1\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}   (C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)}}{Z_{i_3}^{1-\m_1}}
\nonumber \\
& & \times
  \sum_{p_1=1}^{l} \frac{\beta^2(\x^{(i_1)})^T\x^{(p_1)}}{\beta_{i_1}\beta_{p_1}}
     \frac{d}{d\u^{(p_1,3,2)}}\lp\frac{1}{ \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp  }  \rp  \Bigg ) \Bigg. \nonumber \\
& & + \mE_{G,{\mathcal U}_2,{\mathcal U}_1} \lp
\sum_{i_3=1}^{l}
\frac{ \q_1 (C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)}}{\lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp  Z_{i_3}^{1-\m_1}}
  \sum_{p_1=1}^{l} \q_1\frac{\beta^2(\x^{(i_1)})^T\x^{(p_1)}}{\beta_{i_1}\beta_{p_1}}\frac{d}{d\u^{(p_1,3,2)}}\lp  \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}  \rp\rp, \nonumber \\
 \end{eqnarray}
where we recall on
\begin{eqnarray}\label{eq:genEanal19c}
\mE_{{\mathcal U}_2}(\u^{(i_1,3,2)}\u^{(p_1,3,2)}) & = & \q_1\frac{(\x^{(i_1)})^T\x^{(p_1)}}{\|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2}
=\q_1\frac{\beta^2(\x^{(i_1)})^T\x^{(p_1)}}{\beta_{i_1}\beta_{p_1}}, \nonumber \\
\mE_{{\mathcal U}_2}(\u^{(i_1,3,1)}\u^{(p_1,3,1)}) & = & (\q_0-\q_1)\frac{(\x^{(i_1)})^T\x^{(p_1)}}{\|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2}=(\q_0-\q_1)\frac{\beta^2(\x^{(i_1)})^T\x^{(p_1)}}{\beta_{i_1}\beta_{p_1}}.
\end{eqnarray}
One can then rewrite (\ref{eq:liftgenEanal20}) as
\begin{eqnarray}\label{eq:genEanal19a}
T_{2,2}   =   T_{2,2}^{c} +  T_{2,2}^{d} +  T_{2,2}^{e},
\end{eqnarray}
where
\begin{eqnarray}\label{eq:genEanal19b}
T_{2,2}^c &  = &
\mE_{G,{\mathcal U}_2,{\mathcal U}_1} \lp
\sum_{i_3=1}^{l} \frac{\q_1
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}    }{ \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp   }
  \sum_{p_1=1}^{l} \frac{\beta^2(\x^{(i_1)})^T\x^{(p_1)}}{\beta_{i_1}\beta_{p_1}}
  \frac{d}{d\u^{(p_1,3,2)}}\lp\frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)}}{Z_{i_3}^{1-\m_1}}\rp\rp \nonumber \\
T_{2,2}^d &  = & \mE_{G,{\mathcal U}_2,{\mathcal U}_1} \Bigg ( \Bigg.
\sum_{i_3=1}^{l}
\frac{ \q_1\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}   (C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)}}{Z_{i_3}^{1-\m_1}}
\nonumber \\
& & \times
  \sum_{p_1=1}^{l} \frac{\beta^2(\x^{(i_1)})^T\x^{(p_1)}}{\beta_{i_1}\beta_{p_1}}
     \frac{d}{d\u^{(p_1,3,2)}}\lp\frac{1}{ \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp  }  \rp  \Bigg ) \Bigg. \nonumber \\
T_{2,2}^e &  = &
\mE_{G,{\mathcal U}_2,{\mathcal U}_1} \lp
\sum_{i_3=1}^{l}
\frac{ \q_1 (C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)}}{\lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp  Z_{i_3}^{1-\m_1}}
  \sum_{p_1=1}^{l} \frac{\beta^2(\x^{(i_1)})^T\x^{(p_1)}}{\beta_{i_1}\beta_{p_1}} \frac{d}{d\u^{(p_1,3,2)}}\lp  \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}  \rp\rp. \nonumber \\
\end{eqnarray}
Since scaling $T_{2,2}^c$ by $\q_1$ produces the term structurally identical to the one considered in the second part of Section \ref{sec:hand1T11} scaled by $(\q_0-\q_1)$, one can immediately utilize (\ref{eq:liftgenBanal20b}) and write
 \begin{eqnarray}\label{eq:genEanal19c1}
\sum_{i_1=1}^{l}\sum_{i_2=1}^{l} \beta_{i_1}\|\y^{(i_2)}\|_2 \frac{T_{2,2}^c}{\sqrt{1-t}} & = & \q_1 \beta^2 \Bigg( \Bigg. \mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(1)}} \nonumber \\
& & +   (s-1)\mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2^2 \|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2\rangle_{\gamma_{02}^{(1)}}\Bigg.\Bigg)   \nonumber \\
& & - \q_1s\beta^2(1-\m_1)\mE_{G,{\mathcal U}_2}\langle (\x^{(p_1)})^T\x^{(i_1)}\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2 \rangle_{\gamma_{1}^{(1)}}.
\end{eqnarray}

To determining  $T_{2,2}^d$  we first observe
\begin{eqnarray}\label{eq:genEanal20}
\frac{d}{d\u^{(p_1,3,2)}}\lp\frac{1}{ \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp  } \rp   & = &
 -p\sum_{p_3=1}^{l} \frac{
\lp \mE_{{\mathcal U}_1} Z_{p_3}^{\m_1} \rp^{p-1}}{\lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p  \rp^2}
\mE_{{\mathcal U}_1}\frac{dZ_{p_3}^{\m_1}}{d\u^{(p_1,3)}}.
\end{eqnarray}
From \cite{Stojnicnflgscompyx23}'s (52) we also have
\begin{eqnarray}\label{eq:genEanal21}
\frac{dZ_{p_3}^{\m_1}}{d\u^{(p_1,3,2)}} & = & \frac{\m_1}{Z_{p_3}^{1-\m_1}} s  (C_{p_3}^{(p_1)})^{s-1}\sum_{p_2=1}^{l}
\beta_{p_1}A_{p_3}^{(p_1,p_2)}\|\y^{(p_2)}\|_2\sqrt{1-t}.
\end{eqnarray}
A combination of (\ref{eq:genEanal20}) and (\ref{eq:genEanal21}) then gives
\begin{eqnarray}\label{eq:genEanal22}
\frac{d}{d\u^{(p_1,3,2)}}\lp\frac{1}{ \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp  } \rp   & = &
 -p\sum_{p_3=1}^{l} \frac{
\lp \mE_{{\mathcal U}_1} Z_{p_3}^{\m_1} \rp^{p-1}}{\lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p  \rp^2}
 \nonumber \\
 & & \times \frac{\m_1}{Z_{p_3}^{1-\m_1}} s  (C_{p_3}^{(p_1)})^{s-1}\sum_{p_2=1}^{l}
\beta_{p_1}A_{p_3}^{(p_1,p_2)}\|\y^{(p_2)}\|_2\sqrt{1-t}.
\end{eqnarray}
Plugging  (\ref{eq:genEanal22}) back into the expression for $T_{2,2}^d$ given in  (\ref{eq:genEanal19b}) we also have
\begin{eqnarray}\label{eq:genEanal23}
 T_{2,2}^d &  = & -\q_1 p\mE_{G,{\mathcal U}_2,{\mathcal U}_1} \Bigg( \Bigg.\sum_{i_3=1}^{l}
\frac{ \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}   (C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)}}{Z_{i_3}^{1-\m_1}}
  \sum_{p_1=1}^{l}  \frac{\beta^2(\x^{(i_1)})^T\x^{(p_1)}}{\beta_{i_1}\beta_{p_1}}
   \nonumber \\
 & & \times
 \sum_{p_3=1}^{l} \frac{
\lp \mE_{{\mathcal U}_1} Z_{p_3}^{\m_1} \rp^{p-1}}{\lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p  \rp^2}
 \frac{\m_1}{Z_{p_3}^{1-\m_1}} s  (C_{p_3}^{(p_1)})^{s-1}\sum_{p_2=1}^{l}
\beta_{p_1}A_{p_3}^{(p_1,p_2)}\|\y^{(p_2)}\|_2\sqrt{1-t}  \Bigg. \Bigg) \nonumber \\
&  = & -s\sqrt{1-t}\beta^2\q_1\m_1 p \mE_{G,{\mathcal U}_2,{\mathcal U}_1} \Bigg( \Bigg.
 \sum_{i_3=1}^{l} \frac{
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p}}{\lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p  \rp}
\frac{Z_{i_3}^{\m_1}}{\mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}}
 \frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)}}{Z_{i_3}} \nonumber \\
 & & \times
 \sum_{p_3=1}^{l} \frac{
\lp \mE_{{\mathcal U}_1} Z_{p_3}^{\m_1} \rp^{p}}{\lp
\sum_{p_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{p_3}^{\m_1} \rp^p  \rp}
\frac{Z_{p_3}^{\m_1}}{\mE_{{\mathcal U}_1} Z_{p_3}^{\m_1}}
  \sum_{p_1=1}^{l}
 \frac{(C_{p_3}^{(p_1)})^{s}}{Z_{p_3}}  \sum_{p_2=1}^{l}
\frac{A_{p_3}^{(p_1,p_2)}}{(C_{p_3}^{(p_1)})}\|\y^{(p_2)}\|_2\frac{(\x^{(i_1)})^T\x^{(p_1)}}{\beta_{i_1}} \Bigg. \Bigg),
\end{eqnarray}
and consequently
\begin{eqnarray}\label{eq:genEanal24}
\sum_{i_1=1}^{l}\sum_{i_2=1}^{l} \beta_{i_1}\|\y^{(i_2)}\|_2\frac{T_{2,2}^d}{\sqrt{1-t}}
& = & -s\beta^2\q_1\m_1 p \mE_{G,{\mathcal U}_2} \langle \|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2(\x^{(i_1)})^T\x^{(p_1)}\rangle_{\gamma_{21}^{(1)}}.
\end{eqnarray}


To determine $T_{2,2}^e$ we first note
\begin{eqnarray}\label{eq:genDanal24aa0bb0}
\frac{d}{d\u^{(p_1,3,2)}}\lp  \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}  \rp=
 (p-1) \lp  \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-2}
\mE_{{\mathcal U}_1}\frac{d Z_{i_3}^{\m_1}}{d\u^{(p_1,3,2)}}.
\end{eqnarray}
Combining (\ref{eq:genDanal24aa0}) and  (\ref{eq:genEanal21})  one finds
\begin{equation}\label{eq:genDanal24aa1bb1}
\frac{d}{d\u^{(p_1,3,2)}}\lp  \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}  \rp
=
(p-1)  \lp  \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-2}
\mE_{{\mathcal U}_1}
\frac{\m_1}{Z_{i_3}^{1-\m_1}} s  (C_{i_3}^{(p_1)})^{s-1}\sum_{p_2=1}^{l}
\beta_{p_1}A_{i_3}^{(p_1,p_2)}\|\y^{(p_2)}\|_2\sqrt{1-t}.
\end{equation}
Plugging  (\ref{eq:genEanal22}) back into the expression for $T_{2,2}^e$ given in  (\ref{eq:genEanal19b}) we first obtain
\begin{eqnarray}\label{eq:genDanal24aa1bb2}
T_{2,2}^e &  = &
\mE_{G,{\mathcal U}_2,{\mathcal U}_1} \Bigg ( \Bigg.
\sum_{i_3=1}^{l}
\frac{ \q_1 (C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)}}{\lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp  Z_{i_3}^{1-\m_1}}
  \sum_{p_1=1}^{l} \frac{\beta^2(\x^{(i_1)})^T\x^{(p_1)}}{\beta_{i_1}\beta_{p_1}}
  \nonumber \\
  & & \times
  (p-1)  \lp  \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-2}
\mE_{{\mathcal U}_1}
\frac{\m_1}{Z_{i_3}^{1-\m_1}} s  (C_{i_3}^{(p_1)})^{s-1}\sum_{p_2=1}^{l}
\beta_{p_1}A_{i_3}^{(p_1,p_2)}\|\y^{(p_2)}\|_2\sqrt{1-t}
    \Bigg ) \Bigg.   \nonumber \\
    &  = & s\beta^2\q_1\m_1 (p-1)
\mE_{G,{\mathcal U}_2} \Bigg ( \Bigg.
\sum_{i_3=1}^{l}
\frac{    \lp  \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p   }{\lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp  }
\mE_{{\mathcal U}_1}
\frac{Z_{i_3}^{\m_1}} { \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}}
\frac{     (C_{i_3}^{(i_1)})^{s}  }  {   Z_{i_3}  }
\frac{     A_{i_3}^{(i_1,i_2)} }  {  C_{i_3}^{(i_1)}  }
  \nonumber \\
  & & \times
\mE_{{\mathcal U}_1}
\frac{Z_{i_3}^{\m_1}} { \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}}
  \sum_{p_1=1}^{l}
\frac{  (C_{i_3}^{(p_1)})^{s} }{Z_{i_3}}
  \sum_{p_2=1}^{l}
  \frac{ A_{i_3}^{(p_1,p_2)}\|\y^{(p_2)}\|_2
(\x^{(i_1)})^T\x^{(p_1)} \sqrt{1-t} }{   C_{i_3}^{(p_1)}
 \beta_{i_1} }
    \Bigg ) \Bigg. ,
\end{eqnarray}
and
\begin{eqnarray}\label{eq:genDanal24aa1bb3}
\sum_{i_1=1}^{l}\sum_{i_2=1}^{l} \beta_{i_1}\|\y^{(i_2)}\|_2\frac{T_{2,2}^e}{\sqrt{1-t}}
     &  = &     s\beta^2\q_1\m_1 (p-1) \mE_{G,{\mathcal U}_2} \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2(\y^{(p_2)})^T\y^{(i_2)} \rangle_{\gamma_{22}^{(1)}}.
\end{eqnarray}
A combination of (\ref{eq:genEanal19a}), (\ref{eq:genEanal19c1}),
(\ref{eq:genEanal24}), and (\ref{eq:genDanal24aa1bb3})  gives
\begin{eqnarray}\label{eq:genEanal25}
\sum_{i_1=1}^{l}\sum_{i_2=1}^{l} \beta_{i_1}\|\y^{(i_2)}\|_2\frac{T_{2,2}}{\sqrt{1-t}} &  = &
\q_1\beta^2 \Bigg( \Bigg. \mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(1)}} \nonumber \\
& & +  (s-1)\mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2^2 \|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2\rangle_{\gamma_{02}^{(1)}}\Bigg.\Bigg) \nonumber \\
& & - \q_1s\beta^2(1-\m_1)\mE_{G,{\mathcal U}_2}\langle (\x^{(p_1)})^T\x^{(i_1)}\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2 \rangle_{\gamma_{1}^{(1)}} \nonumber \\
&  & -s\beta^2\q_1\m_1 p \mE_{G,{\mathcal U}_2} \langle \|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2(\x^{(i_1)})^T\x^{(p_1)}\rangle_{\gamma_{21}^{(1)}}
\nonumber \\
& &
+ s\beta^2\q_1\m_1 (p-1) \mE_{G,{\mathcal U}_2} \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2(\y^{(p_2)})^T\y^{(i_2)} \rangle_{\gamma_{22}^{(1)}}.
\end{eqnarray}




