\underline{\textbf{\emph{Determining}} $T_{2,3}$}
\label{sec:hand1T23}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

After Gaussian integration by parts we find
\begin{eqnarray}\label{eq:genFanal21}
T_{2,3} & = &  \mE_{G,{\mathcal U}_2}\lp
\sum_{i_3=1}^{l} \frac{
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}    }{ \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp   }
\mE_{{\mathcal U}_1}\frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)} u^{(4,2)}}{Z_{i_3}^{1-\m_1}} \rp \nonumber \\
& = & \mE_{G,{\mathcal U}_1} \lp  \mE_{{\mathcal U}_2} \lp\mE_{{\mathcal U}_2} (u^{(4,2)}u^{(4,2)})\lp\frac{d}{du^{(4,2)}} \lp\frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)}}{Z_{i_3}^{1-\m_1}}
\frac{
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}    }{ \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp   }
\rp \rp\rp\rp \nonumber \\
& = & \p_1\q_1\mE_{G,{\mathcal U}_2,{\mathcal U}_1} \lp
\sum_{i_3=1}^{l}
\frac{
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}    }{ \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp   }
\lp\frac{d}{du^{(4,2)}} \lp\frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)}}{Z_{i_3}^{1-\m_1}}\rp\rp\rp \nonumber \\
& & + \p_1\q_1\mE_{G,{\mathcal U}_2,{\mathcal U}_1} \lp \sum_{i_3=1}^{l}
 \frac{ \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}     (C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)}}{Z_{i_3}^{1-\m_1}}\lp\frac{d}{du^{(4,2)}} \lp\frac{1}{ \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp } \rp\rp\rp
\nonumber \\
& & + \p_1\q_1\mE_{G,{\mathcal U}_2,{\mathcal U}_1} \lp \sum_{i_3=1}^{l}
 \frac{     (C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)}}{  \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp    Z_{i_3}^{1-\m_1}}\lp\frac{d}{du^{(4,2)}} \lp   \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}   \rp\rp\rp.
\end{eqnarray}
Following the methodology presented above, we find it useful to rewrite (\ref{eq:genFanal21}) as
\begin{eqnarray}\label{eq:genFanal22}
T_{2,3} & = & T_{2,3}^c + T_{2,3}^d +T_{2,3}^e,
\end{eqnarray}
where
\begin{eqnarray}\label{eq:genFanal23}
T_{2,3}^c & = &  \p_1\q_1\mE_{G,{\mathcal U}_2,{\mathcal U}_1} \lp
\sum_{i_3=1}^{l}
\frac{
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}    }{ \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp   }
\lp\frac{d}{du^{(4,2)}} \lp\frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)}}{Z_{i_3}^{1-\m_1}}\rp\rp\rp \nonumber \\
 T_{2,3}^d & = & \p_1\q_1\mE_{G,{\mathcal U}_2,{\mathcal U}_1} \lp \sum_{i_3=1}^{l}
 \frac{ \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}     (C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)}}{Z_{i_3}^{1-\m_1}}   \lp \frac{d}{du^{(4,2)}} \lp\frac{1}{ \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp } \rp\rp\rp
\nonumber \\
 T_{2,3}^e & = &
\p_1\q_1\mE_{G,{\mathcal U}_2,{\mathcal U}_1} \lp \sum_{i_3=1}^{l}
 \frac{     (C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)}}{  \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp    Z_{i_3}^{1-\m_1}}\lp\frac{d}{du^{(4,2)}} \lp   \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}   \rp\rp\rp.
\end{eqnarray}
After recognizing  that $\frac{T_{2,3}^c}{\p_1\q_1}=\frac{T_{1,3}}{\p_0\q_0-\p_1\q_1}$, one, based on (\ref{eq:liftgenCanal21b}), obtains
 \begin{eqnarray}\label{eq:genFanal23b}
\sum_{i_1=1}^{l}\sum_{i_2=1}^{l} \beta_{i_1}\|\y^{(i_2)}\|_2 \frac{T_{2,3}^c}{\sqrt{t}} & = &
\p_1\q_1 \beta^2 \Bigg( \Bigg. \mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(1)}} \nonumber \\
& & \times +   (s-1)\mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2^2 \|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2\rangle_{\gamma_{02}^{(1)}}\Bigg. \Bigg) \nonumber \\
& & - \p_1\q_1 s\beta^2(1-\m_1)\mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2\|\x^{(p_`)}\|_2\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2 \rangle_{\gamma_{1}^{(1)}}.
\end{eqnarray}


To find $T_{2,3}^d$, we first write
\begin{eqnarray}\label{eq:genFanal24}
\frac{d}{du^{(4,2)}} \lp\frac{1}{ \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp } \rp
  & = &
 - p \sum_{p_3=1}^{l} \frac{\lp \mE_{{\mathcal U}_1} Z_{p_3}^{\m_1} \rp^{p-1} } { \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp^2} \mE_{{\mathcal U}_1} \frac{dZ_{p_3}^{\m_1}}{d u^{(4,2)}}
\nonumber \\
& = &  - p \sum_{p_3=1}^{l} \frac{\lp \mE_{{\mathcal U}_1} Z_{p_3}^{\m_1} \rp^{p-1} } { \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp^2}\mE_{{\mathcal U}_1} \frac{\m_1}{Z_{p_3}^{1-\m_1}}\frac{dZ_{p_3}}{d u^{(4,2)}}.
\end{eqnarray}
From \cite{Stojnicnflgscompyx23}'s (62) we also have
\begin{equation}\label{eq:genFanal25}
\frac{dZ_{p_3}}{du^{(4,2)}}=\frac{d\sum_{p_1=1}^{l}  (C_{p_3}^{(p_1)})^s}{du^{(4,2)}}
=s \sum_{p_1=1}^{l} (C_{p_3}^{(p_1)})^{s-1}\sum_{p_2=1}^{l}\frac{d(A_{p_3}^{(p_1,p_2)})}{du^{(4,2)}}
=
s \sum_{p_1=1}^{l} (C_{p_3}^{(p_1)})^{s-1}\sum_{p_2=1}^{l}
\beta_{p_1}A_{p_3}^{(p_1,p_2)}\|\y^{(p_2)}\|_2\sqrt{t}.
\end{equation}
A combination of (\ref{eq:genFanal24}) and (\ref{eq:genFanal25}) gives
\begin{eqnarray}\label{eq:genFanal26}
\frac{d}{du^{(4,2)}} \lp\frac{1}{ \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp } \rp
 & = &  - p \sum_{p_3=1}^{l} \frac{\lp \mE_{{\mathcal U}_1} Z_{p_3}^{\m_1} \rp^{p-1} } { \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp^2}\mE_{{\mathcal U}_1} \frac{\m_1}{Z_{p_3}^{1-\m_1}}  \nonumber \\
 & & \times s \sum_{p_1=1}^{l} (C_{p_3}^{(p_1)})^{s-1}\sum_{p_2=1}^{l}
\beta_{p_1}A_{p_3}^{(p_1,p_2)}\|\y^{(p_2)}\|_2\sqrt{t}.
\end{eqnarray}
Plugging (\ref{eq:genFanal26}) into the expression for $T_{2,3}^d$ from (\ref{eq:genFanal23}) gives
\begin{eqnarray}\label{eq:genFanal27}
T_{2,3}^d   & = & -\p_1\q_1  \mE_{G,{\mathcal U}_2,{\mathcal U}_1} \Bigg( \Bigg.
\sum_{i_3=1}^{l}
 \frac{ \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}     (C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)}}{Z_{i_3}^{1-\m_1}} \nonumber \\
& & \times p \sum_{p_3=1}^{l} \frac{\lp \mE_{{\mathcal U}_1} Z_{p_3}^{\m_1} \rp^{p-1} } { \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp^2 }
\mE_{{\mathcal U}_1} \frac{\m_1}{Z_{p_3}^{1-\m_1}}   s \sum_{p_1=1}^{l} (C_{p_3}^{(p_1)})^{s-1}\sum_{p_2=1}^{l}
\beta_{p_1}A_{p_3}^{(p_1,p_2)}\|\y^{(p_2)}\|_2\sqrt{t}\Bigg. \Bigg) \nonumber \\
& = & -s\sqrt{t}\p_1\q_1\m_1 p \mE_{G,{\mathcal U}_2} \Bigg( \Bigg.
\sum_{p_3=1}^{l} \frac{\lp \mE_{{\mathcal U}_1} Z_{p_3}^{\m_1} \rp^{p} } { \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp }
\mE_{{\mathcal U}_1} \frac{Z^{\m_1}}{\mE_{{\mathcal U}_1} Z^{\m_1}} \frac{(C^{(i_1)})^s}{Z}\frac{A^{(i_1,i_2)}}{(C^{(i_1)})}\nonumber \\
& & \times
\sum_{p_3=1}^{l} \frac{\lp \mE_{{\mathcal U}_1} Z_{p_3}^{\m_1} \rp^{p} } { \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp }
  \mE_{{\mathcal U}_1} \frac{Z^{\m_1}}{\mE_{{\mathcal U}_1} Z^{\m_1}} \sum_{p_1=1}^{l} \frac{(C^{(p_1)})^{s}}{Z}\sum_{p_2=1}^{l}
\frac{A^{(p_1,p_2)}}{(C^{(p_1)})}\beta_{p_1}\|\y^{(p_2)}\|_2\Bigg. \Bigg).
