 & = & -s\beta^2\p_1\q_1\m_1 p \mE_{G,{\mathcal U}_2} \langle\|\x^{(i_2)}\|_2\|\x^{(p_2)}\|_2\|\y^{(i_2)}\|_2\|\y^{(p_2)} \|_2 \rangle_{\gamma_{21}^{(1)}}.
\end{eqnarray}


To determine $T_{2,3}^e$ we first write
\begin{eqnarray}\label{eq:genDanal24aa0bb0cc0}
\frac{d}{du^{(4,2)}}\lp  \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-1}  \rp=
 (p-1) \lp  \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-2}
\mE_{{\mathcal U}_1}\frac{d Z_{i_3}^{\m_1}}{d u^{(4,2)}}.
