Plugging  (\ref{eq:genDanal24aa1cc1}) back into the expression for $T_{2,3}^e$ given in (\ref{eq:genFanal23}) we further find
\begin{eqnarray}\label{eq:genDanal24aa1cc2}
T_{2,2}^e &  = &
\p_1\q_1 \mE_{G,{\mathcal U}_2,{\mathcal U}_1} \Bigg ( \Bigg.
\sum_{i_3=1}^{l}
 \frac{     (C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)}}{  \lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp    Z_{i_3}^{1-\m_1}}
\nonumber \\
  & & \times
(p-1)  \lp  \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^{p-2}
\mE_{{\mathcal U}_1}
\frac{\m_1}{Z_{i_3}^{1-\m_1}}   s \sum_{p_1=1}^{l} (C_{i_3}^{(p_1)})^{s-1}\sum_{p_2=1}^{l}
\beta_{p_1}A_{i_3}^{(p_1,p_2)}\|\y^{(p_2)}\|_2\sqrt{t}
    \Bigg ) \Bigg.   \nonumber \\
    &  = & s\beta^2\p_1\q_1\m_1 (p-1)
\mE_{G,{\mathcal U}_2} \Bigg ( \Bigg.
\sum_{i_3=1}^{l}
\frac{    \lp  \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p   }{\lp
\sum_{i_3=1}^{l}
\lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} \rp^p \rp  }
\mE_{{\mathcal U}_1}
\frac{Z_{i_3}^{\m_1}} { \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}}
\frac{     (C_{i_3}^{(i_1)})^{s}  }  {   Z_{i_3}  }
\frac{     A_{i_3}^{(i_1,i_2)} }  {  C_{i_3}^{(i_1)}  }
  \nonumber \\
  & & \times
\mE_{{\mathcal U}_1}
\frac{Z_{i_3}^{\m_1}} { \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}}
  \sum_{p_1=1}^{l}
\frac{  (C_{i_3}^{(p_1)})^{s} }{Z_{i_3}}
  \sum_{p_2=1}^{l}
  \frac{ A_{i_3}^{(p_1,p_2)}\|\y^{(p_2)}\|_2
\|\x^{(i_1)}\|_2   \|\x^{(p_1) }\|_2 \sqrt{t} }{   C_{i_3}^{(p_1)}
 \beta_{i_1} }
    \Bigg ) \Bigg. ,
\end{eqnarray}
and then
\begin{eqnarray}\label{eq:genDanal24aa1cc3}
\sum_{i_1=1}^{l}\sum_{i_2=1}^{l} \beta_{i_1}\|\y^{(i_2)}\|_2\frac{T_{2,3}^e}{\sqrt{t}}
     &  = &     s\beta^2 \p_1\q_1\m_1 (p-1) \mE_{G,{\mathcal U}_2} \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2  \|\y^{(p_2)}\|_2    \|\y^{(i_2)}\|_2 \rangle_{\gamma_{22}^{(1)}}.
