& = &
\p_1\q_1\beta^2 \Bigg( \Bigg. \mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(1)}} \nonumber \\
& & +   (s-1)\mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2^2 \|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2\rangle_{\gamma_{02}^{(1)}}\Bigg.\Bigg) \nonumber \\
& & - \p_1\q_1 s\beta^2(1-\m_1)\mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2\|\x^{(p_`)}\|_2\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2 \rangle_{\gamma_{1}^{(1)}} \nonumber \\
&  & -s\beta^2\p_1\q_1\m_1\mE_{G,{\mathcal U}_2} \langle\|\x^{(i_2)}\|_2\|\x^{(p_2)}\|_2\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2   \rangle_{\gamma_{21}^{(1)}}
\nonumber \\
& & +
 s\beta^2 \p_1 \q_1\m_1 (p-1) \mE_{G,{\mathcal U}_2} \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2  \|\y^{(p_2)}\|_2    \|\y^{(i_2)}\|_2 \rangle_{\gamma_{22}^{(1)}}.
