 & & +  \sum_{p_1=1}^{l} \mE_{G} \Bigg.\Bigg(   \frac{   (C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)}\y_j^{(i_2)}}{ \lp
\sum_{i_3=1}^{l}
