& & - (\q_0-\q_1)s\beta^2(1-\m_1)\mE_{G,{\mathcal U}_2}\langle (\x^{(p_1)})^T\x^{(i_1)}\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2 \rangle_{\gamma_{1}^{(1)}}\nonumber \\
&   &+
\q_1\beta^2\lp\mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(1)}} +   (s-1)\mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2^2 \|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2\rangle_{\gamma_{02}^{(1)}}\rp\nonumber \\
& & - \q_1s\beta^2(1-\m_1)\mE_{G,{\mathcal U}_2}\langle (\x^{(p_1)})^T\x^{(i_1)}\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2 \rangle_{\gamma_{1}^{(1)}} \nonumber \\
&  & -s\beta^2\q_1\m_1 p\mE_{G,{\mathcal U}_2} \langle \|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2(\x^{(i_1)})^T\x^{(p_1)}\rangle_{\gamma_{21}^{(1)}} \nonumber \\
&  & +s\beta^2\q_1\m_1 (p-1) \mE_{G,{\mathcal U}_2} \langle \|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2(\x^{(i_1)})^T\x^{(p_1)}\rangle_{\gamma_{22}^{(1)}} \nonumber \\
&  = &
\q_0\beta^2\lp\mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(1)}} +   (s-1)\mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2^2 \|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2\rangle_{\gamma_{02}^{(1)}}\rp\nonumber \\
& & - \q_0s\beta^2(1-\m_1)\mE_{G,{\mathcal U}_2}\langle (\x^{(p_1)})^T\x^{(i_1)}\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2 \rangle_{\gamma_{1}^{(1)}} \nonumber \\
&  & -s\beta^2\q_1\m_1 p \mE_{G,{\mathcal U}_2} \langle \|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2(\x^{(i_1)})^T\x^{(p_1)}\rangle_{\gamma_{21}^{(1)}} \nonumber \\
&  & +s\beta^2\q_1\m_1 (p-1) \mE_{G,{\mathcal U}_2} \langle \|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2(\x^{(i_1)})^T\x^{(p_1)}\rangle_{\gamma_{22}^{(1)}}.
\end{eqnarray}
From (\ref{eq:liftgenCanal21b}) and (\ref{eq:genFanal29}), we have
  \begin{eqnarray}\label{eq:cpt6}
\Omega_3 & = & (\p_0\q_0-\p_1\q_1)\beta^2 \lp \mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(1)}} +   (s-1)\mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2^2 \|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2\rangle_{\gamma_{02}^{(1)}}\rp\nonumber \\
& & - (\p_0\q_0-\p_1\q_1)s\beta^2(1-\m_1)\mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2\|\x^{(p_`)}\|_2\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2 \rangle_{\gamma_{1}^{(1)}}\nonumber \\
&  & +
\p_1\q_1\beta^2\lp\mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(1)}} +   (s-1)\mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2^2 \|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2\rangle_{\gamma_{02}^{(1)}}\rp\nonumber \\
& & - \p_1\q_1 s\beta^2(1-\m_1)\mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2\|\x^{(p_`)}\|_2\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2 \rangle_{\gamma_{1}^{(1)}} \nonumber \\
&  & -s\beta^2\p_1\q_1\m_1 p \mE_{G,{\mathcal U}_2} \mE_{G,{\mathcal U}_2}\langle\|\x^{(i_2)}\|_2\|\x^{(p_2)}\|_2\|\y^{(i_2)}\|_2\|\y^{(p_2)}\rangle_{\gamma_{21}^{(1)}} \nonumber \\
&  & +s\beta^2\p_1\q_1\m_1 (p-1) \mE_{G,{\mathcal U}_2} \mE_{G,{\mathcal U}_2}\langle\|\x^{(i_2)}\|_2\|\x^{(p_2)}\|_2\|\y^{(i_2)}\|_2\|\y^{(p_2)}\rangle_{\gamma_{22}^{(1)}} \nonumber \\
& = &
\p_0\q_0\beta^2\lp\mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(1)}} +   (s-1)\mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2^2 \|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2\rangle_{\gamma_{02}^{(1)}}\rp\nonumber \\
& & - \p_0\q_0 s\beta^2(1-\m_1)\mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2\|\x^{(p_`)}\|_2\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2 \rangle_{\gamma_{1}^{(1)}} \nonumber \\
&  & -s\beta^2\p_1\q_1
\m_1 p \mE_{G,{\mathcal U}_2} \langle\|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2\|\y^{(i_2)}\|_2\|\y^{(p_2)}\rangle_{\gamma_{21}^{(1)}}   \nonumber \\
&  & +s\beta^2\p_1\q_1
\m_1 (p-1) \mE_{G,{\mathcal U}_2} \langle\|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2\|\y^{(i_2)}\|_2\|\y^{(p_2)}\rangle_{\gamma_{12}^{(1)}}.
\end{eqnarray}
Finally, a combination of (\ref{eq:ctp1}) and (\ref{eq:cpt3})-(\ref{eq:cpt6}) gives
\begin{eqnarray}\label{eq:cpt7}
\frac{d\psi(t)}{dt}  & = &       \frac{\mbox{sign}(s)\beta^2}{2\sqrt{n}} \lp \phi_1^{(1)}+\phi_{21}^{(1)} +\phi_{22}^{(1)} +\phi_{01}^{(1)}+\phi_{02}^{(1)}\rp ,
 \end{eqnarray}
where
\begin{eqnarray}\label{eq:cpt8}
\phi_1^{(1)} & = &
-s(1-\m_1)\mE_{G,{\mathcal U}_2} \langle (\p_0\|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2 -(\x^{(p_1)})^T\x^{(i_1)})(\q_0\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2 -(\y^{(p_2)})^T\y^{(i_2)})\rangle_{\gamma_{1}^{(1)}} \nonumber \\
\phi_{21}^{(1)} & = &
-s\m_1 p \mE_{G,{\mathcal U}_2} \langle (\p_1\|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2 -(\x^{(p_1)})^T\x^{(i_1)})(\q_1\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2 -(\y^{(p_2)})^T\y^{(i_2)})\rangle_{\gamma_{21}^{(1)}} \nonumber \\
\phi_{22}^{(1)} & = &
s\m_1 (p-1) \mE_{G,{\mathcal U}_2} \langle (\p_1\|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2 -(\x^{(p_1)})^T\x^{(i_1)})(\q_1\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2 -(\y^{(p_2)})^T\y^{(i_2)})\rangle_{\gamma_{22}^{(1)}} \nonumber \\
\phi_{01}^{(1)} & = & (1-\p_0)(1-\q_0)\mE_{G,{\mathcal U}_2}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(1)}} \nonumber\\
\phi_{02}^{(1)} & = & (s-1)(1-\p_0)\mE_{G,{\mathcal U}_2}\left\langle \|\x^{(i_1)}\|_2^2 \lp\q_0\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2-(\y^{(p_2)})^T\y^{(i_2)}\rp\right\rangle_{\gamma_{02}^{(1)}}. \end{eqnarray}

The following proposition summarizes the above results.
\begin{proposition}
\label{thm:thm1} Consider vector $\p=[\p_0,\p_1,\p_2]$ with $\p_0\geq \p_1\geq \p_2=0$,  vector $\q=[\q_0,\q_1,\q_2]$ with $\q_0\geq \q_1\geq \q_2=0$, and a scalar $\m_1$. For $k\in\{1,2\}$ let $G\in\mR^{m \times n},u^{(4,k)}\in\mR^1,\u^{(2,k)}\in\mR^{m\times 1}$, and $\h^{(k)}\in\mR^{n\times 1}$ be independent Gaussian objects with  i.i.d. zero-mean components.  Let the variances of the elements of $G$, $u^{(4,1)}$, $u^{(4,2)}$, $\u^{(2,1)}$, $\u^{(2,2)}$, $\h^{(1)}$, and $\h^{(2)}$ be $1$, $\p_0\q_0-\p_1\q_1$, $\p_1\q_1$, $\p_0-\p_1$, $\p_1$, $\q_0-\q_1$, and $\q_1$, respectively. Let ${\mathcal U}_k=[u^{(4,k)},\u^{(2,k)},\h^{(k)}]$ and  assume that sets ${\mathcal X}=\{\x^{(1)},\x^{(2)},\dots,\x^{(l)}\}$, $\bar{{\mathcal X}}=\{\bar{\x}^{(1)},\bar{\x}^{(2)},\dots,\bar{\x}^{(l)}\}$,  and  ${\mathcal Y}=\{\y^{(1)},\y^{(2)},\dots,\y^{(l)}\}$ where $\x^{(i)}, \bar{\x}^{(i)}\in \mR^{n}$ and $\y^{(i)}\in \mR^{m}$, $1\leq i\leq l$ are given. Let $p,\beta\geq 0$ and $s$ be real numbers and let $f_{\bar{\x}^{(i)}}(\cdot) : \mR^n  \rightarrow \mR$ be a given function. Consider 
\begin{equation}\label{eq:prop1eq1}
\psi( t)  =  \mE_{G,{\mathcal U}_2} \frac{1}{p|s|\sqrt{n}\m_1}
\log \lp  \sum_{i_3=1}^{l}  \lp  \mE_{{\mathcal U}_1} \lp \sum_{i_1=1}^{l}\lp\sum_{i_2=1}^{l}e^{\beta D_0^{(i_1,i_2,i_3 )}} \rp^{s}\rp^{\m_1} \rp^p \rp,
\end{equation}
where
\begin{eqnarray}\label{eq:prop1eq2}
 D_0^{(i_1,i_2,i_3)} & \triangleq & \sqrt{t}(\y^{(i_2)})^T
 G\x^{(i_1)}+\sqrt{1-t}\|\x^{(i_1)}\|_2 (\y^{(i_2)})^T(\u^{(2,1)}+\u^{(2,2)})\nonumber \\
 & & +\sqrt{t}\|\x^{(i_1)}\|_2\|\y^{(i_2)}\|_2(u^{(4,1)}+u^{(4,2)}) +\sqrt{1-t}\|\y^{(i_2)}\|_2(\h^{(1)}+\h^{(2)})^T\x^{(i_1)}
 + f_{\bar{\x}^{(i_3)} } ( \x^{(i_1)}  ). \nonumber \\
 \end{eqnarray}
Then
\begin{eqnarray}\label{eq:prop1eq3}
\frac{d\psi(t)}{dt}  & = &   \frac{\mbox{sign}(s)\beta^2}{2\sqrt{n}} \lp \phi_1^{(1)}+\phi_{21}^{(1)} +\phi_{22}^{(1)} +\phi_{01}^{(1)}+\phi_{02}^{(1)}\rp,
 \end{eqnarray}
where $\phi$'s are as in (\ref{eq:cpt8}).
\end{proposition}
\begin{proof}
  Follows immediately as a consequence of the above presentation.
\end{proof}




























































































































































































































