\section{Moving from the first to the second level of full lifting}
\label{sec:seclev}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In this section, we discuss how the first level results presented above extend to the second level. All key concepts needed for this extension are already present in Section \ref{sec:gencon}. However, one has to be very careful as to how to use them. Also, since the move from the first to the second level is pretty much repeated successively later on as one moves to higher levels,  we proceed very carefully and formalize all general steps that can then readily be recalled on and utilized on higher levels. As usual, to facilitate the exposition, we try to parallel the analytical methodology of Section \ref{sec:gencon} as closely as possible. On occasion and when circumstances allow, we avoid unnecessary repetitions and proceed at a bit faster pace.

We again consider vectors $\p$ and $\q$ but this time $\p=[\p_0,\p_1,\p_2,\p_3]$ with $\p_0\geq \p_1\geq \p_2\geq \p_3=0$ and $\q=[\q_0,\q_1,\q_2,\q_3]$ with $\q_0\geq \q_1\geq \q_2\geq \q_3 = 0$. In addition to  $G\in \mR^{m\times n}$ with i.i.d. standard normal elements we now have random variables $u^{(4,1)}\sim {\mathcal N}(0,\p_0\q_0-\p_1\q_1)$, $u^{(4,2)}\sim {\mathcal N}(0,\p_1\q_1-\p_2\q_2)$, and $u^{(4,3)}\sim {\mathcal N}(0,\p_2\q_2)$ that are independent of $G$ and among themselves. We now have a vector $\m=[\m_1,\m_2]$ and the following interpolating function $\psi(\cdot)$
\begin{equation}\label{eq:lev2genanal3}
\psi(t)  =  \mE_{G,{\mathcal U}_3} \frac{1}{p|s|\sqrt{n}\m_2} \log \lp \mE_{{\mathcal U}_2}\lp
\lp
\sum_{i_3=1}^{l}
\lp
 \mE_{{\mathcal U}_1}  Z_{i_3}^{\m_1}
\rp^p
\rp^{\frac{\m_2}{\m_1}}\rp\rp,
\end{equation}
with
\begin{eqnarray}\label{eq:lev2genanal3a}
Z_{i_3} & \triangleq & \sum_{i_1=1}^{l}\lp\sum_{i_2=1}^{l}e^{\beta D_0^{(i_1,i_2,i_3)}} \rp^{s} \nonumber \\
 D_0^{(i_1,i_2,i_3)} & \triangleq & \sqrt{t}(\y^{(i_2)})^T
 G\x^{(i_1)}+\sqrt{1-t}\|\x^{(i_1)}\|_2 (\y^{(i_2)})^T(\u^{(2,1)}+\u^{(2,2)}+\u^{(2,3)}  )\nonumber \\
 & & +\sqrt{t}\|\x^{(i_1)}\|_2\|\y^{(i_2)}\|_2(u^{(4,1)}+u^{(4,2)}+u^{(4,3)}  ) +\sqrt{1-t}\|\y^{(i_2)}\|_2(\h^{(1)}+\h^{(2)}+\h^{(3)}  )^T\x^{(i_1)}
\nonumber \\
& &  + f_{\bar{\x}^{(i_3)}} ( \x^{(i_1)}  ),
 \end{eqnarray}
 and ${\mathcal U}_k=[u^{(4,k)},\u^{(2,k)},\h^{(2k)}]$, $k\in\{1,2,3\}$. In (\ref{eq:lev2genanal3})
 and (\ref{eq:lev2genanal3a}), $\u^{(2,1)}$, $\u^{(2,2)}$, and $\u^{(2,3)}$  are $m$ dimensional Gaussians with variances $\p_0-\p_1$, $\p_1-\p_2$, and , $\p_2$, respectively. Analogously,  $\h^{(1)}$, $\h^{(2)}$, and $\h^{(3)}$ are $n$ dimensional Gaussians with variances $\q_0-\q_1$, $\q_1-\q_2$, and $\q_2$, respectively. All random quantities are zero-mean and independent among themselves. Following the convention established in (\ref{eq:genanal4}), we set
\begin{eqnarray}\label{eq:lev2genanal4}
\bar{\u}^{(i_1,1)} & =  & \frac{G\x^{(i_1)}}{\|\x^{(i_1)}\|_2} \nonumber \\
\u^{(i_1,3,1)} & =  & \frac{(\h^{(1)})^T\x^{(i_1)}}{\|\x^{(i_1)}\|_2} \nonumber \\
\u^{(i_1,3,2)} & =  & \frac{(\h^{(2)})^T\x^{(i_1)}}{\|\x^{(i_1)}\|_2} \nonumber \\
\u^{(i_1,3,3)} & =  & \frac{(\h^{(3)})^T\x^{(i_1)}}{\|\x^{(i_1)}\|_2}.
\end{eqnarray}
and recall that
\begin{eqnarray}\label{eq:lev2genanal5}
\bar{\u}_j^{(i_1,1)} & =  & \frac{G_{j,1:n}\x^{(i_1)}}{\|\x^{(i_1)}\|_2},1\leq j\leq m.
\end{eqnarray}
It is not that difficult to see that for any $i_1$ the elements of $\u^{(i_1,1)}$ are i.i.d. standard normals  and the elements of $\u^{(i_1,3,1)}$, $\u^{(i_1,3,2)}$, and $\u^{(i_1,3,3)}$ are zero-mean Gaussians with  respective variances $\q_0-\q_1$, $\q_1-\q_2$, and $\q_2$. We then rewrite (\ref{eq:lev2genanal3}) as
\begin{equation}\label{eq:lev2genanal6}
\psi(t)  =  \mE_{G,{\mathcal U}_3} \frac{1}{p|s|\sqrt{n}\m_2} \log \lp\mE_{{\mathcal U}_2}  \lp
\sum_{i_3=1}^{l}
\lp
\mE_{{\mathcal U}_1} \lp \sum_{i_1=1}^{l}\lp\sum_{i_2=1}^{l}A_{i_3}^{(i_1,i_2)} \rp^{s}\rp^{\m_1}
\rp^p
 \rp^{\frac{\m_2}{\m_1}}\rp,
\end{equation}
where $\beta_{i_1}=\beta\|\x^{(i_1)}\|_2$ and now
\begin{eqnarray}\label{eq:lev2genanal7}
B^{(i_1,i_2)} & \triangleq &  \sqrt{t}(\y^{(i_2)})^T\bar{\u}^{(i_1,1)}+\sqrt{1-t} (\y^{(i_2)})^T(\u^{(2,1)}+\u^{(2,2)}+\u^{(2,3)} ) \nonumber \\
D^{(i_1,i_2,i_3)} & \triangleq &  B^{(i_1,i_2)}+\sqrt{t}\|\y^{(i_2)}\|_2 (u^{(4,1)}+u^{(4,2)}+u^{(4,3)})+\sqrt{1-t}\|\y^{(i_2)}\|_2(\u^{(i_1,3,1)}+\u^{(i_1,3,2)}+\u^{(i_1,3,3)})  \nonumber \\
& & + f_{\bar{\x}^{(i_3)} } (\x^{(i_1)}) \nonumber \\
A_{i_3}^{(i_1,i_2)} & \triangleq &  e^{\beta_{i_1}D^{(i_1,i_2,i_3)}}\nonumber \\
C_{i_3}^{(i_1)} & \triangleq &  \sum_{i_2=1}^{l}A^{(i_1,i_2)}\nonumber \\
Z_{i_3} & \triangleq & \sum_{i_1=1}^{l} \lp \sum_{i_2=1}^{l} A_{i_3}^{(i_1,i_2)}\rp^s =\sum_{i_1=1}^{l}  (C_{i_3}^{(i_1)})^s.
\end{eqnarray}
To study monotonicity of $\psi(t)$, we again start by considering its derivative
\begin{eqnarray}\label{eq:lev2genanal9}
\frac{d\psi(t)}{dt} & = &  \frac{d}{dt}\lp
\mE_{G,{\mathcal U}_3} \frac{1}{p|s|\sqrt{n}\m_2} \log \lp \mE_{{\mathcal U}_2}\lp
\lp
\sum_{i_3=1}^{l}
\lp
 \mE_{{\mathcal U}_1}  Z_{i_3}^{\m_1}
\rp^p
\rp^{\frac{\m_2}{\m_1}}\rp\rp
 \rp\nonumber \\
& = &  \mE_{G,{\mathcal U}_3} \frac{1}{p|s|\sqrt{n}\m_2\mE_{{\mathcal U}_2}\lp\lp
\sum_{i_3=1}^{l}
\lp
 \mE_{{\mathcal U}_1}  Z_{i_3}^{\m_1}
\rp^p
\rp^{\frac{\m_2}{\m_1}}\rp}
\frac{d\lp \mE_{{\mathcal U}_2}\lp\lp
\sum_{i_3=1}^{l}
\lp
 \mE_{{\mathcal U}_1}  Z_{i_3}^{\m_1}
\rp^p
\rp^{\frac{\m_2}{\m_1}}\rp\rp}{dt}\nonumber \\
& = &  \mE_{G,{\mathcal U}_3,{\mathcal U}_2}
\sum_{i_3=1}^{l}
\frac{\lp
\sum_{i_3=1}^{l}
\lp
 \mE_{{\mathcal U}_1}  Z_{i_3}^{\m_1}
\rp^p
\rp^{\frac{\m_2}{\m_1}-1} \lp
 \mE_{{\mathcal U}_1}  Z_{i_3}^{\m_1}
\rp^{p-1}  }   {|s|\sqrt{n}\m_1\mE_{{\mathcal U}_2}\lp\lp
\sum_{i_3=1}^{l}
\lp
 \mE_{{\mathcal U}_1}  Z_{i_3}^{\m_1}
\rp^p
\rp^{\frac{\m_2}{\m_1}}\rp}
\frac{d \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} }{dt}\nonumber \\
& = & \mE_{G,{\mathcal U}_3,{\mathcal U}_2}
\sum_{i_3=1}^{l}
\frac{\lp
\sum_{i_3=1}^{l}
\lp
 \mE_{{\mathcal U}_1}  Z_{i_3}^{\m_1}
\rp^p
\rp^{\frac{\m_2}{\m_1}-1} \lp
 \mE_{{\mathcal U}_1}  Z_{i_3}^{\m_1}
\rp^{p-1}  }   {|s|\sqrt{n}\mE_{{\mathcal U}_2}\lp\lp
\sum_{i_3=1}^{l}
\lp
 \mE_{{\mathcal U}_1}  Z_{i_3}^{\m_1}
\rp^p
\rp^{\frac{\m_2}{\m_1}}\rp}
\mE_{{\mathcal U}_1} \frac{1}{Z_{i_3}^{1-\m_1}}\frac{d Z_{i_3}}{dt}\nonumber \\
& = &  \mE_{G,{\mathcal U}_3,{\mathcal U}_2}
\sum_{i_3=1}^{l}
\frac{\lp
\sum_{i_3=1}^{l}
\lp
 \mE_{{\mathcal U}_1}  Z_{i_3}^{\m_1}
\rp^p
\rp^{\frac{\m_2}{\m_1}-1} \lp
 \mE_{{\mathcal U}_1}  Z_{i_3}^{\m_1}
\rp^{p-1}  }   {|s|\sqrt{n}\mE_{{\mathcal U}_2}\lp\lp
\sum_{i_3=1}^{l}
\lp
 \mE_{{\mathcal U}_1}  Z_{i_3}^{\m_1}
\rp^p
\rp^{\frac{\m_2}{\m_1}}\rp}
\mE_{{\mathcal U}_1} \frac{1}{Z_{i_3}^{1-\m_1}}
\frac{d\lp \sum_{i_1=1}^{l} \lp \sum_{i_2=1}^{l} A_{i_3}^{(i_1,i_2)}\rp^s \rp }{dt}\nonumber \\
& = &  \mE_{G,{\mathcal U}_3,{\mathcal U}_2}
\sum_{i_3=1}^{l}
\frac{\lp
\sum_{i_3=1}^{l}
\lp
 \mE_{{\mathcal U}_1}  Z_{i_3}^{\m_1}
\rp^p
\rp^{\frac{\m_2}{\m_1}-1} \lp
 \mE_{{\mathcal U}_1}  Z_{i_3}^{\m_1}
\rp^{p-1}  }   {|s|\sqrt{n}\mE_{{\mathcal U}_2}\lp\lp
\sum_{i_3=1}^{l}
\lp
 \mE_{{\mathcal U}_1}  Z_{i_3}^{\m_1}
\rp^p
\rp^{\frac{\m_2}{\m_1}}\rp}
s \mE_{{\mathcal U}_1} \frac{1}{Z_{i_3}^{1-\m_1}}
 \sum_{i=1}^{l} (C_{i_3}^{(i_1)})^{s-1} \nonumber \\
& & \times \sum_{i_2=1}^{l}\beta_{i_1}A_{i_3}^{(i_1,i_2)}\frac{dD^{(i_1,i_2,i_3)}}{dt},
\end{eqnarray}
where
\begin{equation}\label{eq:lev2genanal9a}
\frac{dD^{(i_1,i_2,i_3)}}{dt}= \lp \frac{dB^{(i_1,i_2)}}{dt}+\frac{\|\y^{(i_2)}\|_2 (u^{(4,1)}+u^{(4,2)}+u^{(4,3)})}{2\sqrt{t}}-\frac{\|\y^{(i_2)}\|_2 (\u^{(i_1,3,1)}+\u^{(i_1,3,2)}+\u^{(i_1,3,3)})}{2\sqrt{1-t}}\rp.
\end{equation}
From (\ref{eq:lev2genanal7}) we find
\begin{eqnarray}\label{eq:lev2genanal10}
\frac{dB^{(i_1,i_2)}}{dt} & = &   \frac{d\lp\sqrt{t}(\y^{(i_2)})^T\bar{\u}^{(i_1,1)}+\sqrt{1-t} (\y^{(i_2)})^T(\u^{(2,1)}+\u^{(2,2)}+\u^{(2,3)})\rp}{dt} \nonumber \\
 & = &
\sum_{j=1}^{m}\lp \frac{\y_j^{(i_2)}\bar{\u}_j^{(i_1,1)}}{2\sqrt{t}}-\frac{\y_j^{(i_2)}\u_j^{(2,1)}}{2\sqrt{1-t}}-\frac{\y_j^{(i_2)}\u_j^{(2,2)}}{2\sqrt{1-t}}
-\frac{\y_j^{(i_2)}\u_j^{(2,3)}}{2\sqrt{1-t}}\rp.
\end{eqnarray}
Analogously to (\ref{eq:genanal10e}) we then write
\begin{equation}\label{eq:lev2genanal10e}
\frac{d\psi(t)}{dt}  =       \frac{\mbox{sign}(s)}{2\beta\sqrt{n}} \sum_{i_1=1}^{l}  \sum_{i_2=1}^{l}
\beta_{i_1}\lp T_G + T_2+ T_1\rp,
\end{equation}
where
\begin{eqnarray}\label{eq:lev2genanal10f}
T_G & = & \sum_{j=1}^{m}\frac{T_{G,j}}{\sqrt{t}}  \nonumber\\
