\section{Move to the $r$-th ($r\geq 3$) level of full lifting}
\label{sec:rthlev}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

After introducing key conceptual ingredients in Section \ref{sec:gencon}, we  in Section \ref{sec:seclev} formalized them into a sequence of mathematical steps needed to proceed to second and higher levels of lifting. In this section we present the final results obtained via applying the procedure from Section \ref{sec:seclev} to any level of lifting $r\in\mN$. The presentation of  \cite{Stojnicnflgscompyx23}'s Section 4
 turns out to be of great help in that regard. In fact, as will soon be clear, many of the results obtained therein apply here either in an unaltered fashion or with fairly minimal adjustments.

As in \cite{Stojnicnflgscompyx23}'s Section 4, we now take $r\geq 3$ and  consider vectors $\m=[\m_1,\m_2,...,\m_r]$,
$\p=[\p_0,\p_1,...,\p_r,\p_{r+1}]$ with $\p_0\geq \p_1\geq \p_2\geq \dots \geq \p_r\geq\p_{r+1} = 0$ and $\q=[\q_0,\q_1,\q_2,\dots,\q_r,\q_{r+1}]$ with $\q_0\geq \q_1\geq \q_2\geq \dots \geq \q_r\geq \q_{r+1} = 0$. Also, we assume that the elements of $G\in\mR^{m \times n}$ and  $u^{(4,k)}\in\mR^1,\u^{(2,k)}\in\mR^{m\times 1}$, and $\h^{(k)}\in\mR^{n\times 1}$ (for any $k\in\{1,2,\dots,r+1\}$)  are independent  zero-mean normals. Moreover, he variances of the components of $G$, $u^{(4,k)}$, $\u^{(2,k)}$, and $\h^{(k)}$ are assumed to be $1$, $\p_{k-1}\q_{k-1}-\p_k\q_k$, $\p_{k-1}-\p_{k}$, $\q_{k-1}-\q_{k}$, respectively. Similarly to what was done earlier, we also set ${\mathcal U}_k\triangleq [u^{(4,k)},\u^{(2,k)},\h^{(2k)}]$ and assume that sets ${\mathcal X}$, $\bar{{\mathcal X}}$, ${\mathcal Y}$, scalars  $\beta$, $p$, $s$, and function $f_{\bar{\x}^{(i_3)}}(\cdot)$ are as in Proposition \ref{thm:thm1}. We then focus on the following function
\begin{equation}\label{eq:rthlev2genanal3}
\psi(t)  =  \mE_{G,{\mathcal U}_{r+1}} \frac{1}{\beta|s|\sqrt{n}\m_r} \log
\lp \mE_{{\mathcal U}_{r}} \lp \dots \lp \mE_{{\mathcal U}_2}\lp\lp \sum_{i_3=1}^{l} \lp \mE_{{\mathcal U}_1}  Z_{i_3}^{\m_1}\rp^p \rp^{\frac{\m_2}{\m_1}}\rp\rp^{\frac{\m_3}{\m_2}} \dots \rp^{\frac{\m_{r}}{\m_{r-1}}}\rp,
\end{equation}
where
\begin{eqnarray}\label{eq:rthlev2genanal3a}
Z_{i_3} & \triangleq & \sum_{i_1=1}^{l}\lp\sum_{i_2=1}^{l}e^{\beta D_0^{(i_1,i_2,i_3)}} \rp^{s} \nonumber \\
 D_0^{(i_1,i_2,i_3)} & \triangleq & \sqrt{t}(\y^{(i_2)})^T
 G\x^{(i_1)}+\sqrt{1-t}\|\x^{(i_1)}\|_2 (\y^{(i_2)})^T\lp\sum_{k=1}^{r+1}\u^{(2,k)}\rp\nonumber \\
 & & +\sqrt{t}\|\x^{(i_1)}\|_2\|\y^{(i_2)}\|_2\lp\sum_{k=1}^{r+1}u^{(4,k)}\rp +\sqrt{1-t}\|\y^{(i_2)}\|_2\lp\sum_{k=1}^{r+1}\h^{(k)}\rp^T\x^{(i_1)}
  + f_{\bar{\x}^{(i_3)}}(\x^{(i_3)}). \nonumber \\
 \end{eqnarray}
Analogously to (\ref{eq:genanal4}), we find it convenient to set
\begin{eqnarray}\label{eq:rthlev2genanal4}
\bar{\u}^{(i_1,1)} & =  & \frac{G\x^{(i_1)}}{\|\x^{(i_1)}\|_2} \nonumber \\
\bar{\u}^{(i_1,3,k)} & =  & \frac{(\h^{(k)})^T\x^{(i_1)}}{\|\x^{(i_1)}\|_2},
\end{eqnarray}
and recall that
\begin{eqnarray}\label{eq:rthlev2genanal5}
\bar{\u}_j^{(i_1,1)} & =  & \frac{G_{j,1:n}\x^{(i_1)}}{\|\x^{(i_1)}\|_2},1\leq j\leq m.
\end{eqnarray}
We observe that the elements of $\bar{\u}^{(i_1,1)}$ are i.i.d. standard normals, whereas the elements of $\u^{(2,k)}$  are zero-mean independent Gaussians with variances $\p_{k-1}-\p_k$ and the elements of $\u^{(i_1,3,k)}$ are zero-mean  independent  Gaussians with variances $\q_{k-1}-\q_k$. One can then rewrite (\ref{eq:rthlev2genanal3}) in the following way
\begin{equation}\label{eq:rthlev2genanal6}
\psi(t)  =  \mE_{G,{\mathcal U}_{r+1}} \frac{1}{p|s|\sqrt{n}\m_r} \log
\lp \mE_{{\mathcal U}_{r}} \lp \dots \lp \mE_{{\mathcal U}_2}\lp\lp  \sum_{i_3=1}^{l} \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}\rp^p \rp^{\frac{\m_2}{\m_1}}\rp\rp^{\frac{\m_3}{\m_2}} \dots \rp^{\frac{\m_{r}}{\m_{r-1}}}\rp,
\end{equation}
where $\beta_{i_1}=\beta\|\x^{(i_1)}\|_2$ and now
\begin{eqnarray}\label{eq:rthlev2genanal7}
B^{(i_1,i_2)} & \triangleq &  \sqrt{t}(\y^{(i_2)})^T\bar{\u}^{(i_1,1)}+\sqrt{1-t} (\y^{(i_2)})^T\lp \sum_{k=1}^{r+1}\u^{(2,k)} \rp \nonumber \\
D^{(i_1,i_2,i_3)} & \triangleq &  B^{(i_1,i_2)}+\sqrt{t}\|\y^{(i_2)}\|_2 \lp \sum_{k=1}^{r+1}u^{(4,k)}\rp+\sqrt{1-t}\|\y^{(i_2)}\|_2 \lp \sum_{k=1}^{r+1}\u^{(i_1,3,k)}  \rp   + f_{\bar{\x}^{(i_3)}} (\x^{(i_1)})  \nonumber \\
A_{i_3}^{(i_1,i_2)} & \triangleq &  e^{\beta_{i_1}D^{(i_1,i_2,i_3)}}\nonumber \\
C_{i_3}^{(i_1)} & \triangleq &  \sum_{i_2=1}^{l}A_{i_3}^{(i_1,i_2)}\nonumber \\
Z_{i_3} & \triangleq & \sum_{i_1=1}^{l} \lp \sum_{i_2=1}^{l} A_{i_3}^{(i_1,i_2)}\rp^s =\sum_{i_1=1}^{l}  (C_{i_3}^{(i_1)})^s.
\end{eqnarray}
We set $\m_0=1$ and  analogously to \cite{Stojnicnflgscompyx23}'s (199)
\begin{eqnarray}\label{eq:rthlev2genanal7a}
\zeta_r\triangleq \mE_{{\mathcal U}_{r}} \lp \dots \lp \mE_{{\mathcal U}_2}\lp\lp  \sum_{i_3=1}^{l} \lp \mE_{{\mathcal U}_1}  Z_{i_3}^{\frac{\m_1}{\m_0}}\rp^p \rp^{\frac{\m_2}{\m_1}}\rp\rp^{\frac{\m_3}{\m_2}} \dots \rp^{\frac{\m_{r}}{\m_{r-1}}}, r\geq 2.
\end{eqnarray}
Then one has
\begin{eqnarray}\label{eq:rthlev2genanal7b}
\zeta_k = \mE_{{\mathcal U}_{k}} \lp  \zeta_{k-1} \rp^{\frac{\m_{k}}{\m_{k-1}}}, k\geq 2,\quad \mbox{and} \quad
\zeta_1=  \sum_{i_3=1}^{l} \lp \mE_{{\mathcal U}_1}  Z_{i_3}^{\frac{\m_1}{\m_0}}\rp^p.
\end{eqnarray}
Utilizing  \cite{Stojnicnflgscompyx23}'s (201) we write
\begin{eqnarray}\label{eq:rthlev2genanal9}
\frac{d\psi(t)}{dt}
 & = &  \mE_{G,{\mathcal U}_{r+1}} \frac{1}{p|s|\sqrt{n}\m_1\zeta_r}
\prod_{k=r}^{2}\mE_{{\mathcal U}_{k}} \zeta_{k-1}^{\frac{\m_k}{\m_{k-1}}-1}
 \frac{d\zeta_{1}}{dt} \nonumber \\
& = &   \mE_{G,{\mathcal U}_{r+1}} \frac{1}{|s|\sqrt{n}\m_1\zeta_r}
\prod_{k=r}^{2}\mE_{{\mathcal U}_{k}} \zeta_{k-1}^{\frac{\m_k}{\m_{k-1}}-1}
\sum_{i_3=1}^{l} \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}  \rp^{p-1}
 \frac{d \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1} }{dt} \nonumber \\
 & = &
\mE_{G,{\mathcal U}_{r+1}} \frac{1}{|s|\sqrt{n}\zeta_r}
\prod_{k=r}^{2}\mE_{{\mathcal U}_{k}} \zeta_{k-1}^{\frac{\m_k}{\m_{k-1}}-1}
\sum_{i_3=1}^{l} \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}  \rp^{p-1}
 \mE_{{\mathcal U}_1} \frac{1}{Z_{i_3}^{1-\m_1}}  \sum_{i=1}^{l} (C_{i_3}^{(i_1)})^{s-1} \nonumber \\
& & \times \sum_{i_2=1}^{l}\beta_{i_1}A_{i_3}^{(i_1,i_2)}\frac{dD^{(i_1,i_2,i_3)}}{dt},
\end{eqnarray}
with product running in an \emph{index decreasing order} and
\begin{eqnarray}\label{eq:rthlev2genanal9a}
\frac{dD^{(i_1,i_2,i_3)}}{dt}= \lp \frac{dB^{(i_1,i_2)}}{dt}+\frac{\|\y^{(i_2)}\|_2 (\sum_{k=1}^{r+1} u^{(4,k)})}{2\sqrt{t}}-\frac{\|\y^{(i_2)}\|_2 (\sum_{k=1}^{r+1}\u^{(i_1,3,k)})}{2\sqrt{1-t}}\rp.
\end{eqnarray}
As shown in \cite{Stojnicnflgscompyx23}'s (203), we have
\begin{eqnarray}\label{eq:rthlev2genanal10}
\frac{dB^{(i_1,i_2)}}{dt}
 & = &
\sum_{j=1}^{m}\lp \frac{\y_j^{(i_2)}\u_j^{(i_1,1)}}{2\sqrt{t}}-\frac{\y_j^{(i_2)} \sum_{k=1}^{r+1} \u_j^{(2,k)}}{2\sqrt{1-t}}\rp.
\end{eqnarray}
and then  analogously to (\ref{eq:genanal10e}) (and \cite{Stojnicnflgscompyx23}'s (203)-(205))
\begin{equation}\label{eq:rthlev2genanal10e}
\frac{d\psi(t)}{dt}  =       \frac{\mbox{sign}(s)}{2\beta\sqrt{n}} \sum_{i_1=1}^{l}  \sum_{i_2=1}^{l}
\beta_{i_1}\lp T_G + \sum_{k=1}^{r+1}T_k\rp,
\end{equation}
where
\begin{eqnarray}\label{eq:rthlev2genanal10f}
T_G & = & \sum_{j=1}^{m}\frac{T_{G,j}}{\sqrt{t}}  \nonumber\\
T_k & = & -\sum_{j=1}^{m}\frac{T_{k,1,j}}{\sqrt{1-t}}-\|\y^{(i_2)}\|_2\frac{T_{k,2}}{\sqrt{1-t}}+\|\y^{(i_2)}\|_2\frac{T_{k,3}}{\sqrt{t}}, k\in\{1,2,\dots,r+1\}.
 \end{eqnarray}
 \begin{eqnarray}\label{eq:rthlev2genanal10g}
T_{G,j} & = &  \mE_{G,{\mathcal U}_{r+1}} \lp
\zeta_r^{-1}\prod_{v=r}^{2}\mE_{{\mathcal U}_{v}} \zeta_{v-1}^{\frac{\m_v}{\m_{v-1}}-1}
\sum_{i_3=1}^{l} \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}  \rp^{p-1}
  \mE_{{\mathcal U}_1}\frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)} \y_j^{(i_2)}\u_j^{(i_1,1)}}{Z_{i_3}^{1-\m_1}} \rp \nonumber \\
T_{k,1,j} & = &   \mE_{G,{\mathcal U}_{r+1}} \lp
\zeta_r^{-1}\prod_{v=r}^{2}\mE_{{\mathcal U}_{v}} \zeta_{v-1}^{\frac{\m_v}{\m_{v-1}}-1}
\sum_{i_3=1}^{l} \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}  \rp^{p-1}
  \mE_{{\mathcal U}_1}\frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)} \y_j^{(i_2)}\u_j^{(2,k)}}{Z_{i_3}^{1-\m_1}} \rp \nonumber \\
T_{k,2} & = &   \mE_{G,{\mathcal U}_{r+1}} \lp
\zeta_r^{-1}\prod_{v=r}^{2}\mE_{{\mathcal U}_{v}} \zeta_{v-1}^{\frac{\m_v}{\m_{v-1}}-1}
\sum_{i_3=1}^{l} \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}  \rp^{p-1}
  \mE_{{\mathcal U}_1}\frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)} \u^{(i_1,3,k)}}{Z_{i_3}^{1-\m_1}} \rp \nonumber \\
T_{k,3} & = &  \mE_{G,{\mathcal U}_{r+1}} \lp
\zeta_r^{-1}\prod_{v=r}^{2}\mE_{{\mathcal U}_{v}} \zeta_{v-1}^{\frac{\m_v}{\m_{v-1}}-1}
\sum_{i_3=1}^{l} \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}  \rp^{p-1}
  \mE_{{\mathcal U}_1}\frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)} u^{(4,k)}}{Z_{i_3}^{1-\m_1}} \rp.
\end{eqnarray}

We first discuss the three sequences $\lp T_{k,1,j}\rp_{k=1:r+1}$, $\lp T_{k,2}\rp_{k=1:r+1}$, and $\lp T_{k,3}\rp_{k=1:r+1}$  and then $T_{G,j}$. As Section \ref{sec:seclev} showed, the internal relations among the components in any of these sequences are for all that we need identical. It will therefore be sufficient to take one of them, say $\lp T_{k,1,j}\rp_{k=1:r+1}$, and show how the results of Section \ref{sec:seclev} immediately extend from $r=2$ to any integer $r>2$. For the remaining two, $\lp T_{k,2}\rp_{k=1:r+1}$, and $\lp T_{k,3}\rp_{k=1:r+1}$, we avoid unnecessarily repeating the same strategy and instead  quickly deduce the final results.






