%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Successive scaling and canceling out}
\label{sec:scaledcanout}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Following the strategy of \cite{Stojnicnflgscompyx23}, we consider sequence $\lp T_{k,1,j}\rp_{k=1:r+1}$, take one component, say $T_{k_1,1,j}$, $k_1\geq 2$, and show how it relates to the very next one, $T_{k_1+1,1,j}$. Two aspects of such a recursive relation play a key role: 1) \emph{successive scaling}; and 2) appearance of an appropriately \emph{reweightedly averaged (over a $\gamma$ measure) new term}.

Utilizing \cite{Stojnicnflgscompyx23}'s (207)-(209), we have
 \begin{eqnarray}\label{eq:rthlev2genanal11}
 T_{k_1,1,j}   \hspace{-.06in}  & = &  \hspace{-.06in}  (\p_{k_1-1}-\p_{k_1}) \mE_{G,{\mathcal U}_{r+1}} \Bigg(\Bigg.
\zeta_r^{-1}\prod_{v=r}^{k_1+1}\mE_{{\mathcal U}_{v}} \zeta_{v-1}^{\frac{\m_v}{\m_{v-1}}-1}
\mE_{{\mathcal U}_{k_1}}  \nonumber \\
& &  \hspace{-.06in} \times
\frac{d}{d\u_j^{(2,k_1)}} \lp \zeta_{k_1-1}^{\frac{\m_{k_1}}{\m_{k_1-1}}-1}\prod_{v=k_1-1}^{2}\mE_{{\mathcal U}_{v}} \zeta_{v-1}^{\frac{\m_v}{\m_{v-1}}-1}
\sum_{i_3=1}^{l} \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}  \rp^{p-1}
  \mE_{{\mathcal U}_1}\frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)} \y_j^{(i_2)}\u_j^{(2,k_1)}}{Z_{i_3}^{1-\m_1}} \rp \Bigg.\Bigg)  , \nonumber \\
\end{eqnarray}
and also
 \begin{eqnarray}\label{eq:rthlev2genanal12}
 T_{k_1+1,1,j}
       & = & (\p_{k_1} -\p_{k_1+1})
  \mE_{G,{\mathcal U}_{r+1}} \Bigg( \Bigg.
\zeta_r^{-1}\prod_{v=r}^{k_1+2}\mE_{{\mathcal U}_{v}} \zeta_{v-1}^{\frac{\m_v}{\m_{v-1}}-1}
\mE_{{\mathcal U}_{k_1+1}}  \nonumber \\
& & \times  \frac{d}{d\u_j^{(2,k_1+1)}}  \lp \zeta_{k_1}^{\frac{\m_{k_1+1}}{\m_{k_1}}-1}
\prod_{v=k_1}^{2}\mE_{{\mathcal U}_{v}} \zeta_{v-1}^{\frac{\m_v}{\m_{v-1}}-1}
\sum_{i_3=1}^{l} \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}  \rp^{p-1}
  \mE_{{\mathcal U}_1}\frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)} \y_j^{(i_2)}}{Z_{i_3}^{1-\m_1}} \rp   \Bigg. \Bigg)   \nonumber \\
& = &  \Pi_{k_1+1,1,j}^{(1)}
+  \Pi_{k_1+1,1,j}^{(2)}, \nonumber \\
 \end{eqnarray}
where
 \begin{eqnarray}\label{eq:rthlev2genanal13}
 \Pi_{k_1+1,1,j}^{(1)}
      & = & (\p_{k_1}-\p_{k_1+1})
  \mE_{G,{\mathcal U}_{r+1}} \Bigg( \Bigg.
\zeta_r^{-1}\prod_{v=r}^{k_1+2}\mE_{{\mathcal U}_{v}} \zeta_{v-1}^{\frac{\m_v}{\m_{v-1}}-1}
\mE_{{\mathcal U}_{k_1+1}}  \nonumber \\
& & \times \zeta_{k_1}^{\frac{\m_{k_1+1}}{\m_{k_1}}-1}
 \frac{d}{d\u_j^{(2,k_1+1)}}  \lp
\prod_{v=k_1}^{2}\mE_{{\mathcal U}_{v}} \zeta_{v-1}^{\frac{\m_v}{\m_{v-1}}-1}
\sum_{i_3=1}^{l} \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}  \rp^{p-1}
  \mE_{{\mathcal U}_1}\frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)} \y_j^{(i_2)}}{Z_{i_3}^{1-\m_1}} \rp   \Bigg. \Bigg)   \nonumber \\
\Pi_{k_1+1,1,j}^{(2)}
& = &(\p_{k_1}-\p_{k_1+1})
  \mE_{G,{\mathcal U}_{r+1}} \Bigg( \Bigg.
\zeta_r^{-1}\prod_{v=r}^{k_1+2}\mE_{{\mathcal U}_{v}} \zeta_{v-1}^{\frac{\m_v}{\m_{v-1}}-1}
\mE_{{\mathcal U}_{k_1+1}}  \nonumber \\
& & \times \prod_{v=k_1}^{2}\mE_{{\mathcal U}_{v}} \zeta_{v-1}^{\frac{\m_v}{\m_{v-1}}-1}
\sum_{i_3=1}^{l} \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}  \rp^{p-1}
  \mE_{{\mathcal U}_1}\frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)} \y_j^{(i_2)}}{Z_{i_3}^{1-\m_1}}
   \frac{d}{d\u_j^{(2,k_1+1)}}  \lp \zeta_{k_1}^{\frac{\m_{k_1+1}}{\m_{k_1}}-1}
 \rp   \Bigg. \Bigg). \nonumber \\
\end{eqnarray}
Analogously to \cite{Stojnicnflgscompyx23}'s (210), we further have  for $\Pi_{k_1+1,1,j}^{(1)}$
 \begin{eqnarray}\label{eq:rthlev2genanal14}
 \Pi_{k_1+1,1,j}^{(1)}
\hspace{-.01in}       & = & (\p_{k_1}-\p_{k_1+1})
  \mE_{G,{\mathcal U}_{r+1}} \Bigg( \Bigg.
\zeta_r^{-1}\prod_{v=r}^{k_1+1}\mE_{{\mathcal U}_{v}} \zeta_{v-1}^{\frac{\m_v}{\m_{v-1}}-1}
\mE_{{\mathcal U}_{k_1}}
\nonumber \\
& & \times
 \frac{d}{d\u_j^{(2,k_1+1)}}  \lp
\zeta_{k_1-1}^{\frac{\m_{k_1}}{\m_{k_1-1}}-1}
\prod_{v=k_1-1}^{2}\mE_{{\mathcal U}_{v}} \zeta_{v-1}^{\frac{\m_v}{\m_{v-1}}-1}
\sum_{i_3=1}^{l} \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}  \rp^{p-1}
  \mE_{{\mathcal U}_1}\frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)} \y_j^{(i_2)}}{Z_{i_3}^{1-\m_1}} \rp   \Bigg. \Bigg).   \nonumber \\
 \end{eqnarray}
 Following \cite{Stojnicnflgscompyx23}'s (211)-(214), we set
  \begin{eqnarray}\label{eq:rthlev2genanal15}
 f_c(B^{(i_1,i_2)}) = \lp
\zeta_{k_1-1}^{\frac{\m_{k_1}}{\m_{k_1-1}}-1}
\prod_{v=k_1-1}^{2}\mE_{{\mathcal U}_{v}} \zeta_{v-1}^{\frac{\m_v}{\m_{v-1}}-1}
  \mE_{{\mathcal U}_1}\frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)} \y_j^{(i_2)}}{Z_{i_3}^{1-\m_1}} \rp,
 \end{eqnarray}
 and observe
 \begin{eqnarray}\label{eq:rthlev2genanal18}
   \frac{d}{d\u_j^{(2,k_1)}}  \lp f_c(B^{(i_1,i_2)}) \rp=
   \frac{d}{d\u_j^{(2,k_1+1)}}  \lp f_c(B^{(i_1,i_2)}) \rp.
 \end{eqnarray}
After combining  (\ref{eq:rthlev2genanal11}), (\ref{eq:rthlev2genanal14}), and (\ref{eq:rthlev2genanal18}) we arrive at the \emph{successive scaling} relation (the key component  of the \emph{canceling out} mechanism)
 \begin{eqnarray}\label{eq:rthlev2genanal19}
 \Pi_{k_1+1,1,j}^{(1)}=\frac{(\p_{k_1} -\p_{k_1+1})}{(\p_{k_1-1}-\p_{k_1})}T_{k_1,1,j}.
 \end{eqnarray}

For $\Pi_{k_1+1,1,j}^{(2)}$, we have
\begin{eqnarray}\label{eq:rthlev2genanal20}
 \Pi_{k_1+1,1,j}^{(2)}
& = &(\p_{k_1}-\p_{k_1+1})
  \mE_{G,{\mathcal U}_{r+1}} \Bigg( \Bigg.
\zeta_r^{-1}\prod_{v=r}^{k_1+2}\mE_{{\mathcal U}_{v}} \zeta_{v-1}^{\frac{\m_v}{\m_{v-1}}-1}
\mE_{{\mathcal U}_{k_1+1}}  \nonumber \\
& & \times \prod_{v=k_1}^{2}\mE_{{\mathcal U}_{v}} \zeta_{v-1}^{\frac{\m_v}{\m_{v-1}}-1}
\sum_{i_3=1}^{l} \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}  \rp^{p-1}
  \mE_{{\mathcal U}_1}\frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)} \y_j^{(i_2)}}{Z_{i_3}^{1-\m_1}}
   \frac{d}{d\u_j^{(2,k_1+1)}}  \lp \zeta_{k_1}^{\frac{\m_{k_1+1}}{\m_{k_1}}-1}
 \rp   \Bigg. \Bigg), \nonumber \\
\end{eqnarray}
where analogously to \cite{Stojnicnflgscompyx23}'s (229)
\begin{eqnarray}\label{eq:rthlev2genanal23}
    \frac{d}{d\u_j^{(2,k_1+1)}}  \lp \zeta_{k_1}^{\frac{\m_{k_1+1}}{\m_{k_1}}-1}
 \rp   \Bigg. \Bigg)
  & =  & s \lp \m_{k_1+1} - \m_{k_1} p \rp \zeta_{k_1}^{\frac{\m_{k_1+1}}{\m_{k_1}}-2}
\prod_{k=k_1}^{2}\mE_{{\mathcal U}_{k}} \zeta_{k-1}^{\frac{\m_k}{\m_{k-1}}-1}
\sum_{p_3=1}^{l} \lp \mE_{{\mathcal U}_1} Z_{p_3}^{\m_1}  \rp^{p-1}
\nonumber  \\
& & \times
 \mE_{{\mathcal U}_1} \frac{1}{Z_{p_3}^{1-\m_1}}  \sum_{p_1=1}^{l} (C_{p_3}^{(p_1)})^{s-1}
 \sum_{p_2=1}^{l}\beta_{p_1}A_{p_3}^{(p_1,p_2)}\sqrt{1-t} \y_j^{(p_2)}.
\end{eqnarray}
Combining (\ref{eq:rthlev2genanal20}) and (\ref{eq:rthlev2genanal23}) one obtains the following analogue of \cite{Stojnicnflgscompyx23}'s (220)
\begin{eqnarray}\label{eq:rthlev2genanal24}
 \Pi_{k_1+1,1,j}^{(2)}
 & = & s(\p_{k_1}-\p_{k_1+1}) \lp \m_{k_1+1} - \m_{k_1}  p \rp
  \mE_{G,{\mathcal U}_{r+1}} \Bigg( \Bigg.
\prod_{v=r}^{k_1+1} \mE_{{\mathcal U}_{v}} \frac{\zeta_{v-1}^{\frac{\m_v}{\m_{v-1}}}}{\zeta_v} \nonumber \\
& & \times \prod_{v=k_1}^{2}\mE_{{\mathcal U}_{v}} \frac{\zeta_{v-1}^{\frac{\m_v}{\m_{v-1}}}}{\zeta_v}
\sum_{i_3=1}^{l} \lp \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}  \rp^{p-1}
   \mE_{{\mathcal U}_1}\frac{Z_{i_3}^{\m_1}}{\zeta_1}   \frac{(C_{i_3}^{(i_1)})^{s} }{Z_{i_3}}
\frac{ A_{i_3}^{(i_1,i_2)} }{C_{i_3}^{(i_1)}}\y_j^{(i_2)}
\nonumber \\
& & \times \prod_{k=k_1}^{2}  \mE_{{\mathcal U}_{k}} \frac{\zeta_{k-1}^{\frac{\m_k}{\m_{k-1}}}}{\zeta_k}
\sum_{p_3=1}^{l} \lp \mE_{{\mathcal U}_1} Z_{p_3}^{\m_1}  \rp^{p-1}
 \mE_{{\mathcal U}_1}\frac{Z_{p_3}^{\m_1}}{\zeta_1}  \sum_{p_1=1}^{l} \frac{(C_{p_3}^{(p_1)})^s}{Z_{p_3}}
 \sum_{p_2=1}^{l} \frac{A_{p_3}^{(p_1,p_2)}}{C_{p_3}^{(p_1)}}\sqrt{1-t} \beta_{p_1} \y_j^{(p_2)}
   \Bigg. \Bigg). \nonumber \\
\end{eqnarray}
We then set
\begin{eqnarray}\label{eq:rthlev2genanal25}
 \Phi_{{\mathcal U}_1}^{(i_3)} & \triangleq &  \mE_{{\mathcal U}_{1}} \frac{  Z_{i_3}^{\m_1}  } {  \mE_{{\mathcal U}_{1}} Z_{i_3}^{\m_1}  } \nonumber \\
 \Phi_{{\mathcal U}_k} & \triangleq &  \mE_{{\mathcal U}_{k}} \frac{\zeta_{k-1}^{\frac{\m_k}{\m_{k-1}}}}{\zeta_k} ,k\geq 2 \nonumber \\
 \gamma_{00}(i_3) & = &
\frac{  \lp  \mE_{{\mathcal U}_{1}} Z_{i_3}^{\m_1} \rp^p   }  { \sum_{i_3=1}^{l} \lp  \mE_{{\mathcal U}_{1}} Z_{i_3}^{\m_1} \rp^p   } \nonumber \\
 \gamma_0(i_1,i_2;i_3) & = &
\frac{(C_{i_3}^{(i_1)})^{s}}{Z_{i_3}}  \frac{A_{i_3}^{(i_1,i_2)}}{C_{i_3}^{(i_1)}} \nonumber \\
\gamma_{01}^{(r)}  & = & \prod_{k=r}^{2}\Phi_{{\mathcal U}_k} \gamma_{00}(i_3) \Phi_{{\mathcal U}_1}^{(i_3)} (\gamma_0(i_1,i_2;i_3))  \nonumber \\
\gamma_{02}^{(r)}  & = & \prod_{k=r}^{2} \Phi_{{\mathcal U}_k}   \gamma_{00}(i_3)    \Phi_{{\mathcal U}_1}^{(i_3)}   (\gamma_0(i_1,i_2;i_3)\times \gamma_0(i_1,p_2;i_3)) \nonumber \\
\gamma_{1}^{(r)}  & = & \prod_{k=r}^{2} \Phi_{{\mathcal U}_k}   \gamma_{00}(i_3)    \Phi_{{\mathcal U}_1}^{(i_3)}   (\gamma_0(i_1,i_2;i_3)\times \gamma_0(p_1,p_2;i_3)) \nonumber \\
\gamma_{21}^{(r)}  & = & \prod_{k=r}^{2}\Phi_{{\mathcal U}_k} \lp
  \gamma_{00}(i_3)    \Phi_{{\mathcal U}_1}^{(i_3)}   \gamma_0(i_1,i_2;i_3)\times
    \gamma_{00}(p_3)    \Phi_{{\mathcal U}_1}^{(p_3)}
  \gamma_0(p_1,p_2;p_3) \rp  \nonumber \\
\gamma_{22}^{(r)}  & = & \prod_{k=r}^{2}\Phi_{{\mathcal U}_k} \lp
  \gamma_{00}(i_3)  \lp  \Phi_{{\mathcal U}_1}^{(i_3)}   \gamma_0(i_1,i_2;i_3)\times
     \Phi_{{\mathcal U}_1}^{(i_3)}
  \gamma_0(p_1,p_2;i_3) \rp \rp \nonumber \\
\gamma_{k_1+1}^{(r)}  & = & \prod_{k=r}^{k_1+1}\Phi_{{\mathcal U}_k} \lp \prod_{k=k_1}^{2}\Phi_{{\mathcal U}_k}
  \gamma_{00}(i_3)    \Phi_{{\mathcal U}_1}^{(i_3)}   \gamma_0(i_1,i_2;i_3)\times \prod_{k=k_1}^{2} \Phi_{{\mathcal U}_k}
    \gamma_{00}(p_3)    \Phi_{{\mathcal U}_1}^{(p_3)}
  \gamma_0(p_1,p_2;p_3) \rp, k_1\geq 2, \nonumber \\
 \end{eqnarray}
and from (\ref{eq:rthlev2genanal24}) find
\begin{eqnarray}\label{eq:rthlev2genanal26}
 \sum_{i_1=1}^{l}\sum_{i_2=1}^{l} \sum_{j=1}^{m}
\beta_{i_1} \frac{\Pi_{k_1+1,1,j}^{(2)}}{\sqrt{1-t}}
 & = & -s(\p_{k_1}-\p_{k_1+1}) \lp \m_{k_1}  - \m_{k_1+1} \rp p
  \mE_{G,{\mathcal U}_{r+1}} \Bigg( \Bigg.
\prod_{v=r}^{k_1+1} \Phi_{{\mathcal U}_v} \nonumber \\
& & \times \prod_{v=k_1}^{2} \Phi_{{\mathcal U}_v}
\sum_{i_3=1}^{l}\gamma_{00}(i_3) \Phi_{ {\mathcal U}_1 }^{(i_3)}
\sum_{i_1=1}^{l}\sum_{i_2=1}^{l} \frac{(C^{(i_1)})^{s} }{Z}
\frac{ A^{(i_1,i_2)} }{C^{(i_1)}}\y_j^{(i_2)}
\nonumber \\
& & \times \prod_{k=k_1}^{2} \Phi_{{\mathcal U}_k}
\sum_{p_3=1}^{p}\gamma_{00}(p_3) \Phi_{ {\mathcal U}_1 }^{(p_3)}
 \sum_{p_1=1}^{l} \frac{(C^{(p_1)})^s}{Z}
 \sum_{p_2=1}^{l} \frac{A^{(p_1,p_2)}}{C^{(p_1)}} \beta_{i_1} \beta_{p_1} (\y^{(p_2)})^T \y^{(i_2)}
   \Bigg. \Bigg) \nonumber \\
 & = & -s\beta^2(\p_{k_1}-\p_{k_1+1}) \lp \m_{k_1} - \m_{k_1+1} \rp p \nonumber\\
 & & \times
  \mE_{G,{\mathcal U}_{r+1}} \left \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2 (\y^{(p_2)})^T \y^{(i_2)} \right \rangle_{\gamma_{k_1+1}^{(r)}}.
\end{eqnarray}
A combination of  (\ref{eq:rthlev2genanal12}), (\ref{eq:rthlev2genanal19}), and (\ref{eq:rthlev2genanal26}) then gives
 \begin{eqnarray}\label{eq:rthlev2genanal27}
 \sum_{i_1=1}^{l}\sum_{i_2=1}^{l} \sum_{j=1}^{m}
\beta_{i_1} \frac{T_{k_1+1,1,j}}{\sqrt{1-t}}
& = &  \sum_{i_1=1}^{l}\sum_{i_2=1}^{l} \sum_{j=1}^{m}
\beta_{i_1} \frac{\Pi_{k_1+1,1,j}^{(1)}}{\sqrt{1-t}} +  \sum_{i_1=1}^{l}\sum_{i_2=1}^{l} \sum_{j=1}^{m}
\beta_{i_1} \frac{\Pi_{k_1+1,1,j}^{(2)}}{\sqrt{1-t}} \nonumber \\
& = &  \frac{\p_{k_1}-\p_{k_1+1}}{\p_{k_1-1}-\p_{k_1}}\sum_{i_1=1}^{l}\sum_{i_2=1}^{l} \sum_{j=1}^{m}
\beta_{i_1} \frac{T_{k_1,1,j}}{\sqrt{1-t}} \nonumber \\
 &  & - \Bigg( \Bigg. s\beta^2(\p_{k_1}-\p_{k_1+1}) \lp \m_{k_1} -  \m_{k_1+1} \rp p \nonumber \\
 & & \times
  \mE_{G,{\mathcal U}_{r+1}} \left \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2 (\y^{(p_2)})^T \y^{(i_2)} \right \rangle_{\gamma_{k_1+1}^{(r)} } \Bigg. \Bigg).
\end{eqnarray}
Keeping in mind  first and second level results obtained earlier, one can then immediately write analogously for the other two sequences $\lp T_{k,2}\rp_{k=1:r+1}$ and $\lp T_{k,3}\rp_{k=1:r+1}$
\begin{eqnarray}\label{eq:rthlev2genanal28}
 \sum_{i_1=1}^{l}\sum_{i_2=1}^{l}
\beta_{i_1} \|\y^{(i_2)}\|_2 \frac{T_{k_1+1,2}}{\sqrt{1-t}}
 & = &  \frac{\q_{k_1}-\q_{k_1+1}}{\q_{k_1-1}-\q_{k_1}}\sum_{i_1=1}^{l}\sum_{i_2=1}^{l}
\beta_{i_1} \|\y^{(i_2)}\|_2 \frac{T_{k_1,2}}{\sqrt{1-t}} \nonumber \\
 &  & - \Bigg( \Bigg. s\beta^2(\q_{k_1}-\q_{k_1+1}) \lp \m_{k_1} - \m_{k_1+1} \rp p \nonumber \\
 & &
\times  \mE_{G,{\mathcal U}_{r+1}} \left \langle   (\x^{(p_1)})^T \x^{(i_1)} \|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2  \right \rangle_{\gamma_{k_1+1}^{(r)} } \Bigg.\Bigg), \nonumber \\
\end{eqnarray}
and
 \begin{eqnarray}\label{eq:rthlev2genanal29}
 \sum_{i_1=1}^{l}\sum_{i_2=1}^{l}
\beta_{i_1} \|\y^{(i_2)}\|_2 \frac{T_{k_1+1,3}}{\sqrt{1-t}}
 & = &  \frac{\p_{k_1}\q_{k_1}-\p_{k_1+1}\q_{k_1+1}}{\p_{k_1-1}\q_{k_1-1}-\p_{k_1}\q_{k_1}}\sum_{i_1=1}^{l}\sum_{i_2=1}^{l}
\beta_{i_1} \|\y^{(i_2)}\|_2 \frac{T_{k_1,3}}{\sqrt{1-t}} \nonumber \\
 &  & - \Bigg( \Bigg. s\beta^2(\p_{k_1}\q_{k_1}-\p_{k_1+1}\q_{k_1+1}) \lp  \m_{k_1} - \m_{k_1+1} \rp p \nonumber \\
& & \times   \mE_{G,{\mathcal U}_{r+1}} \left \langle   \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2 \|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2  \right \rangle_{\gamma_{k_1+1}^{(r)} } \Bigg. \Bigg).
\end{eqnarray}
As observed in \cite{Stojnicnflgscompyx23},  adding the elements in each of the sequences results in canceling out parts of the first and second summands.







