    \frac{(C_{i_3}^{(i_1)})^{s-1} A_{i_3}^{(i_1,i_2)} \y_j^{(i_2)}}{Z_{i_3}^{1-\m_1}}    \frac{d}{d\bar{\u}_j^{(p_1,1)}} \lp
 \zeta_{k_1-1}^{\frac{\m_{k_1}}{\m_{k_1-1}}-1}
  \rp \Bigg.\Bigg) \nonumber \\
 &  & +  \beta^2 \mE_{G,{\mathcal U}_{r+1},{{\mathcal U}_{r}},\dots,{{\mathcal U}_{1}}} \Bigg(\Bigg.
 \sum_{p_1=1}^{l} (\x^{(p_1)})^T\x^{(i_1)}   \lp \beta_{i_1}\beta_{p_1} \rp^{-1}
\prod_{v=r+1}^{2} \zeta_{v-1}^{\frac{\m_v}{\m_{v-1}}-1}
\sum_{i_3=1}^{l} \nonumber \\
