 \frac{\y_j^{(i_2)}}{Z_{i_3}}\lp(C_{i_3}^{(i_1)})^{s-1}\beta_{i_1}A_{i_3}^{(i_1,i_2)}\y_j^{(i_2)}\sqrt{t}+(s-1)(C_{i_3}^{(i_1)})^{s-2}\beta_{i_1}\sum_{p_2=1}^{l}A_{i_3}^{(i_1,p_2)}\y_j^{(p_2)}\sqrt{t}\rp \nonumber \\
