& & \times \sum_{p_2=1}^{l} \frac{A_{p_3}^{(p_1,p_2)}}{C_{p_3}^{(p_1)}}\sqrt{t}  \frac{ 1} { \beta_{i_1} } (\x^{(p_1)})^T\x^{(i_1)}  \y_j^{(p_2)}\y_j^{(i_2)}
 \Bigg.\Bigg) \nonumber \\
  & = &  s\beta^2 \lp \m_{k_1} - \m_{k_1-1}\rp p \mE_{G,{\mathcal U}_{r+1}} \Bigg(\Bigg.
\prod_{k=r}^{k_1+1}\Phi_{{\mathcal U}_{k}}
 \prod_{k=k_1}^{2}\Phi_{{\mathcal U}_{k}}
\sum_{i_3=1}^{l}
 \gamma_{00}(i_3)
 \Phi_{{\mathcal U}_{1}}^{(i_3)}
    \frac{(C_{i_3}^{s} }{Z_{i_3}}     \frac{ A_{i_3}^{(i_1,i_2)} }{C_{i_3}^{(i_1)}}  \nonumber \\
& &
\times
