\rp^{p} }  {  \zeta_1 }
\mE_{{\mathcal U}_1}\frac{ Z_{i_3}^{\m_1} } { \mE_{{\mathcal U}_1} Z_{i_3}^{\m_1}  }
 \sum_{p_1=1}^{l} (\x^{(p_1)})^T\x^{(i_1)}
  \frac{1}{Z_{i_3}}  (C_{i_3}^{(p_1)})^{s-1}\sum_{p_2=1}^{l}A_{i_3}^{(p_1,p_2)}
