A combination of  (\ref{eq:rthlev2genanal30}), (\ref{eq:rthlev2genanal34}), (\ref{eq:rthlev2genanal37}), and (\ref{eq:rthlev2genanal35bb1})  then gives
\begin{eqnarray}\label{eq:rthlev2genanal38}
\sum_{i_1=1}^{l}\sum_{i_2=1}^{l}\sum_{j=1}^{m} \beta_{i_1 }\frac{T_{G,j}}{\sqrt{t}}
& = & \sum_{i_1=1}^{l}\sum_{i_2=1}^{l}\sum_{j=1}^{m} \beta_{i_1 }\frac{(T_{G,j}^c+T_{G,j}^{d_1}+T_{G,j}^{e_1}+\sum_{k_1=3}^{r+1} T_{G,j}^{d_{k_1-1}})}{\sqrt{t}} \nonumber \\
& = & \beta^2 \lp \mE_{G,{\mathcal U}_{r+1}} \langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(r)}} +   (s-1)\mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2(\y^{(p_2)})^T\y^{(i_2)}\rangle_{\gamma_{02}^{(r)}}   \rp    \nonumber \\
 &  & -s\beta^2(1-\m_1) \mE_{G,{\mathcal U}_{r+1}}\langle (\x^{(p_1)})^T\x^{(i_1)}(\y^{(p_2)})^T\y^{(i_2)}\rangle_{\gamma_1^{(r)}}
  \nonumber \\
  &  & -s\beta^2 \sum_{k_1=2}^{2}  (\m_{k_1-1}-\m_{k_1}) p \mE_{G,{\mathcal U}_{r+1}}\langle (\x^{(p_1)})^T\x^{(i_1)}(\y^{(p_2)})^T\y^{(i_2)}\rangle_{\gamma_{21}^{(r)}}  \nonumber \\
  &  & + s\beta^2 \m_1 (p-1) \mE_{G,{\mathcal U}_{r+1}}\langle (\x^{(p_1)})^T\x^{(i_1)}(\y^{(p_2)})^T\y^{(i_2)}\rangle_{\gamma_{22}^{(r)}}
    \nonumber \\
  &  & -s\beta^2 \sum_{k_1=2}^{r+1}  (\m_{k_1-1}-\m_{k_1}) p \mE_{G,{\mathcal U}_{r+1}}\langle (\x^{(p_1)})^T\x^{(i_1)}(\y^{(p_2)})^T\y^{(i_2)}\rangle_{\gamma_{k_1}^{(r)}}.
\end{eqnarray}
With $\m_0=1$, $\gamma_{2}^{(r)}\triangleq \gamma_{21}^{(r)}$, and
\begin{eqnarray}\label{eq:rthlev2genanal38aa0}
\omega(x;p) \triangleq \begin{cases}
                         1, & \mbox{if } x=1 \\
                         p, & \mbox{otherwise}.
                       \end{cases},
\end{eqnarray}
 the above can also be  rewritten in a bit more compact form
\begin{eqnarray}\label{eq:rthlev2genanal39}
\sum_{i_1=1}^{l}\sum_{i_2=1}^{l}\sum_{j=1}^{m} \beta_{i_1 }\frac{T_{G,j}}{\sqrt{t}}
 & = & \beta^2  \lp \mE_{G,{\mathcal U}_{r+1}} \langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(r)}} +   (s-1)\mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2(\y^{(p_2)})^T\y^{(i_2)}\rangle_{\gamma_{02}^{(r)}}   \rp    \nonumber \\
   &  & -s\beta^2 \sum_{k_1=1}^{r+1}  (\m_{k_1-1}-\m_{k_1}) \omega(k_1;p)  \mE_{G,{\mathcal U}_{r+1}}\langle (\x^{(p_1)})^T\x^{(i_1)}(\y^{(p_2)})^T\y^{(i_2)}\rangle_{\gamma_{k_1}^{(r)}}
 \nonumber  \\
  &  & + s\beta^2 \m_1 (p-1) \mE_{G,{\mathcal U}_{r+1}}\langle (\x^{(p_1)})^T\x^{(i_1)}(\y^{(p_2)})^T\y^{(i_2)}\rangle_{\gamma_{22}^{(r)}} .
\end{eqnarray}







