%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

We summarize the above in the following theorem.
\begin{theorem}
\label{thm:thm3}
For any integer $r\geq 2$ let $k\in\{1,2,\dots,r+1\}$. Consider three vectors $\m=[\m_0,\m_1,\m_2,...,\m_r,\m_{r+1}]$, $\p=[\p_0,\p_1,...,\p_r,\p_{r+1}]$, and $\q=[\q_0,\q_1,\q_2,\dots,\q_r,\q_{r+1}]$  such that  $\m_0=1$, $\m_{r+1}=0$, $1\geq\p_0\geq \p_1\geq \p_2\geq \dots \geq \p_r\geq \p_{r+1} =0$, and $1\geq\q_0\geq \q_1\geq \q_2\geq \dots \geq \q_r\geq \q_{r+1} = 0$. Let the variances of the independent zero-mean  normal elements of $G\in\mR^{m\times n}$, $u^{(4,k)}\in\mR$, $\u^{(2,k)}\in\mR^m$, and $\h^{(k)}\in\mR^n$ be $1$, $\p_{k-1}\q_{k-1}-\p_k\q_k$, $\p_{k-1}-\p_{k}$, $\q_{k-1}-\q_{k}$, respectively.   Also, let sets ${\mathcal X}$, $\bar{{\mathcal X}}$, ${\mathcal Y}$, scalars $\beta$, $p$, $s$, and function $f_{\bar{\x}^{ ( i_3 ) } }   (\cdot) $  be as in Proposition \ref{thm:thm1}. For  ${\mathcal U}_k\triangleq [u^{(4,k)},\u^{(2,k)},\h^{(2k)}]$ we consider the following
\begin{equation}\label{eq:thm3eq1}
\psi(t)  =  \mE_{G,{\mathcal U}_{r+1}} \frac{1}{p|s|\sqrt{n}\m_r} \log
\lp \mE_{{\mathcal U}_{r}} \lp \dots \lp \mE_{{\mathcal U}_2}\lp\lp    \sum_{i_3=1}^{l} \lp \mE_{{\mathcal U}_1}  Z_{i_3}^{\m_1}\rp^p\rp^{\frac{\m_2}{\m_1}}\rp\rp^{\frac{\m_3}{\m_2}} \dots \rp^{\frac{\m_{r}}{\m_{r-1}}}\rp,
\end{equation}
where
\begin{eqnarray}\label{eq:thm3eq2}
Z_{i_3} & \triangleq & \sum_{i_1=1}^{l}\lp\sum_{i_2=1}^{l}e^{\beta D_0^{(i_1,i_2,i_3)}} \rp^{s} \nonumber \\
 D_0^{(i_1,i_2,i_3)} & \triangleq & \sqrt{t}(\y^{(i_2)})^T
 G\x^{(i_1)}+\sqrt{1-t}\|\x^{(i_1)}\|_2 (\y^{(i_2)})^T\lp\sum_{k=1}^{r+1}\u^{(2,k)}\rp\nonumber \\
 & & +\sqrt{t}\|\x^{(i_1)}\|_2\|\y^{(i_2)}\|_2\lp\sum_{k=1}^{r+1}u^{(4,k)}\rp +\sqrt{1-t}\|\y^{(i_2)}\|_2\lp\sum_{k=1}^{r+1}\h^{(k)}\rp^T\x^{(i_1)}
 + f_{\bar{\x}^{(i_3)}  } ( \x^{ (i_1) }  ). \nonumber \\
 \end{eqnarray}
For  $\zeta_k$ defined in (\ref{eq:rthlev2genanal7a}) and (\ref{eq:rthlev2genanal7b})   set
\begin{eqnarray}\label{eq:thm3eq4}
 \Phi_{{\mathcal U}_1}^{(i_3)} & \triangleq &  \mE_{{\mathcal U}_{1}} \frac{  Z_{i_3}^{\m_1}  } {  \mE_{{\mathcal U}_{1}} Z_{i_3}^{\m_1}  } \nonumber \\
 \Phi_{{\mathcal U}_k} & \triangleq &  \mE_{{\mathcal U}_{k}} \frac{\zeta_{k-1}^{\frac{\m_k}{\m_{k-1}}}}{\zeta_k} ,k\geq 2 \nonumber \\
 \gamma_{00}(i_3) & = &
\frac{  \lp  \mE_{{\mathcal U}_{1}} Z_{i_3}^{\m_1} \rp^p   }  { \sum_{i_3=1}^{l} \lp  \mE_{{\mathcal U}_{1}} Z_{i_3}^{\m_1} \rp^p   } \nonumber \\
 \gamma_0(i_1,i_2;i_3) & = &
\frac{(C_{i_3}^{(i_1)})^{s}}{Z_{i_3}}  \frac{A_{i_3}^{(i_1,i_2)}}{C_{i_3}^{(i_1)}} \nonumber \\
\gamma_{01}^{(r)}  & = & \prod_{k=r}^{2}\Phi_{{\mathcal U}_k} \gamma_{00}(i_3) \Phi_{{\mathcal U}_1}^{(i_3)} (\gamma_0(i_1,i_2;i_3))  \nonumber \\
\gamma_{02}^{(r)}  & = & \prod_{k=r}^{2} \Phi_{{\mathcal U}_k}   \gamma_{00}(i_3)    \Phi_{{\mathcal U}_1}^{(i_3)}   (\gamma_0(i_1,i_2;i_3)\times \gamma_0(i_1,p_2;i_3)) \nonumber \\
 \gamma_{1}^{(r)}  & = & \prod_{k=r}^{2} \Phi_{{\mathcal U}_k}   \gamma_{00}(i_3)    \Phi_{{\mathcal U}_1}^{(i_3)}   (\gamma_0(i_1,i_2;i_3)\times \gamma_0(p_1,p_2;i_3)) \nonumber \\
\gamma_{2}^{(r)} \triangleq \gamma_{21}^{(r)}  & = & \prod_{k=r}^{2}\Phi_{{\mathcal U}_k} \lp
  \gamma_{00}(i_3)    \Phi_{{\mathcal U}_1}^{(i_3)}   \gamma_0(i_1,i_2;i_3)\times
    \gamma_{00}(p_3)    \Phi_{{\mathcal U}_1}^{(p_3)}
  \gamma_0(p_1,p_2;p_3) \rp  \nonumber \\
\gamma_{22}^{(r)}  & = & \prod_{k=r}^{2}\Phi_{{\mathcal U}_k} \lp
  \gamma_{00}(i_3)  \lp  \Phi_{{\mathcal U}_1}^{(i_3)}   \gamma_0(i_1,i_2;i_3)\times
     \Phi_{{\mathcal U}_1}^{(i_3)}
  \gamma_0(p_1,p_2;i_3) \rp \rp \nonumber \\
\gamma_{k_1+1}^{(r)}  & = & \prod_{k=r}^{k_1+1}\Phi_{{\mathcal U}_k} \lp \prod_{k=k_1}^{2}\Phi_{{\mathcal U}_k}
  \gamma_{00}(i_3)    \Phi_{{\mathcal U}_1}^{(i_3)}   \gamma_0(i_1,i_2;i_3)\times \prod_{k=k_1}^{2} \Phi_{{\mathcal U}_k}
    \gamma_{00}(p_3)    \Phi_{{\mathcal U}_1}^{(p_3)}
  \gamma_0(p_1,p_2;p_3) \rp, k_1\geq 2. \nonumber \\
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
  \end{eqnarray}
For $k_1\geq 1$ and $\omega(x;p)$ as in (\ref{eq:rthlev2genanal38aa0}), let
\begin{eqnarray}\label{eq:thm3eq5}
 \phi_{k_1}^{(r)} & = &
-s(\m_{k_1-1}-\m_{k_1}) \omega(k_1;p) \nonumber \\
&  & \times
\mE_{G,{\mathcal U}_{r+1}} \langle (\p_{k_1-1}\|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2 -(\x^{(p_1)})^T\x^{(i_1)})(\q_{k_1-1}\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2 -(\y^{(p_2)})^T\y^{(i_2)})\rangle_{\gamma_{k_1}^{(r)}}
\nonumber \\
 \phi_{22}^{(r)} & = &
s \m_1(p-1) \nonumber \\
&  & \times
\mE_{G,{\mathcal U}_{r+1}} \langle (\p_{k_1-1}\|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2 -(\x^{(p_1)})^T\x^{(i_1)})(\q_{k_1-1}\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2 -(\y^{(p_2)})^T\y^{(i_2)})\rangle_{\gamma_{22}^{(r)}} \nonumber \\
 \phi_{01}^{(r)} & = & (1-\p_0)(1-\q_0)\mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(r)}} \nonumber\\
\phi_{02}^{(r)} & = & (s-1)(1-\p_0)\mE_{G,{\mathcal U}_{r+1}}\left\langle \|\x^{(i_1)}\|_2^2 \lp\q_0\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2-(\y^{(p_2)})^T\y^{(i_2)}\rp\right\rangle_{\gamma_{02}^{(r)}}. \end{eqnarray}

\noindent Then
\begin{eqnarray}\label{eq:thm3eq6}
\frac{d\psi(t)}{dt}  & = &       \frac{\mbox{sign}(s)\beta^2}{2\sqrt{n}} \lp  \lp\sum_{k_1=1}^{r+1} \phi_{k_1}^{(r)}\rp
+ \phi_{22}^{(r)}
+\phi_{01}^{(r)}+\phi_{02}^{(r)}\rp.
 \end{eqnarray}
For a particular choice $\p_0=\q_0=1$ one additionally has
\begin{eqnarray}\label{eq:rthlev2genanal43}
\frac{d\psi(t)}{dt}  & = &       \frac{\mbox{sign}(s)\beta^2}{2\sqrt{n}}
\lp  \sum_{k_1=1}^{r+1} \phi_{k_1}^{(r)}  + \phi_{22}^{(r)} \rp.
 \end{eqnarray}
 \end{theorem}
\begin{proof}
The $r=2$ scenario follows by results presented in  Proposition \ref{thm:thm2}. The $r\geq 3$ scenario
follows via a combination of (\ref{eq:rthlev2genanal10e})-(\ref{eq:rthlev2genanal10g}), (\ref{eq:rthlev2genanal27})-(\ref{eq:rthlev2genanal29}), (\ref{eq:rthlev2genanal39}), after one performs summing and canceling scaled terms while additionally  noting that, what was shown in (\ref{eq:lev2liftgenAanal19i}),  (\ref{eq:lev2liftgenBanal20b}), and (\ref{eq:lev2liftgenCanal21b}) for the  second level in an analogous manner holds for the $r$-th level as well. In particular, one has the following analogue of   (\ref{eq:lev2liftgenAanal19i})
\begin{eqnarray}\label{eq:rthlev2genanal40}
\sum_{i_1=1}^{l}\sum_{i_2=1}^{l}\sum_{j=1}^{m} \beta_{i_1}\frac{T_{1,1,j}}{\sqrt{1-t
}}
& = & \beta^2(\p_0-\p_1) \Bigg( \Bigg. \mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(r)}} \nonumber \\
& & +  (s-1)\mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2(\y^{(p_2)})^T\y^{(i_2)}\rangle_{\gamma_{02}^{(r)}} \Bigg.\Bigg)  \nonumber \\
& & - (\p_0-\p_1)s\beta^2(1-\m_1)\mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2(\y^{(p_2)})^T\y^{(i_2)} \rangle_{\gamma_1^{(r)}},
\end{eqnarray}
the following analogue of  (\ref{eq:lev2liftgenBanal20b})
\begin{eqnarray}\label{eq:rthlev2genanal41}
\sum_{i_1=1}^{l}\sum_{i_2=1}^{l} \beta_{i_1}\|\y^{(i_2)}\|_2 \frac{T_{1,2}}{\sqrt{1-t}}
& = & \beta^2(\q_0-\q_1)\Bigg( \Bigg.  \mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(r)}} \nonumber \\
& &
+   (s-1)\mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2 \|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2\rangle_{\gamma_{02}^{(r)}}\Bigg.\Bigg) \nonumber \\
& & - (\q_0-\q_1)s\beta^2(1-\m_1)\mE_{G,{\mathcal U}_{r+1}}\langle (\x^{(p_1)})^T\x^{(i_1)}\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2 \rangle_{\gamma_1^{(r)}},\nonumber \\
\end{eqnarray}
and the following analogue of (\ref{eq:lev2liftgenCanal21b})
  \begin{eqnarray}\label{eq:rthlev2genanal42}
\sum_{i_1=1}^{l}\sum_{i_2=1}^{l} \beta_{i_1}\|\y^{(i_2)}\|_2 \frac{T_{1,3}}{\sqrt{t}}
& = & \beta^2(\p_0\q_0-\p_1\q_1)\Bigg( \Bigg. \mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(r)}} \nonumber \\
& & +   (s-1)\mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2 \|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2\rangle_{\gamma_{02}^{(r)}}\Bigg.\Bigg)    \nonumber \\
& & - (\p_0\q_0-\p_1\q_1)s\beta^2(1-\m_1)\mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2\|\x^{(p_`)}\|_2\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2 \rangle_{\gamma_1^{(r)}}.\nonumber \\
\end{eqnarray}
The summing  and canceling out procedure works out in the same way for all three sequences, $\lp T_{k,1,j}\rp_{k=1:r+1}$, $\lp T_{k,2}\rp_{k=1:r+1}$, and $\lp T_{k,3}\rp_{k=1:r+1}$. To avoid showing the same mechanism repetitively, we present in details how it works for the first sequence. By trivial
adjustments of the results from the first part of Section \ref{sec:lev2handlT2} we have the following $r$ level analogue of (\ref{eq:lev2genDanal25})
\begin{eqnarray}\label{eq:rthlev2genanal43}
 \sum_{i_1=1}^{l}  \sum_{i_2=1}^{l} \sum_{j=1}^{m}  \beta_{i_1}\frac{T_{2,1,j}}{\sqrt{1-t}}
 & = & (\p_1-\p_2)\beta^2 \nonumber \\
 & & \times
  \lp \mE_{G,{\mathcal U}_{r+1}  }\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(r)}} +   (s-1)\mE_{G,{\mathcal U}_{r+1} }\langle \|\x^{(i_1)}\|_2^2(\y^{(p_2)})^T\y^{(i_2)}\rangle_{\gamma_{02}^{(r)}} \rp\nonumber \\
& & - (\p_1-\p_2)s\beta^2(1-\m_1)\mE_{G,{\mathcal U}_{r+1} }\langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2(\y^{(p_2)})^T\y^{(i_2)} \rangle_{\gamma_{1}^{(r)}}
\nonumber \\
 &   &
  -s\beta^2(\p_1-\p_2)(\m_1-\m_2) p \mE_{G,{\mathcal U}_{r+1}   } \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2(\y^{(p_2)})^T\y^{(i_2)} \rangle_{\gamma_{21}^{(r)}}
\nonumber \\
   &   &
+  s\beta^2(\p_1-\p_2) \m_1 (p-1) \mE_{G,{\mathcal U}_{r+1}  } \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2(\y^{(p_2)})^T\y^{(i_2)} \rangle_{\gamma_{22}^{(r)}}
\nonumber \\
 & = & (\p_1-\p_2)\beta^2 \nonumber \\
 & & \times \Bigg .\Bigg (
  \lp \mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(r)}} +   (s-1)\mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2(\y^{(p_2)})^T\y^{(i_2)}\rangle_{\gamma_{02}^{(r)}} \rp\nonumber \\
  &   &
  -s \sum_{v=1}^{2}  (\m_{v-1}-\m_v) \omega(v;p) \mE_{G,{\mathcal U}_{r+1}  } \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2(\y^{(p_2)})^T\y^{(i_2)} \rangle_{\gamma_{v}^{(r)}}
\nonumber \\
   &   &
+  s  \m_1 (p-1) \mE_{G,{\mathcal U}_{r+1}   } \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2(\y^{(p_2)})^T\y^{(i_2)} \rangle_{\gamma_{22}^{(r)}}
\Bigg .\Bigg ).
\end{eqnarray}
To generalize, we assume for $k_1\geq 2$
 \begin{eqnarray}\label{eq:rthlev2genanal44}
 \sum_{i_1=1}^{l}\sum_{i_2=1}^{l} \sum_{j=1}^{m}
\beta_{i_1} \frac{T_{k_1,1,j}}{\sqrt{1-t}}
 & = & \beta^2 (\p_{k_1-1}-\p_{k_1}) \Bigg( \Bigg. \mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(r)}} \nonumber \\
 & & +  (s-1)\mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2(\y^{(p_2)})^T\y^{(i_2)}\rangle_{\gamma_{02}^{(r)}}   \nonumber \\
 &  & - s \sum_{v=1}^{k_1} \lp \m_{v-1} -  \m_{v} \rp \omega(v;p)
  \mE_{G,{\mathcal U}_{r+1}} \left \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2 (\y^{(p_2)})^T \y^{(i_2)} \right \rangle_{\gamma_{v}^{(r)} }
  \nonumber \\
   &   &
+  s  \m_1 (p-1) \mE_{G,{\mathcal U}_{r+1}   } \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2(\y^{(p_2)})^T\y^{(i_2)} \rangle_{\gamma_{22}^{(r)}}
  \Bigg. \Bigg),\nonumber \\
\end{eqnarray}
and utilizing  (\ref{eq:rthlev2genanal27}) find
 \begin{eqnarray}\label{eq:rthlev2genanal45}
 \sum_{i_1=1}^{l}\sum_{i_2=1}^{l} \sum_{j=1}^{m}
\beta_{i_1} \frac{T_{k_1+1,1,j}}{\sqrt{1-t}}
 & = &  \frac{\p_{k_1}-\p_{k_1+1}}{\p_{k_1-1}-\p_{k_1}}\sum_{i_1=1}^{l}\sum_{i_2=1}^{l} \sum_{j=1}^{m}
\beta_{i_1} \frac{T_{k_1,1,j}}{\sqrt{1-t}} \nonumber \\
 &  & - \Bigg( \Bigg. s\beta^2(\p_{k_1}-\p_{k_1+1}) \lp \m_{k_1} -  \m_{k_1+1}
\rp  \omega(k_1;p)
  \nonumber \\
  & & \times
  \mE_{G,{\mathcal U}_{r+1}} \left \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2 (\y^{(p_2)})^T \y^{(i_2)} \right \rangle_{\gamma_{k_1+1}^{(r)} } \Bigg. \Bigg) \nonumber \\
 & = &  \frac{\p_{k_1}-\p_{k_1+1}}{\p_{k_1-1}-\p_{k_1}}\beta^2 (\p_{k_1-1}-\p_{k_1}) \Bigg( \Bigg. \mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(r)}} \nonumber \\
 & & +  (s-1)\mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2(\y^{(p_2)})^T\y^{(i_2)}\rangle_{\gamma_{02}^{(r)}}   \nonumber \\
 &  & - s \sum_{v=1}^{k_1} \lp \m_{v-1} -  \m_{v} \rp \omega(v;p)
  \nonumber \\
  & & \times
  \mE_{G,{\mathcal U}_{r+1}} \left \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2 (\y^{(p_2)})^T \y^{(i_2)} \right \rangle_{\gamma_{v}^{(r)} }
        \nonumber \\
   &   &
+  s  \m_1 (p-1) \mE_{G,{\mathcal U}_{r+1}   } \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2(\y^{(p_2)})^T\y^{(i_2)} \rangle_{\gamma_{22}^{(r)}}
    \Bigg. \Bigg) \nonumber \\
   &  & - \Bigg( \Bigg. s \beta^2(\p_{k_1}-\p_{k_1+1}) \lp \m_{k_1} -  \m_{k_1+1} \rp \omega(k_1;p)
  \nonumber \\
  & & \times
  \mE_{G,{\mathcal U}_{r+1}} \left \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2 (\y^{(p_2)})^T \y^{(i_2)} \right \rangle_{\gamma_{k_1+1}^{(r)} }
 \Bigg. \Bigg)
   \nonumber \\
 & = &  \beta^2 (\p_{k_1}-\p_{k_1+1}) \Bigg( \Bigg. \mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(r)}} \nonumber \\
 & & +  (s-1)\mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2(\y^{(p_2)})^T\y^{(i_2)}\rangle_{\gamma_{02}^{(r)}}   \nonumber \\
 &  & - s \sum_{v=1}^{k_1+1} \lp \m_{v-1} -  \m_{v} \rp \omega(v;p)
  \mE_{G,{\mathcal U}_{r+1}} \left \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2 (\y^{(p_2)})^T \y^{(i_2)} \right \rangle_{\gamma_{v}^{(r)} }
    \nonumber \\
   &   &
+  s  \m_1 (p-1) \mE_{G,{\mathcal U}_{r+1}   } \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2(\y^{(p_2)})^T\y^{(i_2)} \rangle_{\gamma_{22}^{(r)}}
    \Bigg. \Bigg)
. \nonumber \\
    \end{eqnarray}
Since (\ref{eq:rthlev2genanal44}) holds for $k_1=2$, (\ref{eq:rthlev2genanal45}) ensures that it actually holds for any $k_1\in\{1,2,\dots,r+1\}$. Finally summing over $k_1$ and utilizing \cite{Stojnicnflgscompyx23}'s (249) we obtain
 \begin{eqnarray}\label{eq:rthlev2genanal46}
 \sum_{k_1=1}^{r+1}\sum_{i_1=1}^{l}\sum_{i_2=1}^{l} \sum_{j=1}^{m}
\beta_{i_1} \frac{T_{k_1,1,j}}{\sqrt{1-t}}
 & = & \beta^2  \sum_{k_1=1}^{r+1}  (\p_{k_1-1}-\p_{k_1}) \Bigg( \Bigg. \mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(r)}} \nonumber \\
 & & +  (s-1)\mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2(\y^{(p_2)})^T\y^{(i_2)}\rangle_{\gamma_{02}^{(r)}}   \nonumber \\
 &  & - s \sum_{v=1}^{k_1} \lp \m_{v-1} -  \m_{v} \rp \omega(v;p)
  \mE_{G,{\mathcal U}_{r+1}} \left \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2 (\y^{(p_2)})^T \y^{(i_2)} \right \rangle_{\gamma_{k_1}^{(r)} }
\Bigg. \Bigg)
       \nonumber \\
   &   &
+  s  \sum_{k_1=2}^{r+1}  (\p_{k_1-1}-\p_{k_1})  \m_1 (p-1) \mE_{G,{\mathcal U}_{r+1}   } \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2(\y^{(p_2)})^T\y^{(i_2)} \rangle_{\gamma_{22}^{(r)}}
\nonumber \\
  & = & \beta^2 (\p_{0}-\p_{r+1}) \Bigg( \Bigg. \mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(r)}} \nonumber \\
 & & +  (s-1)\mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2(\y^{(p_2)})^T\y^{(i_2)}\rangle_{\gamma_{02}^{(r)}}  \Bigg. \Bigg) \nonumber \\
 &  & - s  \beta^2\sum_{v=1}^{r+1} \p_{v-1}\lp \m_{v-1} -  \m_{v} \rp \omega(v;p) \mE_{G,{\mathcal U}_{r+1}} \left \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2 (\y^{(p_2)})^T \y^{(i_2)} \right \rangle_{\gamma_{v}^{(r)} }
        \nonumber \\
   &   &
+  s  \beta^2 \p_{1}  \m_1 (p-1) \mE_{G,{\mathcal U}_{r+1}   } \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2(\y^{(p_2)})^T\y^{(i_2)} \rangle_{\gamma_{22}^{(r)}}
 .\nonumber \\
\end{eqnarray}
We then analogously find for the other two sequences
 \begin{eqnarray}\label{eq:rthlev2genanal47}
 \sum_{k_1=1}^{r+1}\sum_{i_1=1}^{l}\sum_{i_2=1}^{l}
\beta_{i_1}\|\y^{(i_2)}\|_2 \frac{T_{k_1,2}}{\sqrt{1-t}}
   & = & \beta^2 (\q_{0}-\q_{r+1}) \Bigg( \Bigg. \mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(r)}} \nonumber \\
 & & +  (s-1)\mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2 \|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2\rangle_{\gamma_{02}^{(r)}} \Bigg. \Bigg)  \nonumber \\
 &  & - s \beta^2 \sum_{v=1}^{r+1} \q_{v-1}\lp \m_{v-1} -  \m_{v} \rp   \omega(v;p)
  \nonumber \\
  & & \times
  \mE_{G,{\mathcal U}_{r+1}} \left \langle \|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2 (\x^{(p_1)})^T \x^{(i_1)} \right \rangle_{\gamma_{v}^{(r)} }
          \nonumber \\
   &   &
+  s  \beta^2 \p_{1}  \m_1 (p-1) \mE_{G,{\mathcal U}_{r+1}   } \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2(\y^{(p_2)})^T\y^{(i_2)} \rangle_{\gamma_{22}^{(r)}},
\nonumber \\
\end{eqnarray}
and
 \begin{eqnarray}\label{eq:rthlev2genanal48}
 \sum_{k_1=1}^{r+1}\sum_{i_1=1}^{l}\sum_{i_2=1}^{l}
\beta_{i_1}\|\y^{(i_2)}\|_2 \frac{T_{k_1,3}}{\sqrt{t}}
   & = & \beta^2 (\p_{0}\q_{0}-\p_{r+1}\q_{r+1}) \Bigg( \Bigg. \mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(r)}} \nonumber \\
 & & +  (s-1)\mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2\rangle_{\gamma_{02}^{(r)}} \Bigg. \Bigg)  \nonumber \\
 &  & - s  \sum_{v=1}^{r+1} \p_{v-1}\q_{v-1}\lp \m_{v-1} -  \m_{v} \rp   \omega(v;p)
 \nonumber \\
 & & \times
 \mE_{G,{\mathcal U}_{r+1}} \left \langle \|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2 \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2 \right \rangle_{\gamma_{v}^{(r)} }
         \nonumber \\
   &   &
+  s  \beta^2 \p_{1}  \m_1 (p-1) \mE_{G,{\mathcal U}_{r+1}   } \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2(\y^{(p_2)})^T\y^{(i_2)} \rangle_{\gamma_{22}^{(r)}}
, \nonumber \\
\end{eqnarray}
Combining (\ref{eq:rthlev2genanal10e})-(\ref{eq:rthlev2genanal10g}), (\ref{eq:rthlev2genanal39}), and (\ref{eq:rthlev2genanal46})-(\ref{eq:rthlev2genanal48}) one obtains that (\ref{eq:thm3eq5}) and (\ref{eq:thm3eq6}) indeed hold.
\end{proof}


















