    \centering
    \includegraphics[width=\linewidth]{Figures/overlap_sectioned.png}
    \caption{An overview of the zippering process. (a) the color palette from the OpenVCAD design is sub-divided into a user defined number of colors with a bandwidth $\alpha$. Overlap regions are inserted in between the original sub-division with a bandwidth of $\beta$. (b) when the design is segmented into individual colors, paths that are in the overlapping region are alternatively assigned to adjacent colors to create the zipper.}
    \label{fig:overlap}
\end{figure}

\begin{algorithm}[]
\caption{Zippering Toolpaths with Overlapping Regions}
\label{alg:zippered_toolpaths}
\KwIn{Geometric outline,Color Palette, List of Faces and their colors, Overlap width (\(\beta\))}
\KwOut{Zippered toolpaths with overlapping regions and color labels}
\BlankLine
\SetKwBlock{StepOne}{Step 1: Generate Traditional Toolpaths}{end}
\SetKwBlock{StepTwo}{Step 2: Section Toolpaths by Color}{end}
\SetKwBlock{StepThree}{Step 3: Introduce Overlapping Regions}{end}
\SetKwBlock{StepFour}{Step 4: Return Zippered Toolpaths}{end}

\StepOne{
    Generate standard toolpaths with the geometric outline.
}
\StepTwo{
    \ForEach{face in faces list}{
        Compute intersections between toolpaths and the face.\\
        Label intersected toolpaths with the face's color.
    }
}
\StepThree{
    \ForEach{pair of adjacent colors}{
        Define the overlap region with width \(\beta\).\\
        \ForEach{toolpath in the overlap region}{
            Alternate assignment of toolpaths to the first or second color.\\
            Optimize toolpath order to minimize the change in color.
        }
    }
}
\StepFour{
    Return toolpaths organized by color, including overlapping regions.
}
\end{algorithm}

