    \includegraphics[width=\linewidth]{Figures/overlap_complex.png}
    \caption{Zippering is added to the $XY$ gradient given in Figure \ref{fig:complex_section} and Equation \ref{eq:color_distributions}. As $\beta$ increases the zippering distance also increases. }
