\title{Conditions for eigenvalue configurations of  two real symmetric matrices: a symmetric function approach}
\author[1]{Hoon Hong\thanks{hong@ncsu.edu}}
\affil[1]{{Department of Mathematics, North Carolina State University, Raleigh, NC, USA}}
\author[1]{Daniel Profili\thanks{daprofil@ncsu.edu}}
