\section{Problem}

\label{sec:problem}In this section, we will state the problem precisely. For
this we first need a few notations and a notion.

\begin{notation}
\label{basic_notation}\ \ 
\end{notation}

\begin{enumerate}
\item Let $F, G$ be $n\times n$ real symmetric matrices with simple and distinct eigenvalues.

\item Let $\alpha=\left(  \alpha_{1},\ldots,\alpha_{n}\right)  $ be the
eigenvalues of$\ F$. 

Let $\beta=\left(  \beta_{1},\ldots,\beta_{n}\right)  $ \ be the eigenvalues
of $G$. 

Since $F$ and $G$ are real symmetric, all their eigenvalues are real. Thus,
without losing generality, let us index the eigenvalues so that
\begin{align*}
\alpha_{1}  &  <\alpha_{2}<\cdots<\alpha_n\\
\beta_{1}  &  <\beta_{2}<\cdots<\beta_{n}%
\end{align*}


\item Let $I_{t}=[\alpha_{t},\alpha_{t+1})$ for $t=1,\ldots,n$, where
$\alpha_{n+1}=\infty$.
\end{enumerate}

\begin{definition}
[Eigenvalue Configuration]\label{def:EC}The eigenvalue configuration, or eigen configuration, of $F$
and $G$, written as $EC\left(  F,G\right)  $, is the tuple $c=(c_{1}%
,\dots,c_{m})$ where $c_{t}=\#\{i:\beta_{i}\in I_{t}\}$.
\end{definition}

\begin{example}
Let $F, G\ $be such that the corresponding eigenvalues are given by
\[
\alpha=(1,3,7,9,12)\qquad\beta=(-1,2,8,10,11)
\]
Then%
\[%
\begin{array}
[c]{ll}%
I_{1}=[\alpha_{1},\alpha_{2})=[1,3) & \ni \beta_2\\
I_{2}=[\alpha_{2},\alpha_{3})=[3,7) &  \\
I_{3}=[\alpha_{3},\alpha_{4})=[7,9) & \ni \beta_3 \\
I_{4}=[\alpha_{4},\alpha_{5})=[9,12) & \ni \beta_4, \beta_5\\
I_{5}=[\alpha_{5},\infty)=[12,\infty) & \\
\end{array}
\]
Therefore
\[
EC(F,G)=(1,0,1,2,0).
\]

\end{example}

\noindent {The challenge is to develop  an algorithm
for the following problem.}

\begin{problem}
\ 

\begin{enumerate}
\item[In:\ ] $n$ a positive integer

$c$ an eigenvalue configuration.

\item[Out:] a \textquotedblleft simple\ condition\textquotedblright\ on the
entries of $n\times n\ $real symmetric matrices $F\ $and $G$ such that $c=EC\left(  F,G\right)  $.
\end{enumerate}
\end{problem}

\begin{remark}
\label{rem:problem}Here we clarify what the problem is precisely and what the
challenge is.

\begin{itemize}
\item \textsf{What is the problem precisely?} It amounts to clarifying what
\textquotedblleft simple\textquotedblright\ condition means.

For this, we first write down the definition of $EC$ condition explicitly, by
stating all the implicit assumptions.
\[
c=EC\left(  F,G\right)  \ \ \ :\Longleftrightarrow\ \ \ \underset{\beta
_{1},\ldots,\beta_{n}}{\underset{\alpha_{1},\ldots,\alpha_{n}}{\exists}%
}\bigwedge\left(
\begin{array}
[c]{l}%
\left\vert \alpha_{1}I_{n}-F\right\vert =0\\
\,\,\,\,\vdots\\
\left\vert \alpha_{n}I_{n}-F\right\vert =0\\
\underset{x}{\forall}\left\vert xI_{n}-F\right\vert =0\Longrightarrow\left(
x=\alpha_{1}\wedge\cdots\wedge x=\alpha_{n}\right) \\
\\
\left\vert \beta_{1}I_{n}-G\right\vert =0\\
\,\,\,\,\vdots\\
\left\vert \beta_{n}I_{n}-G\right\vert =0\\
\underset{x}{\forall}\left\vert xI_{n}-G\right\vert \ =0\Longrightarrow\left(
x=\beta_{1}\wedge\cdots\wedge x=\beta_{n}\right) \\
\\
\beta_{1}<\cdots<\beta_{c_{0}}<\alpha_{1}\\
\alpha_{1}<\beta_{c_{0}+1}<\cdots<\beta_{c_{0}+c_{1}}<\alpha_{2}\\
\,\,\,\,\vdots\\
\alpha_{m}<\beta_{c_{0}+c_{1}+\cdots+c_{m-1}+1}<\cdots<\beta_{n}%
\end{array}
\right)
\]
where $c_{0}$ is a short hand for $n-c_{1}-\cdots-c_{n}$. The top block states
that all the eigenvalues of $F$ are exactly $\alpha_{1},\ldots,\alpha_{n}$.
The middle block states that all the eigenvalues of $G$ are exactly $\beta
_{1},\ldots,\beta_{n}$. The bottom block states that the eigen configuration
is given by $c$.

Note that the whole expression is a quantified boolean combination of
polynomial equations and inequalities, so-called ``a well-formed formula in
the first order theory of real closed fields''. It involves the following
variables: the entries of $F$ and $G$ and the eigenvalues $\alpha$ and $\beta$
and another variable $x$. The condition is not \textquotedblleft
simple\textquotedblright\ in the sense that it involves quantified variables,
namely $\alpha,\beta$ and $x$.

Alfred Tarski's celebrated theorem on real closed fields states that every
first order formula is equivalent to a quantifier-\emph{free}
formula.~\cite{Tarski:30}. Thus, by \textquotedblleft simple\textquotedblright%
\ condition, we mean a quantifier-\emph{free} formula in the entries of $F,G$;
more concretely, a boolean combination of polynomial equations and
inequalities in the entries of $F$ and $G$.

\item \textsf{What is the challenge?} Tarski's proof was constructive, that
is, the proof provided the first algorithm for eliminating
quantifiers~\cite{Tarski:51}. Since then, various alternative and/or improved
algorithms have been developed, to list a just a few \cite{ Tarski:30,
Tarski:51, McCallum:84, Ben-Or_Kozen_Reif:86,Grigorev:88,Weispfenning:95,
Gonzalez_Lombardi_Recio_Roy:89, Hong:90a, Hong:90b, Collins_Hong:91, Hong:92a,
Renegar:92a,Canny:93a,Loos_Weispfenning:93, Weispfenning:94b,
Gonzalez-Vega:96, DBLP:journals/jsc/McCallum99, DBLP:conf/issac/McCallumB09,
DBLP:journals/jsc/Brown01a, DBLP:journals/jsc/Brown01, Strzebonski06,
DBLP:conf/issac/ChenMXY09, DBLP:journals/jsc/Brown12, Hong_Safey:2012}. Some
of them have fully implemented software packages:
QEPCAD~\cite{Hong:90b,Collins_Hong:91,Brown2004}, Reduce in
Mathematica~\cite{Strzebonski06}, RedLog~\cite{SturmW96}, SyNRAC
\cite{Yanami_Anai}, Discoverer~\cite{discoverer}, OpenCAD~\cite{opencad},
RAGlib~\cite{raglib}, Regular Chain~\cite{DBLP:conf/issac/ChenMXY09} and so
on. Thus one might wonder whether we could just run those software on the
above quantified formula. However there are two major difficulties: (1) It
requires that we need to run the software on each $n$ from scratch.
(2) Each run (on each $n$) quickly becomes very time-consuming as
and $n$ grows, making this approach practically infeasible and (2) The output
formula looks chaotic, making it practically incomprehensible.

Thus, the \textsf{challenge} is to produce a quantifier-free formula for
\textsf{all} $n$ \textsf{efficiently} and in a \textsf{structured} form.
\end{itemize}
\end{remark}
\section{Main Result}
\label{sec:main}

Before we state our main result, we first establish some notation.

\begin{notation}
\label{notation}\ \ 

\begin{enumerate}
\item $v(p)$, for a univariate polynomial $p$ with real coefficients, denotes
the sign variation count of $p$; that is, the number of times two consecutive
coefficients of $p$ have opposite sign, ignoring zeros.

$v(s)$, for a sign sequence $s \in \{-, 0, +\}^n$, denotes the number of times consecutive elements in $s$ have opposite sign, ignoring zeros.

\item $\sigma_{j}(X)$, for a list of variables $X$, denotes the $j$-th
elementary symmetric polynomial in $X$; that is,
\[
\sigma_{j}(X):=\sum_{1\leq i_{1}<\dots<i_{j}\leq n}\ \prod_{k=1}^{j}X_{i_{k}}%
\]


\item $Q_{r}$, for a positive integer $r$, is defined as
\[
Q_{r}:=\left\{  \left(  i_{1},\ldots,i_{r},j\right)  :1\leq i_{1}%
<\cdots<i\,_{r}\leq n\ \ \wedge\ \ 1\leq j\leq n\right\}
\]


\item $q_{r}$, for a positive integer $r$, is defined as
\[
q_{r}:=\#\left\{  \left(  i_{1},\ldots,i_{r},j\right)  \in Q_{r}:\prod
_{p=1}^{r}\left(  \alpha_{i_{p}}-\beta_{j}\right)  <0\right\}  ,
\]
where $\#S$ denotes the number of elements of a finite set $S$.

\item $h_{r}$, for a positive integer $r$, is defined as
\[
h_{r}:=\prod\limits_{\left(  i_{1},\ldots,i_{r},j\right)  \in Q_{r}}\left(
x-\prod_{p=1}^{r}\left(  \alpha_{i_{p}}-\beta_{j}\right)  \right)
\]


