We also have
\[
g=|xI-G|=(x-0)(x-3)(x-5)=x^{3}-8x^{2}+15x-0.
\]
Hence
\begin{align*}
b_{1}  &  =8\\
b_{2}  &  =15\\
b_{3}  &  =0.
\end{align*}

\end{enumerate}
\end{example}

\begin{theorem}
[Main Result]\label{main} Let $c=(c_{1},\dots,c_{n})$ be an eigenvalue
configuration and let $F,G\in\mathbb{R}^{n\times n}$ be symmetric.. Then
\[
EC(F,G)=c\iff\bigwedge_{r=1}^{n}v(p_{r}(-x))=(T_{n}c)_{r},
\]
where
\begin{align*}
p_{r}  &  =\text{polynomial such that }h_{r}(x,\alpha_{1},\dots,\alpha
_{n},\beta_{1},\dots,\beta_{n})=p_{r}(x,a_{1},\dots,a_{n},b_{1},\dots
,b_{n}).
\end{align*}

\end{theorem}

\begin{remark}
The key idea of Theorem \ref{main} is that in the logical equivalence
\[
\underbrace{EC(F,G)=c}_{\text{involves quantifiers (eigenvalues of } F,
G)}\iff\underbrace{\bigwedge_{r=1}^{n}v(p_{r}(-x))=(T_{n}c)_{r}}%
_{\text{involves only polynomial operations, }c, \,\, \wedge, \,\, \vee,
\text{ entries of } F, G},
\]
the left-hand side, when fully expanded in terms of the entries of $F$ and
$G$, involves quantifiers, since eigenvalue configurations are defined in
terms of the eigenvalues of $F$ and $G$. In contrast, the right-hand side
consists of a disjunction of conjunctions of polynomial equations and
inequalities involving the entries of $F$ and $G$, with \textbf{no reference}
to the eigenvalues of $F$ and $G$ and therefore \textbf{no quantifiers}.
\end{remark}

\section{Derivation of the Main Result}
\label{sec:proof}

We present the proof of Theorem \ref{main} in the style of a derivation. This
approach will allow us to better illustrate the key ideas behind this
approach. To do this, we split up the derivation into several lemmas, each of
which illustrates one key idea.

Our overall goal is to somehow express the information encoded in the
eigenvalue configuration in a way which does not refer directly to the
eigenvalues of $F$ and $G$. In order to do this, we will first define a vector
$q = (q_{1}, \dots, q_{n})$ which encodes the information contained in the
eigenvalue configuration vector in a way that allows us to compute it via
counting the roots of a certain polynomial. We accomplish this via an
invertible linear transformation $T_{n}$ whose entries are defined
combinatorially. But first, we show that such a transformation exists.

\begin{lemma}
[Transform]\label{Tdef}We have
\[
c=EC\left(  F,G\right)  \ \ \ \ \Longrightarrow\ \ \ \ q=T_{n}c
\]
where%
\[
q=%
\begin{pmatrix}
q_{1}\\
\vdots\\
q_{n}%
\end{pmatrix}
\ \ \text{and }c=%
\begin{pmatrix}
c_{1}\\
\vdots\\
c_{n}%
\end{pmatrix}
\ \ \text{and\ \ }T_{n}=%
\begin{pmatrix}
(T_{n})_{11} & \cdots & (T_{n})_{1n}\\
\vdots &  & \vdots\\
(T_{n})_{n1} & \cdots & (T_{n})_{nn}%
\end{pmatrix}
\]
and where%
\[
(T_{n})_{rs}=\#\left\{  \left(  i_{1},\ldots,i_{r}\right)  :1\leq i_{1}%
<\cdots<i_{r}\leq n\ \ \wedge\ \ \#\left\{  p:i_{p}\leq s\right\}
=odd\right\}  .
\]

\end{lemma}

\begin{proof}
Assume that $c=EC\left(  F,G\right)  $. It suffices to show $q=T_{n}c$. Recall
from Notation \ref{notation} that
\[
Q_{r}=\left\{  \left(  i_{1},\ldots,i_{r},j\right)  :1\leq i_{1}%
<\cdots<i\,_{r}\leq n\ \ \wedge\ \ 1\leq j\leq n\right\}  ,
\]
and
\[
q_{r}=\#\left\{  \left(  i_{1},\ldots,i_{r},j\right)  \in Q_{r}:\prod
_{p=1}^{r}\left(  \alpha_{i_{p}}-\beta_{j}\right)  <0\right\}  .
\]
We proceed by repeatedly rewriting the definition of $q_{r}$, with the goal of
expressing it in terms of the eigenvalue configuration vector. We begin with
the definition of $q_{r}$.
\[
q_{r}=\#\left\{  \left(  i_{1},\ldots,i_{r},j\right)  \in Q_{r}:\prod
_{p=1}^{r}\left(  \alpha_{i_{p}}-\beta_{j}\right)  <0\right\}
\]
Note that for each $(i_{1},\dots,i_{r})$ satisfying $1\leq i_{1}<\cdots
<i_{r}\leq n$, we also have $(i_{1},\dots,i_{r},j)\in Q_{r}$ simply by
appending each $j=1,\dots,n$. Hence, we can rewrite this action of counting
over the set $Q_{r}$ as a summation over all such tuples $(i_{1},\dots,i_{r}%
)$. Thus we obtain
\[
q_{r}=\sum_{1\leq i_{1}<\cdots<i_{r}\leq n}\ \#\left\{  j:\prod_{p=1}%
^{r}\left(  \alpha_{i_{p}}-\beta_{j}\right)  <0\right\}
\]
We can then introduce another summation by partitioning the set on the
right-hand side depending on which interval $I_{s}$ each $\beta_{j}$ belongs
to.
\[
q_{r}=\sum_{1\leq s\leq n}\ \sum_{1\leq i_{1}<\cdots<i_{r}\leq n}\ \#\left\{
j:\beta_{j}\in I_{s}\ \ \wedge\ \ \prod_{p=1}^{r}\left(  \alpha_{i_{p}}%
-\beta_{j}\right)  <0\right\}
\]
Then, we eliminate the product symbol by observing that the product
$\prod_{p=1}^{r}(\alpha_{i_{p}}-\beta_{j})$ is negative if and only if there
are an odd number of $p$'s such that $\alpha_{i_{p}}-\beta_{j}<0$, or
equivalently $\alpha_{i_{p}}<\beta_{j}$.%

\begin{align*}
q_{r}  &  =\sum_{1\leq s\leq n}\ \sum_{1\leq i_{1}<\cdots<i_{r}\leq
n}\ \#\left\{  j:\beta_{j}\in I_{s}\ \ \wedge\ \ \#\left\{  p:\alpha_{i_{p}%
}<\beta_{j}\right\}  =odd\right\}
\end{align*}
Next, we use the fact that the $\alpha$'s are indexed in ascending order, and
we note that $\alpha_{i_{p}} < \beta_{j}$ if and only if $i_{p} \le s$, since
$\beta_{j} \in I_{s}$. Thus
\begin{align*}
q_{r}  &  =\sum_{1\leq s\leq n}\ \sum_{1\leq i_{1}<\cdots<i_{s}\leq
n}\ \#\left\{  j:\beta_{j}\in I_{s}\ \ \wedge\ \ \#\left\{  p:i_{p}\leq
s\right\}  =odd\right\}
\end{align*}
Now, note that if $\# \{p : i_{p} \le s\}$ is even, then the size of the set
in the summand is zero. If $\# \{p : i_{p} \le s\}$ is odd, then the size of
the set in the summand equals $\#\{j : \beta_{j} \in I_{s}\}$, which is
exactly $c_{s}$. Hence
\begin{align*}
q_{s}  &  =\sum_{1\leq s\leq n}\ \sum_{1\leq i_{1}<\cdots<i_{r}\leq n}\left\{
%
\begin{array}
[c]{ll}%
0 & \text{if\ \ }\#\left\{  p:i_{p}\leq s\right\}  =even\\
c_{s} & \text{if\ \ }\#\left\{  p:i_{p}\leq s\right\}  =odd
\end{array}
\right.
\end{align*}


Next, we factor out the $c_{s}$ and move it outside the innermost summation.
\begin{align*}
q_{r} &  =\sum_{1\leq s\leq n}\ \sum_{1\leq i_{1}<\cdots<i_{r}\leq n}\left(
\left\{
\begin{array}
[c]{ll}%
0 & \text{if\ \ }\#\left\{  p:i_{p}\leq s\right\}  =even\\
1 & \text{if\ \ }\#\left\{  p:i_{p}\leq s\right\}  =odd
\end{array}
\right.  c_{s}\right)  \\
&  =\sum_{1\leq s\leq n}\ \left(  \sum_{1\leq i_{1}<\cdots<i_{r}\leq
n}\left\{
\begin{array}
[c]{ll}%
0 & \text{if\ \ }\#\left\{  p:i_{p}\leq r\right\}  =even\\
1 & \text{if\ \ }\#\left\{  p:i_{p}\leq r\right\}  =odd
\end{array}
\right.  \right)  c_{s}%
\end{align*}
Then, we fold the conditional into the summation.
\[
q_{r}=\sum_{1\leq s\leq n}\left(  \sum_{\substack{1\leq i_{1}<\cdots<i_{r}\leq
n\\\#\left\{  p:i_{p}\leq s\right\}  =odd}}1\right)  c_{s}%
\]
Since the innermost summand is just a summation of 1's, we can view it as
counting the elements of the set $\{(i_{1},\dots,i_{r}):1\leq i_{1}%
<\cdots<i_{r}\leq n\,\wedge\,\#\{p:i_{p}\leq s\}=\text{odd}\}$.
\[
q_{r}=\sum_{1\leq s\leq n}(T_{n})_{rs}c_{s}%
\]
where
\[
(T_{n})_{rs}=\#\left\{  \left(  i_{1},\ldots,i_{r}\right)  :1\leq i_{1}%
<\cdots<i_{r}\leq n\ \ \wedge\ \ \#\left\{  p:i_{p}\leq s\right\}
=odd\right\}  .
\]
By the definition of matrix multiplication, this is just the multiplication of
the vector $c=(c_{1},\dots,c_{n})^{T}$ by the matrix $T_{n}$ whose entries are
defined as above. Thus%
\[
\left(
\begin{array}
[c]{c}%
q_{1}\\
\vdots\\
q_{n}%
\end{array}
\right)  =\left(
\begin{array}
[c]{ccc}%
(T_{n})_{11} & \cdots & (T_{n})_{1n}\\
\vdots &  & \vdots\\
(T_{n})_{n1} & \cdots & (T_{n})_{nn}%
\end{array}
\right)  \left(
\begin{array}
[c]{c}%
c_{1}\\
\vdots\\
c_{n}%
\end{array}
\right)
\]
that is%
\[
q=T_{n}c.
\]

\end{proof}

\begin{lemma}
\label{inv} $T_{n}$ is invertible.
\end{lemma}

\begin{proof}
It suffices to prove that $\left\vert T_{n}\right\vert \neq0$. We prove it in
several stages. First, we establish a recurrence relation for the entries of
$T_{n}$, and then apply that to decompose $T_{n}$ into a product of triangular
matrices to more easily compute the determinant.

\bigskip

\noindent{\sf Claim 1:} We have%
\[
(T_{n})_{rs}=\left\{
\begin{array}
[c]{ll}%
s & \text{if }\left(  r,s\right)  \in\left\{  1\right\}  \times\left\{
1,\ldots,n\right\} \\
\left\{
\begin{array}
[c]{ll}%
1 & \text{if }s\ \text{is odd}\\
0 & \text{if }s\ \text{is even}%
\end{array}
\right.  & \text{if }\left(  r,s\right)  \in\left\{  n\right\}  \times\left\{
1,\ldots,n\right\} \\
\left\{
\begin{array}
[c]{ll}%
\left(
\begin{array}
[c]{c}%
n\\
r
\end{array}
\right)  & \text{if }r\ \text{is odd}\\
0 & \text{if }r\ \text{is even}%
\end{array}
\right.  & \text{if }\left(  r,s\right)  \in\left\{  2,\ldots,n-1\right\}

\times\left\{  n\right\} \\
(T_{n-1})_{r-1,s}+(T_{n-1})_{r,s} & \text{if }\left(  r,s\right)  \in\left\{
2,\ldots,n-1\right\}  \times\left\{  1,\ldots,n-1\right.\}.
\end{array}
\right.
\]
Proof of the claim: There are four cases in the above. We will prove them one
by one.

\begin{enumerate}
\item $\left(  r,s\right)  \in\left\{  1\right\}  \times\left\{
1,\ldots,n\right\}  $.

By definition, we have
\[
(T_{n})_{1s}=\#\left\{  \left(  i_{1}\right)  :1\leq i_{1}\leq n\ \ \wedge
\ \ \#\left\{  p:i_{p}\leq s\right\}  =odd\right\}  .
\]
Since we are only considering $i_{1}$, then $\#\{p:i_{p}\leq s\}$ can only be
zero or one. If that quantity is zero, then $(T_{n})_{1,s}$ is zero, since
zero is even. If instead $\#\{p:i_{p}\leq s\}=1$, then $1\leq i_{1}\leq s$, so
there are $s$ choices for $i_{1}$. Thus $(T_{n})_{1,s}=s$.

\item $\left(  r,s\right)  \in\left\{  n\right\}  \times\left\{
1,\ldots,n\right\}  $.

By definition, we have
\begin{align*}
(T_{n})_{ns}  &  =\#\left\{  \left(  i_{1},\ldots,i_{n}\right)  :1\leq
i_{1}<\cdots<i_{n}\leq n\ \ \wedge\ \ \#\left\{  p:i_{p}\leq s\right\}
=odd\right\} \\
&  =\#\left\{  \left(  1,\ldots,n\right)  :\#\left\{  p:p\leq s\right\}
=odd\right\} \\
&  =\#\left\{  \left(  1,\ldots,n\right)  :s=odd\right\} \\
&  =\left\{
\begin{array}
[c]{ll}%
1 & \text{if }s\ \text{is odd}\\
0 & \text{if }s\ \text{is even}%
\end{array}
\right.
\end{align*}


\item $\left(  r,s\right)  \in\left\{  2,\ldots,n-1\right\}  \times\left\{
n\right\}  $.

By definition of $(T_{n})_{rs}$ we have
\[
(T_{n})_{rn}=\#\left\{  \left(  i_{1},\ldots,i_{r}\right)  :1\leq i_{1}%
<\cdots<i_{r}\leq n\ \ \ \wedge\ \ \ \#\left\{  p:1\leq p\leq r\ \ \wedge
\ \ i_{p}\leq n\right\}  =\text{odd}\right\}  .
\]
But $i_{p}\leq n$ trivially, so $\#\{p:1\leq p\leq r\ \wedge\ i_{p}\leq
n\}=\#\{p:1\leq p\leq r\}$. Therefore
\begin{align*}
(T_{n})_{rn}  &  =\#\left\{  \left(  i_{1},\ldots,i_{r}\right)  :1\leq
i_{1}<\cdots<i_{r}\leq n\ \ \ \wedge\ \ \ \#\left\{  1,\ldots,r\right\}
=\text{odd}\right\} \\
&  =\#\left\{  \left(  i_{1},\ldots,i_{r}\right)  :1\leq i_{1}<\cdots
<i_{r}\leq n\ \ \ \wedge\ \ \ r=\text{odd}\right\} \\
&  =\left\{
\begin{array}
[c]{ll}%
\#\left\{  \left(  i_{1},\ldots,i_{r}\right)  :1\leq i_{1}<\cdots<i_{r}\leq
n\right\}  & \text{if }r\ \text{is odd}\\
\#\left\{  {}\right\}  & \text{if }r\ \text{is even}%
\end{array}
\right. \\
&  =\left\{
\begin{array}
[c]{ll}%
\left(
\begin{array}
[c]{c}%
n\\
r
\end{array}
\right)  & \text{if }r\ \text{is odd}\\
0 & \text{if }r\ \text{is even}%
\end{array}
\right.
\end{align*}


\item $\left(  r,s\right)  \in\left\{  2,\ldots,n-1\right\}  \times\left\{
1,\ldots,n-1\right\}  $.

By definition, we have%
\[
(T_{n})_{rs}=\#\left\{  \left(  i_{1},\ldots,i_{r}\right)  :1\leq i_{1}%
<\cdots<i_{r}\leq n\ \ \wedge\ \ \#\left\{  p:i_{p}\leq s\right\}
=odd\right\}  .
\]
We can partition the set whose elements we are counting into elements with
$i_{r}<n$ and those with $i_{r}=n$.%
\begin{align*}
(T_{n})_{rs}  &  =\#\left\{  \left(  i_{1},\ldots,i_{r}\right)  :1\leq
i_{1}<\cdots<i_{r}=n\ \ \wedge\ \ \#\left\{  p:i_{p}\leq s\right\}
=odd\right\}  +\\
&  \#\left\{  \left(  i_{1},\ldots,i_{r}\right)  :1\leq i_{1}<\cdots
<i_{r}<n\ \ \wedge\ \ \#\left\{  p:i_{p}\leq s\right\}  =odd\right\}  .
\end{align*}
If $i_{r}=n$, then $(i_{1},\dots,i_{r-1})$ is a tuple such that $1\leq
i_{1}<\cdots<i_{r}\leq n-1$. In addition, we still have that $\#\{p:i_{p}\leq
s\}$ is odd, because $s<n$. These are exactly the tuples that are counted by
$(T_{n-1})_{r-1,s}$; thus
\begin{align*}
&  \#\left\{  \left(  i_{1},\ldots,i_{r}\right)  :1\leq i_{1}<\cdots
<i_{r}=n\ \ \wedge\ \ \#\left\{  p:i_{p}\leq s\right\}  =odd\right\} \\
=  &  \#\left\{  \left(  i_{1},\ldots,i_{r-1}\right)  :1\leq i_{1}%
<\cdots<i_{r-1}\leq n-1\ \ \wedge\ \ \#\left\{  p:i_{p}\leq s\right\}
=odd\right\} \\
=  &  (T_{n-1})_{r-1,s}.
\end{align*}
On the other hand, if $i_{r}<n$, then $(i_{1},\dots,i_{r})$ is a tuple
satisfying $1\leq i_{1}<\cdots<i_{r}\leq n-1$ and again $\#\{p:i_{p}\leq s\}$
remains odd. These tuples are counted by $(T_{n})_{r,s}$, and so
\begin{align*}
&  \#\left\{  \left(  i_{1},\ldots,i_{r}\right)  :1\leq i_{1}<\cdots
<i_{r}<n\ \ \wedge\ \ \#\left\{  p:i_{p}\leq s\right\}  =odd\right\} \\
=  &  \#\left\{  \left(  i_{1},\ldots,i_{r}\right)  :1\leq i_{1}<\cdots
<i_{r}\leq n-1\ \ \wedge\ \ \#\left\{  p:i_{p}\leq s\right\}  =odd\right\} \\
=  &  (T_{n-1})_{r,s}.
\end{align*}
Putting those together, we get that
\[
(T_{n})_{rs}=(T_{n-1})_{r-1,s}+(T_{n-1})_{r,s}.
\]

\end{enumerate}

\noindent We have proved Claim 1.

\bigskip

\noindent {\sf Claim 2:} We have
\[
T_{n}=L_{n}U_{n}%
\]
where
\[
(L_{n})_{rs}=\left(
\begin{array}
[c]{c}%
n-s\\
r-s
\end{array}
\right)  \ \ \ \,\text{and \ }\ (U_{n})_{rs}=\left(  -2\right)  ^{r-1}\left(
\begin{array}
[c]{c}%
s\\
r
\end{array}
\right)
\]
Proof of the claim. It suffices to show%
\[
(T_{n})_{rs}=\sum_{t=1}^{n}(L_{n})_{rt}(U_{n})_{ts}%
\]
We proceed by induction on $n$. Note that when $n=1$, we have
\[
1=(T_{1})_{11}=\binom{1-1}{1-1}(-2)^{1-1}\binom{1}{1}=L_{1}U_{1}.
\]
For the induction hypothesis, suppose the claim is true for some $n-1$. We
will prove the claim for $n$. There are four cases in the above. We will prove
them one by one.

\begin{enumerate}
\item $\left(  r,s\right)  \in\left\{  1\right\}  \times\left\{
1,\ldots,n\right\}  $.

We have
\begin{align*}
&  \sum_{t=1}^{n}(L_{n})_{1t}(U_{n})_{ts}\\
&  =\sum_{t=1}^{n}\binom{n-t}{1-t}(-2)^{t-1}\binom{s}{t}\\
&  =\binom{n-1}{1-1}(-2)^{1-1}\binom{s}{1}\ \ \ \ \text{since }\binom
{n-t}{1-t}=0\ \text{for }t>1\\
&  =s\\
&  =(T_{n})_{1s}%
\end{align*}


\item $\left(  r,s\right)  \in\left\{  n\right\}  \times\left\{
1,\ldots,n\right\}  $.

We have
\begin{align*}
&  \sum_{t=1}^{n}(L_{n})_{nt}(U_{n})_{ts}\\
&  =\sum_{t=1}^{n}\left(
\begin{array}
[c]{c}%
n-t\\
n-t
\end{array}
\right)  \left(  -2\right)  ^{t-1}\left(
\begin{array}
[c]{c}%
s\\
t
\end{array}
\right) \\
&  =\sum_{t=1}^{s}\left(  -2\right)  ^{t-1}\left(
\begin{array}
[c]{c}%
s\\
t
\end{array}
\right)  \ \ \,\,\,\text{since }\left(
\begin{array}
[c]{c}%
s\\
t
\end{array}
\right)  =0\ \,\text{for }t>s\\
&  =\frac{1}{-2}\left(  -1+\sum_{t=0}^{s}\left(  1\right)  ^{s-t}\left(
-2\right)  ^{t}\left(
\begin{array}
[c]{c}%
s\\
t
\end{array}
\right)  \right) \\
&  =\frac{1}{-2}\left(  -1+\left(  1-2\right)  ^{s}\right) \\
&  =\left\{
\begin{array}
[c]{ll}%
1 & \text{if }s\ \text{is odd}\\
0 & \text{if }s\ \text{is even}%
\end{array}
\right. \\
&  =\left(  T_{n}\right)  _{ns}%
\end{align*}


\item $\left(  r,s\right)  \in\left\{  2,\ldots,n-1\right\}  \times\left\{
n\right\}  $.

We have
\begin{align*}
\sum_{t=1}^{n}(L_{n})_{rt}(U_{n})_{tn}  &  =\sum_{t=1}^{n}\binom{n-t}%
{r-t}(-2)^{t-1}\binom{n}{t}\\
&  =\sum_{t=1}^{n}\frac{\left(  n-t\right)  !}{\left(  n-r\right)  !\left(
r-t\right)  !}(-2)^{t-1}\frac{n!}{\left(  n-t\right)  !t!}\\
&  =\sum_{t=1}^{n}\frac{n!}{\left(  n-r\right)  !}\frac{1}{\left(  r-t\right)
!t!}(-2)^{t-1}\\
&  =\sum_{t=1}^{n}\frac{n!}{\left(  n-r\right)  !r!}\frac{r!}{\left(
r-t\right)  !t!}(-2)^{t-1}\\
&  =\sum_{t=1}^{n}\left(
\begin{array}
[c]{c}%
n\\
r
\end{array}
\right)  \left(
\begin{array}
[c]{c}%
r\\
t
\end{array}
\right)  (-2)^{t-1}\\
&  =\left(
\begin{array}
[c]{c}%
n\\
r
\end{array}
\right)  \sum_{t=1}^{n}\left(
\begin{array}
[c]{c}%
r\\
t
\end{array}
\right)  (-2)^{t-1}\\
&  =\left(
\begin{array}
[c]{c}%
n\\
r
\end{array}
\right)  \left(  \frac{1}{-2}\left(  -1+\sum_{t=0}^{n}\left(
\begin{array}
[c]{c}%
r\\
t
\end{array}
\right)  \left(  1\right)  ^{r-t}(-2)^{t}\right)  \right) \\
&  =\left(
\begin{array}
[c]{c}%
n\\
r
\end{array}
\right)  \left(  \frac{1}{-2}\left(  -1+\left(  1-2\right)  ^{r}\right)
\right) \\
&  =\left\{
\begin{array}
[c]{ll}%
\left(
\begin{array}
[c]{c}%
n\\
r
\end{array}
\right)  & \text{if }r\ \text{is odd}\\
0 & \text{if }r\ \text{is even}%
\end{array}
\right. \\
&  =\left(  T_{n}\right)  _{rn}%
\end{align*}


\item $\left(  r,s\right)  \in\left\{  2,\ldots,n-1\right\}  \times\left\{
1,\ldots,n-1\right\}  $.

Recall that we have
\[
(T_{n})_{rs}=(T_{n-1})_{r-1,s}+(T_{n-1})_{r,s}.
\]
By the induction hypothesis, we have
\begin{align*}
(T_{n})_{rs}  &  =\sum_{t=1}^{n-1}(L_{n-1})_{r-1,t}(U_{n-1})_{t,s}+\sum
_{t=1}^{n-1}(L_{n-1})_{r,t}(U_{n-1})_{t,s}\\
&  =\sum_{t=1}^{n-1}(L_{n-1})_{r-1,t}(U_{n-1})_{t,s}+(L_{n-1})_{r,t}%
(U_{n-1})_{t,s}\\
&  =\sum_{t=1}^{n-1}((L_{n-1})_{r-1,t}+(L_{n-1})_{r,t})(U_{n-1})_{t,s}\\
&  =\sum_{t=1}^{n-1}\left(  \binom{n-1-t}{r-1-t}+\binom{n-1-t}{r-t}\right)
(U_{n-1})_{t,s}\\
&  =\sum_{t=1}^{n-1}\binom{n-t}{r-t}(U_{n-1})_{t,s}\\
&  =\sum_{t=1}^{n-1}(L_{n})_{r,t}(U_{n-1})_{t,s}.
\end{align*}
But $(U_{n-1})_{t,s}$ does not depend on $n$. Thus $(U_{n-1})_{t,s}%
=(U_{n})_{t,s}$. Hence
\begin{align*}
(T_{n})_{rs}  &  =\sum_{t=1}^{n-1}(L_{n})_{r,t}(U_{n})_{t,s}\\
&  =\sum_{t=1}^{n-1}(L_{n})_{r,t}(U_{n})_{t,s}+\underbrace{\binom{n-n}%
{r-n}(-2)^{r-1}\binom{s}{n}}_{=0\text{ since }s<n}\\
&  =\sum_{t=1}^{n}(L_{n})_{r,t}(U_{n})_{t,s}.
\end{align*}

\end{enumerate}

\noindent We have proved Claim 2.

\bigskip

\noindent Now note that $L_{n}$ is lower triangular, since if $s>r$ then
$r-s<0$ and so $\binom{n-s}{r-s}=0$. Similarly, $U_{n}$ is upper triangular,
since if $r>s$ then $\binom{s}{r}=0$. Further, we have
\[
|L_{n}|=\prod_{t=1}^{n}(L_{n})_{tt}=\prod_{t=1}^{n}\binom{n-t}{t-t}%
=\prod_{t=1}^{n}\binom{n-t}{0}=\prod_{t=1}^{n}1=1,
\]
and
\[
|U_{n}|=\prod_{t=1}^{n}(U_{n})_{tt}=\prod_{t=1}^{n}(-2)^{t-1}\binom{t}%
{t}=\prod_{t=1}^{n}(-2)^{t-1}=(-2)^{0+1+\dots+n-1}=(-2)^{\binom{n}{2}}.
\]
Thus we have
\[
|T_{n}|=|L_{n}||U_{n}|=(-2)^{\binom{n}{2}}\neq0\text{.}%
\]
Hence $T_{n}$ is invertible.
\end{proof}

\begin{remark}
In the previous proof, as a stepping stone toward proving that $T_{n}$ is
invertible we showed that $T_{n}$ has the decomposition $T_{n} = L_{n} U_{n}$
where
\[
(L_{n})_{rs}=\left(
\begin{array}
[c]{c}%
n-s\\
r-s
\end{array}
\right)  \ \ \text{and\ \ } (U_{n})_{rs}=\left(  -2\right)  ^{r-1}\left(
\begin{array}
[c]{c}%
s\\
r
\end{array}
\right)  .
\]
These are combinatorially beautiful matrices for which we provided no
combinatorial interpretation. This is one focus of our future work in this
area, as the matrix $T_{n}$ has many interesting combinatorial aspects which
we did not have time or space to address in this paper.
\end{remark}

Now, we can summarize Lemmas \ref{Tdef} and \ref{inv} into the following lemma.

\begin{lemma}
\label{iff} We have
\[
EC(F, G) = c \ \ \iff\ \ q = T_{n} c.
\]

\end{lemma}

\begin{proof}
Lemma \ref{Tdef} shows that $EC(F, G) = c \implies q = T_{n} c$. Lemma
\ref{inv} shows that $T_{n}$ is invertible, hence $T_{n}$ is a 1-1 linear map.
Therefore, we have that $q = T_{n} c \implies EC(F, G) = c.$
\end{proof}

At this point, we have found an equivalent condition for $EC(F,G)=c$. However,
this condition still contains quantifiers, as it references the eigenvalues of
$F$ and $G$. The remainder of the derivation will focus on solving this issue,
by introducing symmetric polynomials $h_{r}$ whose roots can be counted to
produce an equivalent condition in terms of the entries of $F$ and $G$ only,
and not their eigenvalues.

\begin{lemma}
\label{hk} We have
\[
q_{r}=\# \text{ of negative roots of } h_{r}.
\]

\end{lemma}

\begin{proof}
Recall that by definition we have
\[
h_{r}:=\prod\limits_{\left(  i_{1},\ldots,i_{r},j\right)  \in Q_{r}}\left(
x-\prod_{p=1}^{r}\left(  \alpha_{i_{p}}-\beta_{j}\right)  \right)  .
\]
The roots of $h_{r}$ are, by construction, exactly the products $\prod
_{p=1}^{r} (\alpha_{i_{p}} - \beta_{j})$. Hence the negative roots of $h_{r}$
are exactly what is counted by $q_{r}$.
\end{proof}

Notice that $h_{r}$ is a symmetric polynomial with real roots. This is the
crucial fact which allows us to construct another polynomial $p_{r}$ involving
the \textit{entries} of $F$ and $G$ rather than their \textit{eigenvalues}.
This will eliminate the quantifiers.

\begin{proposition}
\label{ftsp} For each $r = 1, \dots, n$, there exists $p_{r}\in\mathbb{R}%
\left[  x, a_{1}, \dots, a_{n}, b_{1}, \dots, b_{n} \right]  $ such that
\[
h_{r} = p_{r}(x, a_{1}, \dots, a_{n}, b_{1}, \dots, b_{n}).
\]

\end{proposition}

\begin{proof}
\ For the purposes of this proof, we view $h_{r}$ as being a polynomial in $x,
\alpha_{1}, \dots, \alpha_{n}, \beta_{1}, \dots, \beta_{n}$, with real coefficients.

Note that by construction $h_{r}$ is symmetric in $\alpha_{1},\dots,\alpha
_{n}$. Recall that by the Fundamental Theorem of Symmetric Polynomials, this
means that there exists a polynomial $p_{\alpha}\in\mathbb{Z}[x, y_{1}%
,\dots,y_{n}]$ such that
\[
h_{r}(x,\alpha_{1},\dots,\alpha_{n},\beta_{1},\dots,\beta_{n})=p_{\alpha
}(x,\sigma_{1}(\alpha),\dots,\sigma_{n}(\alpha)).
\]


Further note $h_{r}$ is also symmetric in $\beta_{1},\dots,\beta_{n}$; hence
$p_{\alpha}$ is symmetric in $\beta_{1},\dots,\beta_{n}$. Thus by again
applying the Fundamental Theorem of Symmetric Polynomials, there exists a
polynomial $p_{r}\in\mathbb{Z}[x,y_{1},\dots,y_{n}][z_{1},\dots,z_{n}]$ such
that
\[
p_{\alpha}(x,y_{1},\dots,y_{n})=p_{r}(x,\sigma_{1}(\alpha),\dots,\sigma
_{n}(\alpha),\sigma_{1}(\beta),\dots,\sigma_{n}(\beta)).
\]


Now, combining these together, we have that
\begin{align*}
p_{r}(x,\sigma_{1}(\alpha),\dots,\sigma_{n}(\alpha),\sigma_{1}(\beta
),\dots,\sigma_{1}(\beta))  &  =p_{\alpha}(x,\sigma_{1}(\alpha),\dots
,\sigma_{n}(\alpha))\\
&  =h_{r}(x,\alpha_{1},\dots,\sigma_{n},\beta_{1},\dots,\beta_{n}).
\end{align*}


Finally, note that
\begin{align*}
a_{1}  &  =\sum_{1\leq i_{1}\leq n}\alpha_{i_{1}}=\alpha_{1}+\cdots+\alpha
_{n}=\sigma_{1}(\alpha)\\
a_{2}  &  =\sum_{1\leq i_{1}<i_{2}\leq n}\alpha_{i_{1}}\alpha_{i_{2}}%
=\sigma_{2}(\alpha)\\
&  \vdots\\
a_{n}  &  =\sum_{1\leq i_{1}<\cdots<i_{n}\leq n}\alpha_{i_{1}}\cdots
\alpha_{i_{n}}=\alpha_{1}\cdots\alpha_{n}=\sigma_{n}(\alpha).
\end{align*}
Similarly
\begin{align*}
b_{1}  &  =\sigma_{1}(\beta)\\
&  \vdots\\
b_{n}  &  =\sigma_{n}(\beta).
\end{align*}


Hence, we have that
\begin{align*}
h_{r}(x,\alpha_{1},\dots,\alpha_{n},\beta_{1},\dots,\beta_{n})  &  = p_{r}(x,
\underbrace{\sigma_{1}(\alpha)}_{a_{1}}, \dots, \underbrace{\sigma_{n}%
(\alpha)}_{a_{n}}, \underbrace{\sigma_{1}(\beta)}_{b_{1}}, \dots,
\underbrace{\sigma_{n}(\beta)}_{b_{n}})\\
&  =p_{r}(x,a_{1},\dots,a_{n},b_{1},\dots,b_{n})
\end{align*}

\end{proof}

With that, we are ready to prove the main result (Theorem \ref{main}).

\begin{proof}
[\textbf{Proof of Main Result (Theorem \ref{main})}] \ 

Let $q=%
\begin{pmatrix}
q_{1}\\
\vdots\\
q_{n}%
\end{pmatrix}
=T_{n}c$.
For each $r=1,\dots,n$, by Proposition \ref{ftsp} there exists $p_{r}%
\in\mathbb{R}[x,a_{1},\dots,a_{n},b_{1},\dots,b_{n}]$ such that
\[
h_{r}(x,\alpha_{1},\dots,\alpha_{n},\beta_{1},\dots,\beta_{n})=p_{r}(x,a_{1},
\dots, a_{n}, b_{1}, \dots, b_{n}).
\]
Note by Lemma \ref{hk}
\begin{align*}
q_{r}  &  =\#\text{ negative roots of }h_{r}(x)\\
&  =\#\text{ negative roots of }p_{r}(x)\\
&  =\#\text{ positive roots of }p_{r}(-x)\\
&  =v(p_{r}(-x))\,\text{by Descartes' rule of signs, since all roots of }%
p_{r}\text{ are real}.
\end{align*}
Therefore, we have that
\[
  q = T_n c \, \, \iff \, \, \bigwedge_{r=1}^n v(p_r(-x)) = (T_nc)_r.
  \]
Finally, by Lemmas \ref{Tdef} and \ref{inv}, we have
\[
EC(F,G)=c\,\,\iff \,\, q = T_n c \, \, \iff \,\, \underbrace{\bigwedge_{r=1}^{n}v(p_{r}(-x))=(T_{n} c)_{r}}_{P}.
\]
Note that each $v(p_{r}(-x)) = (T_nc)_r$ is a logical disjunction (see Algorithm \ref{alg:main} and Remark \ref{rmk}) involving the
coefficients of $p_{r}$ as viewed as a polynomial in $x$, whose coefficients
are themselves polynomials in $a_{1},\dots,a_{n},b_{1},\dots,b_{n}$. Hence the
expression $P$ is a quantifier-free condition which is equivalent to
$EC(F,G)=c$.
\end{proof}

