\section{Algorithms}
\label{sec:algorithms}

\begin{algorithm}
[TM]\ \ 

\begin{itemize}
\item[In :] $n,$ positive integer

\item[Out:] $T_{n} \in\mathbb{Z}^{n \times n}$ such that $q = T_{n}c$ for any
eigenvalue configuration $c$ of $n \times n$ matrices.
\end{itemize}

\begin{enumerate}
% \item If $n=1$ then return $\left[  1\right]  $.

% \item For $s=1,\ldots,n$

% $\qquad(T_{n})_{1s}\longleftarrow s $

