% \qquad\qquad$(T_{n})_{rs}\longleftarrow(T_{n-1})_{r-1,s}+(T_{n-1})_{r,s}$

\item $(T_n)_{rs} \longleftarrow \sum_{t=1}^{n} \binom{n-t}{r-t} (-2)^{r-1} \binom{s}{t}$

