\end{enumerate}
\end{algorithm}

\begin{algorithm}
[pv]\ \ 

\begin{itemize}
\item[In :] 

\begin{enumerate}
\item $n \ge1$

\item $r \in\{1, \dots, n\}$
\end{enumerate}

\item[Out:] $p_{r} \in \mathbb{R}[x, \alpha_1, \dots, a_n, b_1, \dots, b_n]$ such that $h_{r} = p_{r}(x,a_{1}, \dots, a_{n}, b_{1},
\dots, b_{n})$
\end{itemize}

\begin{enumerate}
\item $h_{r} \longleftarrow\prod\limits_{\left(  i_{1},\ldots,i_{r},j\right)
\in Q_{r}}\left(  x-\prod_{p=1}^{r}\left(  \alpha_{i_{p}}-\beta_{j}\right)
\right)  $

\item $p_{\alpha}\longleftarrow$ polynomial such that $h_{r} = p_{\alpha}(x,
\sigma_{1}(\alpha), \dots, \sigma_{1}(\beta))$
\label{ftsp1}

\item $p_{r} \longleftarrow$ polynomial such that $p_{\alpha}= p_{r}(x,
\sigma_{1}(\beta), \dots, \sigma_{1}(\beta))$
\label{ftsp2}

\item Return $p_{r} \in \mathbb{R}[x, a_{1}, \dots, a_{n}, b_{1}, \dots, b_{n}]$
\end{enumerate}
\end{algorithm}

\begin{remark}
  Lines \ref{ftsp1} and \ref{ftsp2} of the previous algorithm rely on the Fundamental Theorem of Symmetric Polynomials, the proof and algorithm for which can be found in many algebra texts.
\end{remark}

\begin{algorithm}
[EC]\ 
\label{alg:main}
\begin{itemize}
\item[In: ] $c,\ $the eigen configuration

\item[Out:] $P,$ condition on $F$ and $G$ such that $c=EC\left(  F,G\right)  $
\end{itemize}

\begin{enumerate}
\item $F\longleftarrow$ with indeterminate entries

$G\longleftarrow$ with indeterminate entries

\item $f\longleftarrow\left\vert xI-F\right\vert $ $\ $where $f=x^{n}%
-a_{1}x^{n-1}+a_{2}x^{n-2}+\cdots+\left(  -1\right)  ^{n}a_{n}x^{0}$

$g\longleftarrow\left\vert xI-G\right\vert \ \ $where $g=x^{n}-b_{1}%
x^{n-1}+b_{2}x^{n-2}+\cdots+\left(  -1\right)  ^{n}b_{n}x^{0}$

\item $q\longleftarrow TM(n) \ast c$

\item for $r=1,\ldots,n$ do

\begin{enumerate}
\item $p_{r}\longleftarrow pv(n, r)  $

\item $P_{r}\longleftarrow$ the condition on $a_{1},\ldots,a_{n},b_{1}%
,\ldots,b_{n}$ such that \# of negative roots of $p_{r}$ is $q_{r}$.
\label{cond}
\end{enumerate}

\item $P\longleftarrow\underset{r}{\wedge}P_{r}$

\item Return $P$
\end{enumerate}
\end{algorithm}

\begin{remark}
  \label{rmk}
  Line \ref{cond} of the previous algorithm is a succinct way of expressing the following procedure, which enumerates all possibilities for the signs of the coefficients $p_r(-x)$ satisfying a given sign variation count.
  \begin{enumerate}
  \item For each sign sequence $s \in \{-, 0, +\}^n$ such that $v(s) = q_r$ do

    \qquad $P_r \longleftarrow P_r \vee \left( \bigwedge_{i=1}^n sign(\text{coeff}(p_r(-x), x^i)) = s_i \right)$
  \end{enumerate}
\end{remark}

