% \end{proof}

\begin{restatable}{lemma}{DefeasibleCorrespondence}
    \label{lemma:correspondence-conditionals-propositional-preferential}
    A defeasible implication $\phi_\mathcal{M} \twiddle \psi_\mathcal{M}$ over $\mathcal{M}$ is satisfied by a preferential interpretation $\mathcal{P}$ if and only if the compound attribute counterpart $\phi \twiddle \psi$ is satisfied in the derived preferential context $\mathbb{P}^\mathcal{P}$. 
\end{restatable}

While the consequence relation induced by a derived preferential context is not strictly equivalent to that of the corresponding propositional interpretation; \Cref{lemma:correspondence-propositional-compound} and \Cref{lemma:correspondence-conditionals-propositional-preferential} establish a systematic correspondence between the two. These results show that the inferential structure of a propositional consequence relation can be faithfully reflected in the compound attribute language of a preferential context.

% \begin{proof}
%     \Cref{lemma:correspondence-propositional-compound} shows the correspondence between satisfaction of propositional formulae by states in a preferential interpretation, and satisfaction of compound attributes by objects in a preferential context. By construction the preference relation on states corresponds exactly to the relation on objects, and there is a bijection between states and objects. Then, the minimal states satisfying a propositional formula correspond to the minimal objects satisfying the respective compound attribute, and any further inferences that are true for the minimal states are also true for the minimal objects. 

% \end{proof}

\begin{restatable}[Completeness of Preferential Contexts]{theorem}{CompletenessP}
    \label{theorem:representation-preferential-contexts}
	A consequence relation is preferential if and only if it can be induced by some preferential context $\mathbb{P}$. 
\end{restatable}

