\Equivalence*

\begin{proof}
    We begin with the \textit{if} part and assume $\minDerivation{\phi} \subseteq \psi$. For an object $g \in \minDerivation{\phi}$ it is clear that $g \in \phi^\downarrow \cap \psi^\downarrow$. We assume that $g \not \in \underline{\phi^\downarrow \cap \psi^\downarrow}$ and thus the existence of some $h \in \phi^\downarrow \cap \psi^\downarrow$ with $h \prec g$. By basic set theory it should follow that $h \in \phi^\downarrow$, but this causes a contradiction since $g$ is minimal in $\phi^\downarrow$ but $h \prec g$. So no such $h$ can exist, which implies $g \in \underline{\phi^\downarrow \cap \psi^\downarrow}$. Then, we assume $g \in \underline{\phi^\downarrow \cap \psi^\downarrow}$. If $g \not \in \minDerivation{\phi}$ there exists some $h \in \minDerivation{\phi}$ such that $h \prec g$, but we have just shown $\minDerivation{\phi} \subseteq \underline{\phi^\downarrow \cap \psi^\downarrow}$. So $h \in \underline{\phi^\downarrow \cap \psi^\downarrow}$, which is a contradiction since $g \in \underline{\phi^\downarrow \cap \psi^\downarrow}$. Therefore, $\underline{\phi^\downarrow \cap \psi^\downarrow} \subseteq \minDerivation{\phi}$   

    The \textit{only if} part of the proof is trivial. 

\end{proof}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Soundness for Preferential Contexts
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\SoundnessP*

\begin{proof}
	The proofs for (REF), (RW), and (AND) are quite obvious and thus omitted. (LLE) is also obvious when we recognise that two attributes are equivalent when they have the same extension. 
%   
    For the (OR) postulate, we have that $\phi \twiddle \gamma$ and $\psi \twiddle \gamma$, and so $\minDerivation{\phi} \subseteq \gamma^\downarrow$ and $\minDerivation{\psi} \subseteq \gamma^\downarrow$. For some $g \in \underline{\phi^\downarrow \cup \psi^\downarrow}$ it follows that $g \in \phi^\downarrow$ or $g \in \psi^\downarrow$ (or both), and that there cannot be some $h \in \phi^\downarrow \cup \psi^\downarrow$ such that $h \prec g$.  If $g \in \phi^\downarrow$ then $g \in \minDerivation{\phi}$, and similarly if $g \in \psi^\downarrow$ then $g \in \minDerivation{\psi}$.  In either case, by our assumption it follows that $g \in \gamma^\downarrow$.  Since $g$ was an arbitrary, we have that $\underline{\phi^\downarrow \cup \psi^\downarrow} \subseteq \gamma^\downarrow$, which is precisely $\phi \lor \psi \twiddle \gamma$. 
%
    To show (CUT) we assume $\minDerivation{\phi} \subseteq \psi^\downarrow$ and $\underline{\phi^\downarrow \cap \psi^\downarrow} \subseteq \gamma^\downarrow$. By \Cref{lemma1} we have $\minDerivation{\phi} = \underline{\phi^\downarrow \cap \psi^\downarrow}$. Then from equality we get $\minDerivation{\phi} \subseteq \gamma^\downarrow$ which is the condition for $\phi \twiddle_\mathbb{P} \gamma$. 
%
    The proof for (CM) is similar to (CUT). We assume $\minDerivation{\phi} \subseteq \psi^\downarrow$ and $\minDerivation{\phi} \subseteq \gamma^\downarrow$. Once again we use \Cref{lemma1} and get $\minDerivation{\phi} = \underline{\phi^\downarrow \cap \psi^\downarrow}$. Then, by set equality $\underline{\phi^\downarrow \cap \psi^\downarrow} \subseteq \gamma^\downarrow$ which gives us $\phi \land \psi \twiddle \gamma$.

\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Lemma correspondence compound attributes
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\Correspondence*

\begin{proof}
    By construction of a derived context, an object $g_s \Vdash m$ if and only if the corresponding state satisfies the reciprocal propositional atom, $l(s) \Vdash m_\mathcal{M}$. That this correspondence holds for conjunction is clear. If $l(s) \Vdash \neg m_\mathcal{M}$ then we have $l(s) \nVdash m_\mathcal{M}$ and by definition of a derived context, $g_s \nVdash m$; it then follows that $g \in G \setminus m^\downarrow$ and so $g \Vdash \neg m$. For disjunction, let $l(s) \Vdash m_\mathcal{M} \lor n_\mathcal{M}$ then it needs to be shown that $g_s \in m^\downarrow \cup n^\downarrow$. Let $l(s)\Vdash m_\mathcal{M}$, then, from before, $g_s \Vdash m$ and $g_s \in m^\downarrow \cup n^\downarrow$. The same argument applies to the case where $l(s) \Vdash n_\mathcal{M}$. 

\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Lemma correspondence compound attributes
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\DefeasibleCorrespondence*

\begin{proof}
    Let $\mathbb{P}^{\mathcal{P}}=(G,M,I, \prec_*)$ and assume for some $g_s\in G$ assume $g_s\notin \underline{\alpha^{\downarrow}}$. Equivalently, either $g_s\notin\alpha^{\downarrow}$ or $g_s\in\alpha^{\downarrow}$ and there exists some $g_t\in G$ with $g_t\prec_* g_s$. In the first case $l(s)\notin \llbracket\alpha_\mathcal{M}\rrbracket$. In the second case, this is equivalent to $l(s)\in\llbracket\alpha_\mathcal{M}\rrbracket$, and there exists $t\in S$ such that $t\prec s$ and $l(t)\Vdash \alpha_\mathcal{M}$. That is, $g_s\notin \underline{\alpha^{\downarrow}}$ iff. $s\notin \min_{\prec}\llbracket\alpha_\mathcal{M}\rrbracket$.\\

    Then $\phi_{\mathcal{M}}\twiddle\psi_{\mathcal{M}}$, iff. $\min_{\prec}\llbracket\phi_\mathcal{M}\rrbracket\subseteq \llbracket\psi_{\mathcal{M}}\rrbracket$. By the previous paragraph $g_s\in \underline{\phi^{\downarrow}}$ iff. $s\in \min_{\prec}\llbracket\phi_\mathcal{M}\rrbracket$, and from Lemma \ref{lemma:correspondence-propositional-compound} we have that $g_s\in\psi^\downarrow$ iff. $s\in\llbracket\psi_{\mathcal{M}}\rrbracket$. Therefore, $\min_{\prec}\llbracket\phi_\mathcal{M}\rrbracket\subseteq\llbracket\psi_{\mathcal{M}}\rrbracket$ iff. $\underline{\phi^\downarrow}\subseteq \psi^\downarrow$, which is equivalent to $\mathbb{P}^{\mathcal{P}}$ satisfying $\phi\twiddle\psi$.

\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Completeness Preferential Contexts
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\CompletenessP*

\begin{proof}
    By \Cref{theorem:propositional-completeness} we have that a consequence relation $\twiddle_\mathcal{P}$ is preferential if and only if it the consequence defined by some preferential interpretation $\mathcal{P}$. We omit the proof for this as it is a well known result from \cite{KLM2002nonmonotonic}. Then, by the correspondence result between preferential interpretations and preferential contexts, given by \Cref{lemma:correspondence-propositional-compound} and \Cref{lemma:correspondence-conditionals-propositional-preferential}, we have that a consequence relation $\twiddle_\mathcal{P}$ is preferential if and only if it is the consequence relation defined by a preferential context $\mathbb{P}$. 

\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Soundness Ranked Contexts
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\SoundnessR*

\begin{proof}
    We assume that $\phi \twiddle_\mathbb{R} \psi$ and $\phi \ntwiddle_\mathbb{R} \neg \gamma$. By the second assumption there exists at least one object $g \in \minDerivation{\phi}$ such that $g \in \gamma^\downarrow$. It follows that $g \in \underline{\phi^\downarrow \cap \gamma^\downarrow}$. Any other $h \in \underline{(\phi^\downarrow \cap \gamma^\downarrow)}$ is incomparable to $g$ and so there can be no $i \in \phi^\downarrow$ such that $i \prec h$, as then modularity would require that $i \prec g$, but $g \in \minDerivation{\phi}$. Thus $h \in \minDerivation{\phi}$. Then by our first assumption it follows that $h \in \psi^\downarrow$. All elements in $\underline{\phi^\downarrow \cap \gamma^\downarrow} \subseteq \psi^\downarrow$.

\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Derived Ranked Contexts
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\DefeasibleCorrespondenceRanked*

\begin{proof}
    Let $\mathbb{R}^\mathcal{R} = (G,M,I,\prec_*)$ be a derived ranked context where $\mathsf{R}_*$ is the ranking function that induces $\prec$. For some $g_s \in G$ assume $g_s \not \in \minDerivation{\phi}$. Then either $g_s\not \in \phi^\downarrow$ or $g_s \in \phi^\downarrow$ and there exists some $g_t \in \phi^\downarrow$ with $\mathsf{R}_*(g_t) < \mathsf{R}_*(g_s)$. In the first case, $l(s) \not \in \llbracket \phi_\mathcal{M}\rrbracket$. The second case is equivalent to $l(s) \in \llbracket\phi_\mathcal{M}\rrbracket$ and there exists some $t \in S$ such that $\mathsf{R}(t) < \mathsf{R}(s)$ with $t \Vdash \phi$. 

    Then, $\phi_\mathcal{M} \twiddle \psi_\mathcal{M}$ if and only if for every minimal state $v \in \llbracket\phi_\mathcal{M}\rrbracket$ it holds that $v \in \llbracket \psi_\mathcal{M} \rrbracket$. Then, some object $g_s \in \minDerivation{\phi}$ if and only if $s \in \llbracket \phi_\mathcal{M} \rrbracket$, and from \Cref{lemma:correspondence-propositional-compound} it holds that $g_s \in \psi^\downarrow$ if and only if $s \in \llbracket \psi_\mathcal{M} \rrbracket$. Therefore, $\min_{\prec}\llbracket\phi_\mathcal{M}\rrbracket\subseteq\llbracket\psi_{\mathcal{M}}\rrbracket$ if and only if $\minDerivation{\phi} \subseteq \psi^\downarrow$ which is equivalent to $\mathbb{R}^\mathcal{R}$ satisfying $\phi \twiddle \psi$. 

\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Completeness Ranked Contexts
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\CompletenessR*

\begin{proof}
    The proof follows the same construction as the completeness result for preferential contexts. Lehmann \& Magidor \cite{what-does-a-conditional-knowledge-base-entail} show that a consequence relation is rational if and only if it the consequence relation induced by some ranked interpretation. We show in \Cref{lemma:correspondence-ranked} that for any ranked interpretation a ranked context can be constructed which induces a corresponding consequence relation. It follows that a consequence relation is rational if and only if it is the relation that can be induced by a ranked context. 

\end{proof}
