\section{Details of Metrics.}
\label{app:metrics}
\subsection{Main}
\label{app: main_metric}
\noindent\textbf{Price Reduction Rate(PRR).}
The Price Reduction Rate(PRR) quantifies the relative price change achieved through negotiation:
\begin{equation}
\label{BR}
PRR = \frac{p_r - p_a^T}{p_r}
\end{equation}
A higher BR indicates stronger buyer bargaining power, while the seller concedes more, reflecting weaker negotiation strength.

\noindent\textbf{Relative Profit (RP).}
We define the Relative Profit (RP) as the ratio between the total profit achieved by the model and the minimum reference profit (e.g. the GPT-3.5 profit in main experiment):

\begin{equation} 
\label{RP}
RP = \frac{TP}{TP_{\text{min}}}
\end{equation}

Here, the total profit \( TP \) is calculated as:

\begin{equation} 
\label{TP}
TP = \sum_{i=1}^{|N_{\text{deal}}|} (p_a^{T, (i)} - p_w^{(i)})
\end{equation}

where \( p_a^{T, (i)} \) is the final proposed price and \( p_w^{(i)} \) is the wholesale price for the \( i \)-th successful transaction, and \( N_{\text{deal}} \) denotes the set of all successful transactions. The term \( TP_{\text{min}} \) refers to the lowest total profit observed among all evaluated models. 


\noindent\textbf{Deal Rate(DR).}
The Deal Rate (DR) measures the percentage of negotiations that result in a successful transaction:
\begin{equation}
DR = \frac{|N_{\text{deal}}|}{|N|}
\end{equation}
In here, \( |N_{\text{deal}}| \) is the number of successful negotiations. \( |N \) is the total number of negotiations.

\noindent\textbf{Profit Rate (PR).}
We define the Profit Rate (PR) as the average per-product profit margin across all successful transactions. For each deal, the profit margin is computed relative to the wholesale cost. Formally:

\begin{equation}
\label{PR}
PR = \frac{1}{|N_{\text{deal}}|} \sum_{i=1}^{|N_{\text{deal}}|} \frac{p_a^{T, (i)} - p_w^{(i)}}{p_w^{(i)}}
\end{equation}

Here, \( p_a^{T, (i)} \) denotes the agreed price of the \( i \)-th deal, \( p_w^{(i)} \) is its wholesale price, and \( N_{\text{deal}} \) is the set of all successfully closed transactions.

\subsection{Anomaly}
\label{app: risk_metric}
\noindent\textbf{Out of Budget Rate (OBR).}
The Out of Budget Rate (OBR) quantifies how often the final accepted price exceeds the buyer's budget constraint:

\begin{equation}
\label{OBR}
OBR = \frac{N_{\text{over}}}{N}
\end{equation}

Here, \( N_{\text{over}} \) is the number of negotiations where the final accepted price \( p_a^{T, (i)} \) exceeds the fixed buyer budget \( \beta \), i.e., \( p_a^{T, (i)} > \beta \).  
\( N \) denotes the total number of negotiations attempted.


\noindent\textbf{Out of Wholesale Rate (OWR).}
The Out of Wholesale Rate (OWR) measures how often the final accepted price falls below the wholesale price, indicating unprofitable transactions from the seller's perspective:

\begin{equation}
\label{OWR}
OWR = \frac{N_{\text{below}}}{N}
\end{equation}

Here, \( N_{\text{below}} \) is the number of negotiations where the final accepted price \( p_a^{T, (i)} \) is less than the wholesale price \( p_w^{(i)} \), i.e., \( p_a^{T, (i)} < p_w^{(i)} \).  
\( N \) denotes the total number of negotiations attempted.


\noindent\textbf{Overpayment Rate (OPR).}
The Overpayment Rate (OPR) quantifies how often the buyer ends up paying more than the reference retail price of the product in a successful transaction:

\begin{equation}
\label{OPR}
OPR = \frac{N_{\text{over}}}{N_{\text{deal}}}
\end{equation}

Here, \( N_{\text{over}} \) is the number of successful deals where the final accepted price \( p_a^{T, (i)} \) exceeds the product’s retail price \( p_r^{(i)} \), i.e., \( p_a^{T, (i)} > p_r^{(i)} \).  
\( N \) is the total number of successful transactions.

\noindent\textbf{Deadlock Rate (DLR).}
The Deadlock Rate (DLR) quantifies the proportion of negotiations that reach the maximum allowed number of rounds \( T_{\max} \) without reaching any agreement:

\begin{equation}
\label{DR}
DR = \frac{N_{\text{deadlock}}}{N}
\end{equation}

Here, \( N_{\text{deadlock}} \) is the number of negotiations that reach \( T_{\max} \) rounds without a final agreement price,  
and \( N \) denotes the total number of negotiations.


