\subsection{Statistical Features for Agent-2}\label{appx:B2}

The statistical feature $\mathcal{O}_t\in\mathbb{R}^9$is summarized below:

\begin{enumerate}
    \item The first feature is the minimum objective value in the current (sub-)population indicating the achieved best performance of the current (sub-)population:
    \begin{equation}
        \mathcal{O}_{i,1}=\min \{\frac{f_i}{f^{0,*}-f^*}\}_{i\in [1,NP_{local}]}
    \end{equation}
    It is normalized by the difference between the best objective value at initial optimization $f^{0,*}$ step and the global optimal objective value of the optimization problem $f^*$, so that the scales of the features from different tasks are in the same level. which hence stabilizes the training. $NP_{local}$ is the (sub-)population size.
    \item The second one is the averaged normalized objective values in the current (sub-)population, indicating the average performance of the (sub-)population:
    \begin{equation}
        \mathcal{O}_{i,2}=\text{mean}\{\frac{f_i}{f^{0,*}-f^*}\}_{i\in [1,NP_{local}]}
    \end{equation}
    \item The variance of the normalized objective values in the current (sub-)population, indicating the variance and convergence of the (sub-)population:
    \begin{equation}
        \mathcal{O}_{i,3}=\text{std} \{\frac{f_i}{f^{0,*}-f^*}\}_{i\in [1,NP_{local}]}
    \end{equation}
    \item The next feature is the maximal distance between the solutions in (sub-)population, normalized by the diameter of the search space, measuring the convergence:
    \begin{equation}
        \mathcal{O}_{i,4}=\mathop{\max}\limits_{i,j \in[1,NP_{local}]} \frac{||x_i - x_j||_2}{||ub-lb||_2}
    \end{equation}
    where $ub$ and $lb$ are the upper and lower bounds of the search space.
    \item The dispersion difference~\cite{lunacek2006dispersion} feature is calculated as the difference of the maximal distance between the top 10\% solutions and the maximal distance between all solutions in (sub-)population:
    \begin{equation}
    \begin{split}
        \mathcal{O}_{i,5}=\mathop{\max}\limits_{i,j \in[1,10\% NP_{local}]} \frac{||x_i - x_j||_2}{||ub-lb||_2} \\- \mathop{\max}\limits_{i,j \in[1,NP_{local}]} \frac{||x_i - x_j||_2}{||ub-lb||_2}
    \end{split}
    \end{equation}
    It measures the funnelity of the problem landscape: a single funnel problem has a smaller dispersion difference while the multi-funnel landscape has larger value.
    \item The fitness distance correlation (FDC)~\cite{fdc} describes the complexity of the problem by evaluating the relationship between fitness value and the distance of the solution from the optimum. 
    \begin{equation}
        \mathcal{O}_{i,6}=\frac{\frac{1}{NP_{local}}\sum_{i=1}^{NP_{local}}{(f_i - \Bar{f})(d_i^* - \Bar{d}^*)}}{\text{var}(\{d_i^*\}_{i\in [1,NP_{local}]})\cdot\text{var}(\{f_i\}_{i\in [1,NP_{local}]})}
    \end{equation}
    where the $\Bar{f}$ is the averaged objective value in (sub-)population, $d_i^* = ||x_i-x^*||_2$ is the distance between $x_i$ and the best solution $x^*$, $\Bar{d}^* = \text{mean} \{d_i^*\}_{i\in [1,NP_{local}]}$ is the averaged distance,\\ var($\cdot$) is the variance.
    \item The found global best objective among all (sub-)populations, indicating the achieved best performance of the overall optimization:
    \begin{equation}
        \mathcal{O}_{i,7}=\min \{\frac{f_i}{f^{0,*}-f^*}\}_{i\in [1,NP]}
    \end{equation}
    \item This feature is the FDC feature for the overall population:
    \begin{equation}
        \mathcal{O}_{i,8}=\frac{\frac{1}{NP}\sum_{i=1}^{NP}{(f_i - \Bar{f})(d_i^* - \Bar{d}^*)}}{\text{var}(\{d_i^*\}_{i\in [1,NP]})\cdot\text{var}(\{f_i\}_{i\in [1,NP]})}
    \end{equation}
    \item The last feature is the remaining optimization budget, indicating the optimization progress:
    \begin{equation}
        \mathcal{O}_{i,9}=\frac{maxFEs-FEs}{maxFEs}
    \end{equation}
    where $maxFEs$ is maximum allowed function evaluations and $FEs$ is the number of consumed function evaluations.
\end{enumerate}

