\begin{algorithm}[!h]
    \caption{The pseudo code of the training of DesignX}
    \label{alg:train}
    \KwIn{Training problem set $\mathcal{D}_{train}$, Modular-EC $\mathcal{M}$, initial Agent-1 model $\pi_\phi$, Agent-2 actor $\pi_\theta$ and critic $v_\psi$.}
    \KwOut{Well trained $\pi_\phi$, $\pi_\theta$ and $v_\psi$.}
    \textcolor{gray}{// Training for Agent-1\;}
    Freeze $\pi_\theta$\;
    \For{$epoch = 1$ \KwTo $Epoch$}{
        \For{each $p \in \mathcal{D}_{train}$}{
            Sample solutions $X_{ELA}\in\mathbb{R}^{100p.D\times p.D}$ and evaluate them $Y_{ELA}=p(X_{ELA})$\;
            Obtain the ELA features $\mathcal{F}_{ELA}=\text{ELA}(X_{ELA}, Y_{ELA})$\;
            Get the feature vector $\mathcal{F}_p = $Concat$(p.D, p.maxFEs, p.ub, p.lb, \mathcal{F}_{ELA})$\;
            Auto-regressively generate the optimizer $\mathcal{A}_p=\pi_\phi(\mathcal{F}_p, \mathcal{M})$ following Section 3.2.1\;
            Initial state $\mathcal{O}_{t=1} = \mathcal{A}_p.optimize(p), R_p=0$\;
            \While{Termination condition is not met}{
                $a_t = \pi_\theta(\mathcal{O}_t)$\;
                $\mathcal{O}_{t+1}, r_t = \mathcal{A}_p.optimize(a_t, p)$\;
                $R_p = R_p + r_t$\;
            }
            Update $\pi_\phi$ by in REINFORCE~\cite{reinforce} manner\;
        }
    }
    \textcolor{gray}{// Training for Agent-2\;}
    Freeze $\pi_\phi$\;
    \For{$epoch = 1$ \KwTo $Epoch$}{
        \For{each $p \in \mathcal{D}_{train}$}{
            Generate the optimizer $\mathcal{A}_p$ as Lines 7$\sim$10\;
            Initial state $\mathcal{O}_{t=1} = \mathcal{A}_p.optimize(p)$\;
            \While{Termination condition is not met}{
                \For{$step = 1$ \KwTo $nstep$}{
                    $a_t = \pi_\theta(\mathcal{O}_t)$\;
                    $\mathcal{O}_{t+1}, r_t = \mathcal{A}_p.optimize(a_t, p)$\;
                    Record transition $<s_t, a_t, s_{t+1}, r_t>$\;
                }
                \For{$k=1$ \KwTo $kepoch$}{
                    Update actor $\pi_\theta$ and critic $v_\psi$ in PPO~\cite{ppo} manner\;
                }
            }
        }
    }
\end{algorithm}

\section{Experimental Setup}\label{appx:E}

\subsection{Training Setup}\label{appx:E1}

In this paper, we set the embedding dimension $h = 64$ and the number of attention head $k = 4$ for both Agent-1 \& 2. The number of blocks $L$ is $1$ for Agent-1 and $3$ for Agent-2. The maximum number of modules $M$ is 64 and the predefined maximum configuration size $N_{max} = 12$. The training of both agents on $\mathcal{D}_{train}$ lasts for $Epoch=100$ epochs with a fixed learning rate $0.0001$. Agent-1 is trained with a batch size of $128$. During the training of Agent-2, for a batch of $64$ problems, PPO~\citep{ppo} method is used to update the policy and critic nets for $kepoch=3$ times for every $nstep=10$ rollout optimization steps. All experiments are run on two Intel(R) Xeon(R) 6458Q CPUs with 488G RAM. All baseline configurations align with their original papers.

\subsection{Objective Value Normalization}\label{appx:E2}

Since the objective value scales of different problems can vary, averaging them directly is not fair, it cannot reflect the true performance of baselines. To normalize the values to the same scale, we use the best objective value found by random search $f^*_{p,RS}$ on problem $p$. Concretely, for problem $p$ we randomly sample $p.maxFEs$ solutions in the search range $[p.lb, p.ub]$ and take the best sampled objective value as $f^*_{p,RS}$. In the experiment, for the found best objective value $f^*_{p,b,i}$ of baseline $b$ in test run $i$ on problem $p$, we normalize it by $f_{p,b,i}^{*\prime} = \frac{f^*_{p,b,i}}{f^*_{p,RS}}$. Then we average the normalized objective values of baseline $b$ on all problem and all runs as the normalized averaged objective value in Table 1 in the main paper: $f_b = \frac{1}{|\mathcal{D}_{test}|\cdot51}\sum_{p\in\mathcal{D}_{test}}\sum_{i=1}^{51}f_{p,b,i}^{*\prime}$. The similar procedure is conducted on the three realistic benchmarks. We also use a reversed normalized averaged objective value formulated as $1 - f_b$ in the ablation study in Section 4.3.

\subsection{Realistic Benchmark}\label{appx:E3}

\begin{enumerate}
    \item \textbf{Protein-Docking Benchmark}~\cite{protein}, where the objective is to minimize the Gibbs free energy resulting from protein-protein interaction between a given complex and any other conformation. We select 28 protein complexes and randomly initialize 10 starting points for each complex, resulting in 280 problem instances. To simplify the problem structure, we only optimize 12 interaction points in a complex instance (12D problem). 

    \item \textbf{HPO-B Benchmark}~\cite{hpo-b} is an AutoML hyper-parameter optimization benchmark which includes a wide range of hyperparameter optimization tasks for 16 different model types (e.g., SVM, XGBoost, etc.), resulting in a total of 935 problem instances. The dimension of these problem instances range from 2 to 16. To save evaluation time, we adopt the continuous version of HPO-B, which provides surrogate evaluation functions for time-consuming machine learning tasks. We also note that HPO-B represents problems with ill-conditioned landscape such as huge flatten. 

    \item \textbf{UAV Path Planning Benchmark}~\cite{uav} provides 56 terrain-based landscapes as realistic Unmanned Aerial Vehicle (UAV) path planning problems, each of which is 30D. The objective is to select given number of path nodes (x,y,z coordinates) from the 3D space, so the the UAV could fly as shortly as possible in a collision-free way.
\end{enumerate}

\subsection{Relative Importance Calculation}\label{appx:E4}

% In the left of Figure~\ref{fig:heatmap}, we summarize the relative importance of different module types in Modular-EC when considering various optimization problem characteristics: Dimension, maxFEs, Search Range, Modality, Global Structure, Conditioning. To compute the relative importance, we provide a example here. Suppose we consider the relative importance of ``M''~(mutation) for Modality, we first divide problem instances in $\mathcal{D}_{test}$ into those unimodal ones and those multimodal ones. Then based on the optimizer workflows generated by DesignX for these problem instances, the relative importance can be calculated as the KL-divergence of the sub-module occurence distributions of ``M'' in unimodal problems and multimodal problems~(see Appendix E.4 for more clarification). The relative importance factor reflects how DesignX thinks when designing an optimizer for a problem with certain property.

Taking the relative importance of mutation (``M'') modules on modality as an example, we first divide problem instances in $\mathcal{D}_{test}$ into those unimodal ones and those multimodal ones. Next we collect the mutation modules used in optimizers generated for unimodal and multimodal problems respectively. We count the occurence of each mutation sub-modules in the two mutation module collections as the histogram shown in the top right of Figure 4 in the main paper. Considering the occurence probabilities of different sub-modules in the two collections for unimodal and multimodal as two distributions, we then measure the relative importance of mutation modules to modality as the KL-divergence between the two distributions. For characteristics with more than two properties such as dimension, maxFEs and search range, we use the maximum KL-divergence among the distributions. Finally, to highlight the relative importance of different modules to the same problem characteristic, we conduct the mean-std standardization. Given the importance $\mathcal{I}_{\omega, \rho}$ of module $\omega\in\Omega$ to characteristic $\rho$, the standardized importance is $\mathcal{I}'_{\omega, \rho} = \frac{\mathcal{I}_{\omega, \rho} - \text{mean}_{\varpi\in\Omega}(\mathcal{I}_{\varpi, \rho})}{\text{std}_{\varpi\in\Omega}(\mathcal{I}_{\varpi, \rho})}$, which is shown in the left of figure 4 in the main paper.


% For each problem characteristic $\rho\in\{$dimension, maxFEs, search range, modality, global structure, conditioning$\}$ with |$\rho$| different properties, and each module category $\omega\in\{$I, N, M, C, OU, BC, S, PR, RS, IS$\}$ with |$\omega$| different modules, the occurence probability of an option $\rho_i$ under module $\omega_j$ is defined as $D_{\rho_i, \omega_j} = \frac{N_{i}(\omega_j)}{\sum_{j=1}^{|\omega|}N_{i}(\omega_j)}$ where $N_i(\cdot)$ is the number of occurence of module $\omega_j$ in the optimizers designed for problems with property $\rho_i$. The probabilities of all modules under $\rho_i$ forms a distribution $D_{\rho_i} = \{D_{\rho_i, \omega_j}\}_{j = 1}^{|\omega|}$~(as shown in the right of Figure 4 of the main paper). To measure the relative importance $\mathcal{I}_{\rho, \omega}$ of property $\rho$ to module category $\omega$, we use the maximal Wasserstein distance among the distributions of property options $\mathcal{I}_{\rho, \omega} = \max_{i, k \in [1,|\rho|]} Dist_w(D_{\rho_i}, D_{\rho_k})$. Finally, to highlight the relative importance, we conduct the mean-std standardization on the importance values of module categories under the same optimization property: $\mathcal{I}'_{\rho, \omega} = \frac{\mathcal{I}_{\rho, \omega} - \text{mean}_{\omega} \mathcal{I}_{\rho, \omega}}{\text{std}_{\omega} \mathcal{I}_{\rho, \omega}}$.

