\section{Preliminaries and assumptions}\label{sec_prel}
Let $d\in\NN$. For any $x,y \in \RR^d$, we denote by $x\cdot y$ their standard inner product and by $|\cdot|$ its inducted norm. We write $B(0,R)$ and $\ov{B}(0,R)$  for the associated open and closed balls, respectively, centered at the origin and radius $R>0$. We denote by  $|\cdot|_{\infty}$ the maximum norm in $\RR^d$, and we write $B_{\infty}(0,R)$ and $\ov{B}_{\infty}(0,R)$ for the corresponding open and closed balls, respectively, centered at the origin and radius $R>0$. Let $\P(\RR^d)$ be the set of probability
measures on $\RR^d$, endowed with the Kantorovich–Rubinstein distance 
\begin{equation*} \label{e:d_1_alternative} 
d_1(\nu,\tilde \nu)=\sup\bigg\{\int_{\RR^d}\varphi(x)\dd[\nu-\tilde \nu](x)\,\Big|\,\varphi: \RR^d \to \RR  \text{ is 1- Lipschitz } \bigg\}.
\end{equation*} 
We denote by $\to$ and $\rightharpoonup$  the convergence  in $\P(\RR^d)$ with respect to the $d_1$-distance and the narrow topology, respectively.
For every $\nu\in\P(\RR^{d})$ we denote by $\supp(\nu)$ its support.
In what follows, given an absolutely continuous measure (w.r.t. the Lebesgue measure in $\RR^{d}$)  $\nu\in \P(\RR^d)$,  we still denote by $\nu$ its density.
For any metric spaces $(E^1,d_{E^1})$ and $(E^2,d_{E^2})$, we denote by  $\mathcal{B}(E^1;E^2)$, $\CC_b(E^1;E^2)$, $\CC^k(E^1,E^2)$, $\CC^{k}_c(E^1,E^2)$, 
the sets of  bounded, bounded continuous, $k$-times continuously differentiable, and $k$-times continuously differentiable functions with compact support   from $E^1$ to $E^2$ respectively.  Whenever $E^2=\RR$, we suppress explicit mention of the codomain and use the abbreviated notations  $\mathcal{B}(E^1)$, $\CC_b(E^1)$,  $\CC^k(E^1)$ and   $\CC^{k}_c(E^1)$. 

We suppose that the functions $F,G :\RR^{d} \times \P_{1}(\RR^d) \to \RR$ and the measure $m^*_0$, which are the data of   the MFGs system, satisfy the following assumptions:
   \begin{Hassum}
        \item\label{continuity} $F,G \in \CC( \RR^d \times\P_{1}(\RR^d))$; 
        \item\label{C2bounded}  $G(\cdot,\nu)\in \CC^2(\RR^d)$ for any $\nu \in \P_1(\RR^d)$, and there exist  some constants $C_{F,i}>0,C_{G,i}>0$ $(i=1,2)$ such that, for any $\nu \in \P_1(\RR^d)$, 
        \begin{equation*}
        \begin{aligned}
        |F(x,\nu)|&\leq C_{F,1}, \\ 
            |F(x,\nu)-F(y,\nu)|&\leq C_{F,2}|x-y|, \\ 
        \supp(G(\cdot,\nu))&\subseteq \ov B(0,C_{G,1}),\\ 
            ||G(\cdot,\nu)||_{\CC^{2}(\RR^d)}&\leq C_{G,2},
        \end{aligned}
        \end{equation*}
     where $ ||h||_{\CC^{2}(\RR^d)}=\sup_{x\in \RR^{d}}\Big\{|h(x)|+ |D_x h(x)|+ |D^2_xh(x)|\Big\}$; 
     \item\label{initialdensity} the initial condition $m^*_{0}\in \P_{1}(\RR^d)$ is absolutely continuous with respect to the Lebesgue measure, with density still denoted by $m^*_{0}$ such that $m_0^*\in \CC^2(\RR^d)$   and $\supp(m^*_{0})\subseteq \ov B(0,C^*)$, for some $C^*>0$;  
     \item \label{ass:lagrangian}   $L\in \CC^2(\RR^d\times\RR^d)$, it is bounded from below  and there exist some constants $C_{L,i}>0$  $(i=1,\dots,5)$ such that, for any $(x,a)\in \RR^d \times \RR^d$, we have
\begin{equation*}
\begin{aligned}
L(x,a)&\leq C_{L,1}|a|^2+C_{L,2},\\
|D_{x}L(x,a)|&\leq C_{L,3}(1+|a|^2),\\
C_{L,4}|b|^2&\leq \langle
D^{2}_{aa}L(x,a)b,b\rangle\quad\text{for any }b\in\RR^d,\\
\langle D^{2}_{xx}L(x,a)y,y\rangle&\leq C_{L,5}(1+|a|^2)|y|^2\quad\text{for any }y\in\RR^d;
\end{aligned}
\end{equation*}
\item\label{monoticityassumption} for $h=F,G$ the following Lasry--Lions monotonicity condition holds         \begin{equation*}
    \int_{\RR^{d}}\Big(h(x,\nu)-h(x,\tilde \nu)\Big)\dd[\nu-\tilde \nu](x)\geq 0 \quad \text{for any }  \nu,\tilde \nu\in \P_{1}(\RR^d).
\end{equation*}
\end{Hassum}
\begin{rem} As shown in \cite[Remark 2.1]{CarliniSilvaZorkot}, \ref{ass:lagrangian} implies that there exist $C_{L,6},C_{L,7}>0$ s.t. 
\begin{equation*}
    L(x,a)\geq C_{L,6}|a|^{2}-C_{L,7}\quad\text{for any }x,\,a\in\RR^d.
\end{equation*}
Therefore, $H\in \CC^2(\RR^d\times \RR^d)$, $D_{p}H(x,p)$ is the unique maximizer of $\sup_{a\in\RR^{d}}\big\{ a\cdot p -L(x,a)\big\}$ and there exist some constants $C_{H,i}>0$ $(i=1,\cdots,5)$ such that 
\begin{equation*}
\begin{aligned}
   C_{H,1}|p|^2-C_{H,2}&\leq H(x,p)\leq C_{H,3}|p|^2+C_{H,4}\quad\text{for any }x,\,p\in\RR^d, \\ 
   |D_{p}H(x,p)|&\leq C_{H,5}(1+|p|)\quad\text{for any }x,\,p\in\RR^{d}.
\end{aligned}
\end{equation*}
\end{rem}




\begin{rem}\label{rem:viscosity} Under
\cref{C2bounded,continuity,initialdensity,ass:lagrangian}, there exists at least one solution $(m,v)$ to   the MFGs system, in the distributional and viscosity sense, respectively. Moreover, also assuming \ref{monoticityassumption}, the solution is unique (see \cite{lions2007cours,cardaliaguet2010notes}).
\end{rem}

A notion of weak solution for stationary MFGs problems was introduced in \cite{FerreiraGomes}, relying on the theory of motonone operators, as mentioned also in \cite{CardaliaguetPorretta} for second order MFGs problems. Following this approach,   the MFGs system can be rephrased as $\mathcal{A}[w] = 0$ subject to  initial-terminal conditions, where $\mathcal{A}$ is  the
operator on the couple $w=(m,v)$ defined by
\begin{equation*}
\mathcal{A}[w]
\coloneqq
\begin{bmatrix}
	\partial_{t}v(x,t)-H(x,D_xv(x,t))+F(x,m(t)) \\
	\partial_{t} m(x,t)- \diver\Bigl(D_pH\big(x,D_xv(x,t)\big)m(x,t)\Bigl) \\
\end{bmatrix}. 
\end{equation*}
For any $w=(m,v)$ and $\Tilde w=(\Tilde m,\Tilde v)$, setting $\langle w,\tilde{w} \rangle \coloneqq \int_{Q_T}\Big( m(x,t)\Tilde m(x,t) +  v(x,t)\Tilde v(x,t)  \Big)\dd x\dd t,$
and $Q_T:={\RR^d\times[0,T]}$,
we give the following notion of weak solution:
\begin{defin}\label{weak solution}
    The couple $w^*=(m^*,v^*)$ is a {\emph weak} solution  to   the MFGs system if $m^*,v^* :{Q_T}\to \RR$, $m^*(t)\in\P_1(\RR^d)$ for any $t\in [0,T]$, 
     $ v^*\in L^\infty({Q_T})$ and 
    \begin{equation*}
         \langle \mathcal A[\varphi],\varphi-w^* \rangle \geq 0 \qquad \text{for any } \varphi= (\phi,\psi) \in \mathcal{D},
    \end{equation*}
where 
       \begin{equation*}
               \begin{aligned}
        \mathcal{D}\coloneqq \Big\{ \varphi=(\phi,\psi) \,  \Big |\,  
        &\phi,\psi\in \CC_c^2({Q_T}), \\ 
        &\phi \geq 0, \, \int_{\RR^d}\phi(x,t)\dd x=1  \text{ for any } t \in [0,T], \, \phi(x,0)=m_0^*(x),\\  & \psi(x,T)=G(x,\phi(T)), \, 
       ||D_x \psi||_{L^\infty({Q_T})}\leq \ov  C_{\text{{\rm b}}} \Big\},
     \end{aligned}
    \end{equation*}
with $\ov C_{\text{{\rm b}}}>0$ such that $C_{G,2}\leq\ov C_{\text{{\rm b}}}\leq C_H/C_{H,5}-1$, where $ C_H\coloneqq C_{\text{{\rm b}}}+C_{H,5}(C_{G_2}+1)$ and  $ C_{\text{{\rm b}}}>0$ is the constant defined in  \cite[Proposition 2.1]{CarliniSilvaZorkot}. 
\end{defin}

Let us observe that the constants  $\ov C_{\text{{\rm b}}}$ and $C_H$ guarantee  $||D_pH(\cdot,D_x\psi)||_{L^\infty({Q_T})}\leq C_H$.


The notion of solution in \cref{weak solution}
is less used than the one referred in \cref{rem:viscosity}, however it allowed us to
established a converge results for
 the SL scheme proposed in \cref{sec: A semi-Lagrange scheme for MFGs}. In addition, this convergence result
 proves that, under suitable assumptions, there exists a weak solution to   the MFGs system (\cref{existencewealsolution}).

\section{Semi-Lagrangian schemes}\label{sec:semi-Lagrangian schemes}
We recall some standard SL schemes for approximating solutions to the HJB equation and the continuity equation. These schemes will be employed in the subsequent algorithms developed to compute approximate solutions to   the MFGs system.

Let us consider a pair $\Delta=(\Delta x,\Delta t)>0$ such that $N_T\Delta t=T$ for some $N_T\in\NN_+$. We define the sets of indices  
$\It\coloneqq\{0,\dots, N_T\}$, $\It ^*\coloneqq\It \backslash \{N_T\}$,  
$\Ix\coloneqq\mathbb{Z}^d$, $\Ixt\coloneqq \Ix\times\It$ and $\Ixt^*\coloneqq \Ix\times\It^*$.
For any $(i,k)\in \Ixt$ we define  $x_i\coloneqq i\Delta x$ and $t_k\coloneqq k\Delta t$. We define the $d$ dimensional space grid
$\GG_{\Delta x}\coloneqq \{x_{i},  i\in \Ix\}$, the time grid $\GG_{\Delta t}\coloneqq \{t_{k}, k\in \It\}$ and the space-time grid $\GG_{\Delta}\coloneqq \GG_{\Delta x}\times \GG_{\Delta t}$. We also define  $\GG^*_{\Delta t}\coloneqq \{t_{k}=k\Delta t, k\in \It^*\}$ and $\GG^*_{\Delta}\coloneqq \GG_{\Delta x}\times \GG^*_{\Delta t}$.   Given $h \in \BB(\GG_{\Delta x};\RR^d)$ and $l\in \BB(\GG_{\Delta};\RR^d)$, we use the notation 
\begin{equation*}
    h_i\coloneqq h(x_i) \qquad l_{i,k}\coloneqq l(x_i,t
    _k) \qquad \text{ for any } (i,k)\in \Ixt,
 \end{equation*} 
 and, for $k\in \It$, we define the function $l_{k}\in \BB(\GG_{\Delta x};\RR^d)$ such that  $ (l_{k})_{i}\coloneqq l_{i,k}$ for any $i\in \Ix$.
 Given $\varphi \in \CC_{b}(\RR^{d})$ and $\psi\in \CC_{b}(Q_T)$, we define the functions  $\hat \varphi \in\BB(\GG_{\Delta x})$ and $\hat \psi \in \BB(\GG_{\Delta})$ such that 
\begin{equation*}
  \hat \varphi _i\coloneqq \varphi(x_i) \qquad \hat \psi _{i,k}\coloneqq\psi(x_i,t_k) \qquad \text{ for any } (i,k)\in \Ixt.
\end{equation*}
We consider the $\mathbb{Q}_1$ basis of functions $\{\beta_{i}:\RR^{d}\to\RR, \, i\in\Ix\}$ (see \cite{CarliniSilvaZorkot}) and the interpolation operator $I_{\Delta x}:\BB(\GG_{\Delta x})\to \CC_{b}(\RR^{d})$ defined by  
\begin{equation}\label{interpolation operator}
    I_{\Delta x}[W](\cdot)\coloneqq \sum_{i\in \Ix}W_{i}\beta_{i}(\cdot).
\end{equation}
We have that, given $\phi\in \CC(\RR^d)$, the following holds  (see \cite{QuarteroniValli})
\begin{equation} \label{interperr}
    \sup_{x\in \RR^d}|I_{\Delta x}[\hat{\phi}](x)-\phi(x)|= \mathcal{O}(\Delta x^{\gamma}),
\end{equation}
where $\gamma=1$ if $\phi$ is Lipschitz and $\gamma=2$ if $ \phi\in \CC^2(\RR^d)$ with bounded first and second
derivatives.


\subsection{Fully discrete scheme for the Hamilton Jacobi Bellman equation }\label{A_fully_discrete_scheme_for_the_Hamilton_Jacobi_Bellman_equation}
Given $u \in \BB(\GG_{\Delta})$, we define its extension on $ Q_T $  by
\begin{equation}\label{vdelta}
    V_{\Delta}[u](x,t)\coloneqq I_{\Delta x}[u_{\lceil\frac{t}{\Delta t}\rceil}](x).
\end{equation}
Given $\nu \in \CC([0,T];\P_1(\RR^d))$ 
and  $C_H$  as in  \cref{weak solution},  we define ${S}_{\Delta}[\nu]:\BB(\GG_{\Delta x})\times \Ixt \to \RR$ by
\begin{equation*}\label{eq:infS}
    {S}_{\Delta}[\nu](W,i,k)\coloneqq \inf_{a\in \ov{B}_{\infty}(0,C_H) }\left\{I_{\Delta x}[W](x_{i}-\Delta t a)+\Delta tL(x_i,a)\right\}+\Delta t F(x_{i},\nu(t_{k})).
\end{equation*}

We consider the following fully-discrete SL scheme for \eqref{eq:MFGs1}: define recursively 
 $v\in \BB(\GG_{\Delta})$ as
\begin{equation}\label{eq:HJBdiscr}\tag{$HJBdiscr$}
            \begin{aligned}
               &v_{i,k}={S}_{\Delta}[\nu](v_{k+1},i,k) &&\text{for any   }(i,k)\in \Ixt ^*, \\
               &v_{i,N_T}=G(x_i,\nu(T)) &&  \text{for any  }i\in \Ix. \\  
            \end{aligned}
\end{equation}
and its extension  $v_{\Delta}:=V_{\Delta}[v]$.
The following properties of ${S}_{\Delta}$ and $v_{\Delta}$ are established in \cite{CarliniSilvaZorkot}. 
\begin{prop}\label{properties decrete value function}
Under \cref{continuity,C2bounded,ass:lagrangian}, let $\nu \in \CC([0,T];\P_1(\RR^d))$ and $\Delta=(\Delta x,\Delta t)>0$,
the following properties hold:
\begin{enumerate}
\item [{\rm(i)}]  {\rm[Monotonicity]} 
For any $W,\tilde W\in \BB(\GG_{\Delta_x})$ such that $W_i\leq \tilde W_i $ for any $i\in \Ix$, we have 
\begin{equation*}
{S}_{\Delta}[\nu](W,i,k)\leq {S}_{\Delta}[\nu](\tilde W,i,k) \quad \text{for any } (i,k)\in \Ixt.
\end{equation*}
\item [{\rm(ii)}]  {\rm[Consistency]}  
For any $\psi\in\CC^2(Q_T)$ with bounded derivatives and s.t. 
$||D_x \psi||_{L^\infty(Q_T)}\leq \ov  C_{\text{{\rm b}}}$, for any $(i,k)\in \Ixt^*$, we have 
\begin{equation*}
\begin{aligned}
&\frac{\hat\psi_{i,k}-{S}_{\Delta}[\nu](\hat{\psi}_{k+1},i,k)}{\Delta t}=\partial_{t}\psi(x_i,t_k)+H(x_i,D_{x}\psi(x_i,t_k))-F(x_i,\nu(t_k))+\mathcal{O}\left(\frac{\Delta x^2}{\Delta t}\right).
\end{aligned}
\end{equation*}
    \item [{\rm(iii)}] {\rm[Stability]}
  We have 
\begin{equation*}
|v_{\Delta}(x,t)|\leq \widetilde C_{\text{{\rm v}}}\quad\text{for any }(x,t)\in \RR^{d}\times [0,T], 
\end{equation*}
where $\widetilde{C}_{\text{{\rm v}}}>0$ is independent of $(\nu,\Delta x,\Delta t)$.
\item [{\rm(iv)}] {\rm[Lipschitz property]}
  We have 
  \begin{equation*}
      \big|v_{\Delta}(x,t)-v_{\Delta}(y,t)\big|\leq \widetilde{C}_{\text{{\rm Lip}}}|x-y|\quad\text{for any }x,\,y\in\RR^d\,, t\in[0,T],
  \end{equation*}
  where $\widetilde{C}_{\text{{\rm Lip}}}>0$ is independent of
$(\nu,\Delta x,\Delta t)$. 
\end{enumerate}
\end{prop}
\medskip
 For any
 $(i,k)\in \Ixt^*$ and $v \in \BB(\GG_{\Delta})$, we define  the set of {\emph{discrete optimal controls}}
\begin{equation}\label{optimal set}
\begin{aligned}
  \Lambda_{i,k}[v]&\coloneqq\amin_{a \in \ov{B}_{\infty}(0,C_H)}\left\{I_{\Delta x}[v_{k+1}](x_{i}-\Delta t a)+\Delta tL(x_i,a)\right\}.\\ 
\end{aligned}
\end{equation}
We also define a set formed by grid functions of optimal controls and a set of  {\emph{relaxed controls}}
\begin{equation*} 
\begin{aligned}
  \Lambda_{\Delta}[v]&\coloneqq\{q\in \BB(\GG_{\Delta}^*;\RR^d) \, | \, q_{i,k}\in \Lambda_{i,k}[v]\}, \\ 
   \M_{\Delta}[v]&\coloneqq \Big\{\mu=(\mu_{i,k})_{(i,k)\in \Ixt^*} \, \Big | \, \mu_{i,k}\in \P_1(\RR^d), \, \supp(\mu_{i,k})\subseteq\Lambda_{i,k}[v]  \Big\}.
\end{aligned}
\end{equation*}


\subsection{Fully discrete scheme for the continuity equation}\label{A_fully_discrete_scheme_for_the_continuity_equation}
Given $\Delta=(\Delta x, \Delta t)$, we define  the sets $ \S(\GG_{\Delta x}):= \{ z\in \BB(\GG_{\Delta x}) |\, z_{i}\geq 0, \; \sum_{i\in \Ix}z_{i}=1 \}$ 
and $\S(\GG_{\Delta})\coloneqq \{ \nu=(\nu_{k})_{k=0}^{N_{T}} |\,\nu_{k}\in \S(\GG_{\Delta x}) \}$.
For any $\nu\in \S(\GG_{\Delta x})$, we define its extension on  $\RR^d$ as 
\begin{equation*}
    M_{\Delta x }[\nu](x)\coloneqq \frac{1}{(\Delta x) ^{d}}\sum_{i \in \Ix} \nu_i\rchi_{E_{i}}(x), \quad {\textrm{for }}\,x\in \RR^d,
\end{equation*}
with 
$ E_{i}\coloneqq \{x\in\RR^d\, |\, |x-x_i|_\infty \leq \Delta x/2\}$,  and $\rchi_{E}$ denotes the characteristic function of $E\subset \RR^d$.
Given $\nu\in \S(\GG_{\Delta})$, we also define  its extension on  $Q_T$  as 
\begin{equation}\label{mdelta}
 M_{\Delta}[\nu](x,t)\coloneqq M_{\Delta x}[\nu_k](x) \quad \text{if }t\in [t_k,t_{k+1}), k \in \It^*,\quad M_{\Delta}[\nu](x,t)\coloneqq M_{\Delta x}[\nu_{N_T}](x) \quad \text{if }t=T.
\end{equation}
Given $\mu=(\mu_{i,k}) $ such that $\mu_{i,k}\in \P(\RR^d)$ for  any ${(i,k)\in \mathcal{I}_{\Delta}^*}$, we define recursively $m\in \S(\GG_{\Delta})$  by the following discrete transport of the initial measure $m_0^*$ induced  by a generic probability measure $\mu$ :
\begin{equation}\label{eq:CEdiscr}\tag{$CEdiscr$}
            \begin{aligned}
               &m_{i,k+1}=\sum_{j\in \Ix}m_{j,k} \int_{\RR^d}\beta_{i}(x_j-\Delta t a)\dd \mu_{j,k}(a) &&\text{for any   }(i,k)\in \Ixt ^*, \\
               &m_{i,0}=\int_{E_{i}}\dd [m_0^*](x) &&  \text{for any  }i\in \Ix. \\  
            \end{aligned}
\end{equation}
It is easy to verify the following result,  analogous to \cite[Lemma 4.1]{CarliniSilvaZorkot}. 
\begin{lem}\label{SLCEproperties}
Let us assume  \ref{initialdensity} and
  $\Delta=(\Delta x,\Delta t )>0.$
  Let $\mu=(\mu_{i,k})$ be such that $\mu_{i,k}\in \P(\RR^d)$ 
  with $\supp(\mu_{i,k}) \subseteq \ov B(0,R)$, for some $R>0$, 
  for any ${(i,k)\in \mathcal{I}_{\Delta}^*}$. Let
  $m\in \S(\GG_{\Delta})$  be defined by \eqref{eq:CEdiscr}. 
For any $c>0$, such that $\Delta x\leq c\Delta t$, then there exists $C>0$, independent of $(\Delta ,\mu)$, such that 
  $m_{i,k}=0$ if $x_i\notin\ov B(0,C)$ for any $(i,k) \in \Ixt$.
\end{lem}


\subsection{A semi-Lagrangian scheme \eqref{eq:MFGsdiscr1}  for MFGs}\label{sec: A semi-Lagrange scheme for MFGs}
We introduce a SL scheme to approximate a weak solution to   the MFGs system. 
This scheme is obtained by combining the SL scheme for the HJB equation defined in \cref{A_fully_discrete_scheme_for_the_Hamilton_Jacobi_Bellman_equation} and the SL scheme for the continuity equation defined in \cref{A_fully_discrete_scheme_for_the_continuity_equation}. We show that, under suitable assumptions, there exists a  solution to this scheme and it converges to a weak solution to   the MFGs system. \\ 
We define $f,g : \GG_{\Delta x} \times \S(\GG_{\Delta x})\to\RR$ 
by 
\begin{equation*} 
    f(x_i,\nu)\coloneqq F(x_i,M_{\Delta x}[\nu]), \qquad g(x_i,\nu)\coloneqq G(x_i,M_{\Delta x}[\nu]). 
\end{equation*}
The proposed SL scheme is the following: find $(m,v) \in \S(\GG_{\Delta})\times \BB(\GG_{\Delta})$ such that 
\begin{equation}\label{eq:MFGsdiscr1}\tag{$MFG^1_d$}
            \begin{aligned}
               &v_{i,k}=I_{\Delta x}[v_{k+1}](x_{i}-\Delta t q_{i,k})+\Delta tL(x_i,q_{i,k})  +\Delta t f(x_i,m_k)&&\text{for any   }(i,k)\in \Ixt ^*, \\
                 &m_{i,k+1}=\sum_{j\in \Ix}m_{j,k} \int_{\RR^d}\beta_{i}(x_{j}-\Delta t q_{j,k})\dd[\mu_{j,k}](a)  &&\text{for any   }(i,k)\in \Ixt ^*,\\
               &v_{i,N_T}=g(x_i, m_{N_T}), \qquad m_{i,0}=\int_{E_{i}}\dd [m^*_{0}](x)&&  \text{for any  }i\in \Ix,\\  
            \end{aligned}
\end{equation}
 with  $q \in \Lambda_{\Delta}[v]$  and $\mu\in \M_{\Delta }[v]$.
We consider the following assumptions:
\begin{Hassum}[resume]
\item \label{DiscreteMonotonicity} for $h=f,g$ the following monotonicity condition holds   
  \begin{equation*}
  \sum_{i \in \Ix}\Big(h(x_i,\nu)- h(x_i,\tilde \nu)  \Big)\Big(\nu_i-\tilde \nu_i\Big)\geq 0  \,\text{ for any } \nu,\tilde \nu\in \S(\GG_{\Delta x}) \text{ with compact support};
\end{equation*}
\item \label{condition dxdt for compact support discrete solution}
the pair $\Delta=(\Delta x,\Delta t)$ of spatial and time step is such  that $ \Delta x < c \Delta t$, for some $c>0$.
\end{Hassum}
\begin{rem}\label{rem: discrete monotonicity}  Under \cref{C2bounded}, if \ref{monoticityassumption} holds with the strict inequality for  distinct measures, then \ref{DiscreteMonotonicity} holds for any $\Delta x>0$ small enough. To verify this assertion, we take $\nu,\tilde \nu $ as in \ref{DiscreteMonotonicity}. We observe that, since $\nu,\tilde \nu$ have compact support, the following sums on $\Ix$ are finite.
Therefore, due to \ref{C2bounded} and \ref{monoticityassumption}, we have 
\begin{equation*}
    \begin{aligned}
        &0<\int_{\RR^d}\Big(F(x,M_{\Delta x}[\nu])- F(x,M_{\Delta x}[\tilde \nu])  \Big)\Big(M_{\Delta x}[\nu](x)-M_{\Delta x}[\tilde \nu](x)\Big) \dd x\\   
         &= \sum_{j \in \Ix} \int_{E_j}\Big(F(x,M_{\Delta x}[\nu])- F(x,M_{\Delta x}[\tilde \nu])  \Big)\Big(M_{\Delta x}[\nu](x_j)-M_{\Delta x}[\tilde \nu](x_j)\Big) \dd x \\ 
        &=\sum_{j \in \Ix}\Big(f(x_j,\nu)- f(x_j,\tilde \nu)  \Big)\Big(\nu_j-\tilde \nu_j\Big) + \mathcal{O}(\Delta x).\\ 
    \end{aligned}
\end{equation*}
Taking 
$\Delta x>0$ small enough, the claim follows.
\end{rem}
For any   $v \in \BB(\GG_{\Delta})$, $q\in \Lambda_{\Delta }[v]$ and $\mu\in \M_{\Delta}[v]$, we notice that, for any $(i,k)\in \Ixt^*$,
\begin{equation}\label{optimalrelaxedcontrolproperty}
  I_{\Delta x}[v_{k+1}](x_{i}-\Delta t q_{i,k})+\Delta tL(x_i,q_{i,k}) =\int_{\RR^d}\Big(I_{\Delta x}[v_{k+1}](x_{i}-\Delta t a)+\Delta tL(x_i,a) \Big)\dd[\mu_{i,k}](a). 
\end{equation}
We observe that, for any $v,\tilde v \in \BB(\GG_{\Delta})$, setting $\mu\in \M_{\Delta}[v]$ and $\tilde \mu\in \M_{\Delta}[\tilde v]$,
    the following holds  
\begin{equation}\label{minproperty}
 \int_{\RR^d}\Big(I_{\Delta x}[ \tilde v_{i,k+1}](x_i- \Delta t a)+\Delta tL(x_i,a)\Big )\dd [ \mu_{i,k}-\tilde \mu_{i,k}](a)\geq 0 \quad{\text{for any $(i,k)\in \Ixt^*$}}.
\end{equation} 
For any  couple $w=(m,v) \in \S(\GG_{\Delta}) \times \BB(\GG_{\Delta})$,  we consider the operator $A_{\Delta }[w]$ defined as the set of values given by  
\begin{equation*}\label{eq:multivaluedDiscr}
	A_{\Delta }[w] \coloneqq \{ A_{i,k}[w] \, | \,  (i,k)\in\Ixt^* \},
\end{equation*}
where the map $A_{i,j}[w]$ is defined by 
\[
A_{i,k}[w]
\coloneqq
\begin{bmatrix}
	-v_{i,k} + I_{\Delta x}[v_{k+1}](x_i-\Delta t q_{i,k} ) + \Delta tL(x_i,q_{i,k}) +\Delta tf(x_i,m_k)\\
	m_{i,k+1} -  \sum_{j\in \Ix}m_{j,k}\int_{\RR^d}\beta_{i}(x_j-\Delta t a)\dd[\mu_{j,k}](a) \\
\end{bmatrix},
\]
with $q\in \Lambda_{\Delta}[v]$ and  $\mu\in \M_{\Delta}[v]$. We observe that, if $w=(m,v)$ is a solution to \eqref{eq:MFGsdiscr1}, then $A_{\Delta}[w]=0$.
For any $w=(m,v), \tilde w=(\tilde m,\tilde v) \in \S(\GG_{\Delta}) \times \BB(\GG_{\Delta})$, setting $q\in \Lambda_{\Delta}[v]$ and $\mu\in \M_{\Delta}[v]$,  we  define 
   \begin{equation*}
   \begin{aligned}
         &\langle  A_{\Delta }[ w], \tilde w \rangle_{\Delta }:= \\ &	 \sum_{k\in \It^*} \sum_{i\in\Ix} \Big(
		 -v_{i,k}  +  I_{\Delta x}[v_{k+1}](x_i - \Delta t q_{i,k}) + \Delta tL(x_i,q_{i,k}) +\Delta t f(x_i,m_k) \Big) (m_{i,k} - \tilde{m}_{i,k}) \\
		&+  \sum_{k\in \It^*} \sum_{i\in\Ix}\left( m_{i,k+1}  - \sum_{j\in\Ix} m_{j,k}\int_{\RR^d}\beta_i(x_j-\Delta t a)\dd[\mu_{j,k}](a) \right)(v_{i,k+1} - \tilde{v}_{i,k+1} ). 
   \end{aligned}
    \end{equation*}
For any $w,\ov w, \tilde w \in \S(\GG_{\Delta}) \times \BB(\GG_{\Delta})$, the following properties hold 
\begin{equation*}
\begin{aligned}
   \langle  A_{\Delta }[ w], \tilde w\rangle_{\Delta }-\langle  A_{\Delta }[\ov w], \tilde w\rangle_{\Delta }&=\langle  A_{\Delta }[ w]-A_{\Delta }[ \ov w], \tilde w\rangle_{\Delta } ,\\  \langle  A_{\Delta }[w], \tilde w\rangle_{\Delta }-\langle  A_{\Delta }[ w], \ov w\rangle_{\Delta }&=\langle  A_{\Delta }[ w], \tilde w-\ov w \rangle_{\Delta }.
\end{aligned}
\end{equation*}
The operator $A_{\Delta}$ satisfies the following monotonicity properties,  whose proof is given in \cref{Appendix}. 
\begin{prop}\label{Adelta properties}
   For any  $w=(m,v), \tilde w=(\tilde m,\tilde v) \in \S(\GG_{\Delta}) \times \BB(\GG_{\Delta})$ such that $m_k$ and $\tilde m_k$ have compact support for any $k\in \It$, setting $q\in \Lambda_{\Delta}[v]$,  $\tilde q\in \Lambda_{\Delta}[\tilde v]$, $\mu \in\M_{\Delta}[v]$ and $\tilde \mu \in\M_{\Delta}[\tilde v]$,   we have 
       \begin{equation}\label{eq:equality Adelta}
   \begin{aligned}
         \langle  A_{\Delta }[\tilde w]-A_{\Delta }[ w], \tilde w-w \rangle_{\Delta }&=  \sum_{i\in \Ix} \big((\tilde v_{i,0}-v_{i,0})(m_{i,0}-\tilde m_{i,0}) +(v_{i,N_T}-\tilde v_{i,N_T})(m_{i,N_T}-\tilde m_{i,N_T})\big)\\
+&\sum_{(i,k)\in\Ixt^*}m_{i,k}\int_{\RR^d}\Big(I_{\Delta x}[ \tilde v_{i,k+1}](x_i- \Delta t a)+\Delta tL(x_i,a)\Big )\dd [ \mu_{i,k}-\tilde \mu_{i,k}](a)\\ 
          +&\sum_{(i,k)\in\Ixt^*} m_{i,k}\int_{\RR^d}\Big(I_{\Delta x}[  v_{i,k+1}](x_i- \Delta t a)+\Delta tL(x_i,a)\Big )\dd[\tilde \mu_{i,k}-\mu_{i,k}](a)\\
            +&\sum_{(i,k)\in\Ixt^*}\Delta t \,\big(f(x_i,m_k)-f(x_i,\tilde m_k)\big)(m_{i,k}-\tilde m_{i,k}).\\ 
   \end{aligned}
    \end{equation}   
If \ref{DiscreteMonotonicity} is also satisfied, then 
           \begin{equation}\label{eq: inequality Adelta discrmon}
   \begin{aligned}
      \langle  A_{\Delta }[\tilde w]-A_{\Delta }[ w], \tilde w-w \rangle_{\Delta }&\geq   \sum_{i\in \Ix} \big((\tilde v_{i,0}-v_{i,0})(m_{i,0}-\tilde m_{i,0}) +(v_{i,N_T}-\tilde v_{i,N_T})(m_{i,N_T}-\tilde m_{i,N_T})\big).
   \end{aligned}
    \end{equation}
\end{prop}

\begin{rem}
 Under \ref{DiscreteMonotonicity}, it follows that $A_{\Delta}$ combining with the initial and terminal conditions is \textit{monotone}, i.e. for any   $w=(m,v), \tilde w=(\tilde m,\tilde v) \in \S(\GG_{\Delta}) \times \BB(\GG_{\Delta})$ as in \cref{Adelta properties} and, in addition, such that,  for any $i\in \Ix$, $m_{i,0}=\tilde m_{i,0}$,    
 $v_{i,N_T}=g(x_i,m_{N_T})$  and $\tilde v_{i,N_T}=g(x_i,\tilde m_{N_T})$, 
 \begin{equation*}
      \langle  A_{\Delta }[\tilde w]-A_{\Delta }[ w], \tilde w-w \rangle_{\Delta }\geq 0.
 \end{equation*}
 \end{rem}
\begin{prop}\label{existenceMFGsd1}
     Let us assume \onlyref{continuity,initialdensity,ass:lagrangian} and $\Delta=(\Delta x,\Delta t)>0$ such that \ref{condition dxdt for compact support discrete solution} holds. Then there exists at least one solution to \eqref{eq:MFGsdiscr1}.
\end{prop}
\begin{proof}
We prove the existence of a solution to \eqref{eq:MFGsdiscr1} by applying
Kakutani’s fixed point theorem to a suitably defined multivalued map $\Psi:X\to 2^{X}\setminus \emptyset$,  as in  \cite{AshrafyanGomes}. We define the set $X\coloneqq\{\mu=(\mu_{i,k})_{(i,k)\in \Ixt^*}  \, | \, \mu_{i,k}\in \P_1(\RR^d), \, \supp(\mu_{i,k})\subseteq \ov B_\infty(0,C_H) \}$. It is compact and convex.
Given $\mu\in X$, let $m\in \S(\GG_{\Delta})$ be defined by  \eqref{eq:CEdiscr} and  $m_{\Delta}:=M_{\Delta}[m]$. Given $m_{\Delta}$,  let $v\in \BB(\GG_{\Delta})$ be defined by  \eqref{eq:HJBdiscr} and we take the set $\Lambda_{i,k}[v]$ defined by \eqref{optimal set}. Finally, we define 
\begin{equation*}
    \Psi(\mu)\coloneqq\{\ov \mu=(\ov \mu_{i,k})_{(i,k)\in \Ixt^*} \, | \, \ov \mu_{i,k}\in \P_1(\RR^d), \, \supp(\ov \mu_{i,k})\subseteq  \Lambda _{i,k}[v] \}.
\end{equation*}
We note that $\Psi(\mu)$ is a compact and convex set. The map  $\Psi$ is upper hemicontinuous, i.e. for any $\mu^n,\mu \in X$ such that $\mu^n \rightharpoonup \mu $ and for any $\ov \mu^n \in \Psi(\mu^n)$ such that  $\ov \mu^n \rightharpoonup \ov \mu$ for a some $ \ov \mu$, we have that $\ov \mu \in \Psi (\mu)$. To prove this property, we start by fixing $(i,k)\in \Ixt^*$.
According to \cite[Proposition 5.1.8]{AmbrosioGigliSavar}, the convergence $\ov \mu_{i,k} ^n \rightharpoonup \ov \mu_{i,k} $ implies that 
\begin{equation}\label{due to covnergennce of ovBn}
    \forall \ov a_{i,k} \in \supp(\ov \mu _{i,k}), \, \exists \,\ov a_{i,k}^n \in \supp(\ov \mu ^n_{i,k}) \, \text{ s.t. }\,  \lim_{n\to \infty}\ov a_{i,k}^n= \ov a_{i,k}. 
\end{equation}
As before, given $\mu^n$, let $m^n\in \S(\GG_\Delta)$ be defined by  \eqref{eq:CEdiscr} and  $m^n_{\Delta}:=M_{\Delta}[m^n]$. Given $m^n_{\Delta}$, let $v^n\in \BB(\GG_{\Delta})$ be defined by \eqref{eq:HJBdiscr}  and  $v^n_{\Delta}:=V_{\Delta}[v^n]$. In the same way, given $\mu$, we define $(m,m_{\Delta},v, v_{\Delta})$. We observe that $v^n_{\Delta}$ converges to $v_{\Delta}$ locally uniformly in $Q_T$. Indeed, according to  \cite[Proposition 7.1.5]{AmbrosioGigliSavar},  $\supp (\mu^n)_{i,k}\subset\ov B_\infty(0,C_H)$ and  $\mu ^n_{i,k} \rightharpoonup  \mu_{i,k}$ imply that  $\mu^n_{i,k}\to \mu_{i,k}$. Therefore, by definition of $m^n_{\Delta}$ and $m_{\Delta}$, we have $m^n_{\Delta}( t)\to m_{\Delta}(t)$ in $\P_1(\RR^d)$ for any $t \in [0,T]$. Combing with \ref{continuity}, this implies the locally uniform convergence of $v^n_{\Delta}$ to $v_{\Delta}$. We define $\omega^n,\omega: \ov B_{\infty}(0, C_H)\to \RR$ such that $ \omega^n(a)\coloneqq I_{\Delta x}[v^n_{k+1}](x_i-\Delta t a)+\Delta t L(x_i,a)$ and   $\omega(a)\coloneqq I_{\Delta x}[v_{k+1}](x_i-\Delta t a)+\Delta t L(x_i,a)$. We observe that $\omega^n$ converges uniformly to $\omega$ because $\sup_{a\in \ov B_{\infty}(0,C_H)}|\omega^n(a)-\omega(a)|=\sup_{a\in \ov B_{\infty}(0,C_H)}|v^n_{\Delta}(x_i-\Delta t a,t_k)-v_{\Delta}(x_i-\Delta t a,t_k)|$, due to \eqref{interperr}. 
Applying \cref{Compact nostrict Lemma 2.4 CapuzzoDolcetta}, we obtain that
\begin{equation}\label{due to covnergennce of controls}
\begin{aligned}
      &  \forall a^n_{i,k} \in \Lambda_{i,k}[v^n],  \text{ for any convergent subsequence (at least one exists), still denoted by $ a^n_{i,k}$}, \\ & \exists a^*_{i,k}\in  \Lambda_{i,k}[v] \,  \text{ s.t } \,  \lim_{n\ \to \infty} a_{i,k}^{n}=  a^*_{i,k}.
\end{aligned}
\end{equation}
We aim to show that $\ov \mu \in \Psi(\mu)$,  i.e. for any $(i,k)\in \Ixt^*$ we have $\supp(\ov \mu_{i,k})\in \Lambda_{i,k}[v]$. Let $\ov a_{i,k}\in \supp(\ov \mu_{i,k})$. Due to \eqref{due to covnergennce of ovBn}, there exists  $\ov a_{i,k}^n \in \supp(\ov B^n_{i,k})$ s.t. $\lim_{n \to \infty}\ov a^n_{i,k}= \ov a_{i,k}$.   In addition, due to \eqref{due to covnergennce of controls}, there exists $ a^*_{i,k}\in  \Lambda_{i,k}[v]$ s.t. $\lim_{n\ \to \infty} a_{i,k}^{n}=  a^*_{i,k}$. For the uniqueness of the limit, $a_{i,k}=a^*_{i,k} \in \Lambda_{i,k}[v]$. Finally, due to Kokutani's fixed-point theorem, there exists a fix point of the map $\Psi$.
\end{proof}
\cref{convergenceschemeMFGsD1} proves the convergence of the scheme \eqref{eq:MFGsdiscr1} to a weak solution to   the MFGs system, and implicitly also establishes the existence of such a solution. Its proof can be obtained using techniques analogous to those in  \cite[Proposition 7.7]{AshrafyanGomes}.
In the following, we will use {\em u.t.s.}
to indicate that the convergence holds up to subsequences.

\begin{theo}\label{convergenceschemeMFGsD1}
  Let us assume  \onlyref{continuity,C2bounded,initialdensity,ass:lagrangian}.  Consider a sequence  $\Delta_n=(\Delta x_n,\Delta t_n)>0$ such that $(\Delta x_n,\Delta t_n)\to 0$ and $\frac{\Delta x_n}{\Delta t_n}\to 0$ as $n\to \infty$, and assume that \onlyref{DiscreteMonotonicity,condition dxdt for compact support discrete solution} hold for any $(\Delta x_n, \Delta t_n)$.  Let $(m^n,v^n)$  be a solution to \eqref{eq:MFGsdiscr1} for the corresponding grid parameters $(\Delta x_n,\Delta t_n)$. Let $m_{\Delta_n}=M_{\Delta_n}[m^n]$ and $v_{\Delta_n}=V_{\Delta_n}[v^n]$.
Then there  exists  a weak solution $(m^*,v^*)$ to    the MFGs system such that, u.t.s., $m_{\Delta_n}(t)\to m^*(t)$ in $\P_1(\RR^d)\cap  L^1({\RR^d})$ for any $t\in [0,T]$,  and $v_{\Delta_n}\rightharpoonup^* v^*$ in $L^\infty(Q_T)$. 
\end{theo}
\begin{proof}

We define $w^n\coloneqq (m^n,v^n)$ and $w_{\Delta_n}\coloneqq(m_{\Delta_n},v_{\Delta_n})$.
Our goal is to prove that there exists a  $w^*=(m^*,v^*)$, weak u.t.s. limit of $w_{\Delta_n}$, 
such that
\begin{equation}\label{eq:tesi}
    \langle \mathcal A [ \varphi], \varphi-w^* \rangle \geq 0 \qquad \text{ for any } \varphi \in \mathcal{D}.
\end{equation}
 To prove \eqref{eq:tesi}, we will show that  for any $\varphi=(\phi,\psi)\in \mathcal{D}$ the following hold
 \begin{equation}\label{eq:tesi1}
\langle \mathcal A [ \varphi], \varphi-w_{\Delta _n} \rangle \to \langle \mathcal A [ \varphi], \varphi-w^* \rangle,\qquad  
 \end{equation}
 and 
 \begin{equation}\label{eq:tesi2}
     \mathcal{E}_1(\Delta_n)\leq \langle  A_{\Delta _n}[ \varphi^n], \varphi^n-w^n \rangle_{\Delta_n} = \langle \mathcal A [ \varphi], \varphi-w_{\Delta _n} \rangle + \mathcal{E}_2(\Delta_n)+\mathcal{E}_3(\Delta_n),
 \end{equation}
where  
   $\mathcal{E}_i(\Delta_n) \to 0$ as $n\to \infty$, for $i=1,2,3$,  $\varphi^n:=(\phi^n,\psi^n) \in \S(\GG_{\Delta_n})\times \BB(\GG_{\Delta_n})$ and
\begin{equation*}
    \phi^n_{i,k}\coloneqq \int_{E_i}\phi(x,t_k)\dd x, \qquad \psi^n_{i,k}\coloneqq \psi(x_i,t_k), \qquad \text{for any } (i,k)\in\Ixtn.
\end{equation*}
We define the  extensions $\phi_{\Delta_n}\coloneqq M_{\Delta_n}[\phi^n]$  and $ \psi_{\Delta_n}\coloneqq V_{\Delta_n}[\psi^n]$.
We observe that $\phi(\cdot,t)$, $\psi(\cdot,t)$, $\phi_{\Delta _n}(\cdot,t),\psi_{\Delta _n}(\cdot,t)$,
and $m_{\Delta_n}(\cdot,t)$
have compact support in $\ov B(0,R_1)$, with $R_1 > C>0$ and $C$ as in \cref{SLCEproperties}.
Moreover, for any $k\in\It$, by the regularity of $\phi(\cdot,t_k)$, we have
\begin{equation}\label{eq:step5a}
    d_1(\phi_{\Delta_n}(t_k),\phi(t_k))=\mathcal{O}(\Delta x_n),
\end{equation}
and  the following error estimate of the midpoint quadrature rule on $E_i$
\begin{equation}\label{eq:step5b}
     \sup_{i\in \Ixn}|
     \phi_{\Delta_n}(x_i,t_k)-\phi(x_i,t_k)|
   =\mathcal{O}(\Delta x_n^{2}).
\end{equation}
We organize the proof in the following steps, where we will make us of the following definitions.
We set
 $\Jxn\coloneqq\{i\in\Ixn | x_i\in \ov B(0,R_1+\sqrt{d}TC_H) \}$,
which implies $\sum_{i \in \Jxn}\beta_i (x_j- \Delta t_n a)=1$, for any   $a \in \ov B_{\infty}(0,C_H)$ and  $x_j \in \ov B (0,R_1)$. Given $\nu^n\in\M_{\Delta_n}[\psi^n]$, we define $\nu_{\Delta_n}^{x,t}\in \P(\RR^d)$ as 
\begin{equation*}
\begin{aligned}
\nu_{\Delta_n}^{x,t}\coloneqq \nu^n_{i,k} \quad \text{if }(x,t) \in E_i\times[t_k,t_{k+1}),\quad \nu_{\Delta_n}^{x,t}\coloneqq \nu^n_{i,N_{T}-1} \quad \text{if }t=T,
\end{aligned}
\end{equation*}
 for any $(x,t)\in Q_T$.

\textit{Step 1: Existence of $w^*$ and proof of \eqref{eq:tesi1}.} By \cref{properties decrete value function}, $||v_{\Delta_n}||_{L^\infty(Q_T)}\leq  \widetilde C_{\text{{\rm v}}}$ for any $n\in\NN$. According to the Riesz Representation theorem, there exists $v^*\in L^\infty(Q_T)$ such that, u.t.s., 
 $v_{\Delta_n}\rightharpoonup^* v^*$,  
\begin{equation*}
 {\text {i.e.}}\quad  \int_{Q_T}v_{\Delta_n}(x,t) \zeta(x,t)\dd x \dd t\to \int_{Q_T}v^*(x,t) \zeta(x,t)\dd x\dd t \qquad \text{for any } \zeta \in L^1(Q_T).
\end{equation*}
For any $t\in [0,T]$, by \cref{SLCEproperties}, $m_{\Delta_n}(t)$ are uniform tight measures. Then, by Prokhorov's theorem (see \cite[Theorem 5.1.3]{AmbrosioGigliSavar}), the sequence $m_{\Delta_n}(t)$ is relative compact in $\P_1(\RR^d)$. By \cref{SLCEproperties}, $m_{\Delta_n}(t)$ have uniformly integrable first moments. Then, by   \cite[Proposition 7.1.5]{AmbrosioGigliSavar}, there exists $m^*(t)\in \P_1(\RR^d)$ such that, u.t.s., $m_{\Delta_n}(t) \to m^*(t)$ in $\P_1(\RR^d)$.
 In addition, since $||m_{\Delta_n}(\cdot,t)||_{L^1(\RR^d)}=1$ for any $t\in [0,T]$, $m_{\Delta_n}(\cdot,t)\rightharpoonup m^*(\cdot,t)$ in $L^1(\RR^d)$. We observe that $m^*(x,t)=0$  for a.e.   $x \notin\ov B(0,C)$, and we call $w^*\coloneqq(m^*,v^*)$. This also proves \eqref{eq:tesi1}.

\textit{Step 2: Definition of  $\mathcal{E}_1(\Delta_n)$ and proof that $\mathcal{E}_1(\Delta_n)\to 0$.} We start by noticing that $\langle  A_{\Delta _n}[ \varphi^n], \varphi^n-w^n \rangle_{\Delta_n} = \langle  A_{\Delta _n}[ \varphi^n]-A_{\Delta _n}[ w^n], \varphi^n-w^n \rangle_{\Delta_n}$, since $A_{\Delta_n}[w^n]=0$. Applying \eqref{eq: inequality Adelta discrmon} combined with  the initial and terminal conditions in \eqref{eq:MFGsdiscr1},
we obtain 
\begin{equation*}
    \langle  A_{\Delta _n}[ \varphi^n], \varphi^n-w^n \rangle_{\Delta_n}\geq   \sum_{i\in \Ixn}(g(x_i,m^n_{N_T})- G(x_i,\phi(T))(m^n_{i,N_T}-\phi^n_{i,N_T}). 
\end{equation*}
By adding and subtracting  the terms $g(i,\phi^n_{N_T})(m^n_{i,N_T}-\phi^n_{i,N_T})$ for any $i\in \Ixn$ and using the discrete monotonicity \cref{DiscreteMonotonicity} of $g$, we further 
 obtain 
\begin{equation*}
    \langle  A_{\Delta _n}[ \varphi^n], \varphi^n-w^n \rangle_{\Delta_n}\geq   \sum_{i\in \Ixn}(g(x_i,\phi^n_{N_T})-  G(x_i,\phi (T)))(m^n_{i,N_T}-\phi^n_{i,N_T}). 
\end{equation*}
 Therefore, we set $\mathcal{E}_1(\Delta_n)\coloneqq \sum_{i\in \Ixn}(g(x_i,\phi^n_{N_T})-  G(x_i,\phi (T)))(m^n_{i,N_T}-\phi^n_{i,N_T})$.  We estimate $\mathcal{E}_1(\Delta_n)$ from above, noticing that $g(i,\phi_{\Delta_n}(T))=G(x_i,\phi_{\Delta_n}(T))$, 
\begin{equation*}
\begin{aligned}  
&|\mathcal{E}_1(\Delta x_n,\Delta t_n)|=|\sum_{i\in \Jxn}( G(x_i,\phi_{\Delta_n}(T))-  G(x_i,\phi (T)))(m^n_{i,N_T}-\phi^n_{i,N_T})|\\
&\leq 2 \sup_{i\in\Jxn}|G(x_i,\phi_{\Delta_n}(T))- G(x_i,\phi (T)|\leq 2 \sup_{x\in\ov B(0,R_1)}|G(x,\phi_{\Delta_n}(T))- G(x,\phi (T)|.\\ 
\end{aligned}
\end{equation*}
We consider the sequence of functions $G(\cdot,\phi_{\Delta_n}(T)):\ov B(0,R_1)\to \RR$. By \eqref{eq:step5a} and \ref{continuity}, this sequence converges pointwise to  $G(\cdot,\phi(T))$. Moreover, by \ref{C2bounded},  these functions  are equi-bounded and equi-Lipschitz. By Ascoli-Arzelà theorem, there exists a subsequence, still denoted by $G(\cdot,\phi_{\Delta_n}(T))$, that converges uniformly to $G(\cdot,\phi(T))$. 
Since this limit is unique, we  conclude that  $\lim_{n\to \infty}\sup_{x\in\ov B(0,R_1)}|G(x,\phi_{\Delta_n}(T))- G(x,\phi (T)|= 0$, which implies that $\mathcal{E}_1(\Delta_n)\to 0$ as $n\to \infty$.

\textit{Step 3: Definition of  $\mathcal{E}_2(\Delta_n)$ and proof that $\mathcal{E}_2(\Delta_n)\to 0$.} We define 
\begin{equation*}
 \begin{aligned}
          &\mathcal{E}_2(\Delta_n)\coloneqq\int_{Q_T}\big(\partial_t\psi(x,t)-H(x,D_x\psi(x,t))+F(x,\phi(t)\big)\big(m_{\Delta_n}(x,t)-\phi(x,t)\big)\dd x\dd t \\ 
          &+\sum_{k\in \Itns} \sum_{i\in\Ixn} \Big(
		  \psi^n_{i,k}   - I_{\Delta x_n}[ \psi^n_{k+1}](x_i - \Delta t_n \xi^n_{i,k}) - \Delta t_n L(x_i,\xi^n_{i,k})  -\Delta t_n  f(x_i,\phi^n_k) \Big) (m^n_{i,k} - \phi^n_{i,k}). 
 \end{aligned}
 \end{equation*}
By defining the grid function $\eta^n \coloneqq m^n-\phi^n$ and the functions 
$h\coloneqq\partial_t\psi-H(x,D_x\psi)+F(x,\phi(t))$, $\eta_{\Delta_n}=m_{\Delta_n}-\phi_{\Delta_n}$,  we can rewrite $\mathcal{E}_2(\Delta_n)$ as the sum of the following four terms.
The first term is
\begin{equation}\label{err2: term1}
    \Delta t_n \sum_{k\in \Itns} \sum_{i\in\Ixn} \Big(
		 F(x_i,\phi(t_k))- F(x_i,\phi_{\Delta_n}(t_k)) \Big) \eta^n_{i,k}
\end{equation}
and tends to zero, arguing as in {\em Step 2}. The second term is
\begin{equation}\label{err2: term2}
\begin{aligned}
          &\Delta t_n\sum_{k\in \Itns} \sum_{i\in\Ixn} \frac{
		  \psi^n_{i,k}   - I_{\Delta x_n}[ \psi^n_{k+1}](x_i - \Delta t_n \xi^n_{i,k}) - \Delta t_n L(x_i,\xi^n_{i,k})  -\Delta t_n  F(x_i,\phi(t_k)) }{\Delta t_n}\eta^n_{i,k} \\ 
  &-\Delta t_n \sum_{k\in \Itns} \sum_{i\in\Ixn} \big(\partial_t\psi(x_i,t_k)-H(x_i,D_x\psi(x_i,t_k))+F(x_i,\phi(t_k))\big)\eta^n_{i,k},
		\\
\end{aligned}
\end{equation}
and goes to zero by the consistency property in \cref{properties decrete value function}. The third term is 
\begin{equation}\label{err2: term3}
    \begin{aligned}
    &\int_{Q_T}h(x,t)\eta_{\Delta_n}(x,t)\dd x\dd t-\Delta t_n \Delta x_n^d\sum_{(i,k)\in \Ixtn^*} h(x_i,t_k)\eta_{\Delta_n}(x_i,t_k),
    \end{aligned}
\end{equation}
and goes to zero because,  using that $\supp( \eta_{\Delta_n}(\cdot,t)) \subseteq \ov B(0,R_1)$ for any $t \in [0,T]$, we can write 
\begin{equation*}
\begin{aligned}
   & \int_{Q_T}h(x,t)\eta_{\Delta_n}(x,t)\dd x\dd t=\int_{\ov B(0,R_1)}\sum_{k\in \Itns}\int_{t_k}^{t_{k+1}}h(x,t)\eta_{\Delta_n}(x,t_k)\dd t\dd x \\ &   =  \Delta t_n \sum_{k\in\Itns} \int_{\ov B(0,R_1)} h(x,t_k)\eta_{\Delta_n}(x,t_k)\dd t\dd x\dd x +\mathcal{O}(\Delta t_n)\\
    & =  \Delta x_n^d \Delta t_n \sum_{k\in\Itns}  \sum_{i\in\Ixn}  h(x_i,t_k)\eta_{\Delta_n}(x_i,t_k)+\mathcal{O}(\Delta t_n+\Delta x_n ).\\
\end{aligned}
\end{equation*}
Finally, the fourth term is
\begin{equation}\label{err2: term4}
    \int_{Q_T}h(x,t)\left(\phi(x,t)-\phi_{\Delta_n}(x,t)\right)\dd x\dd t,
\end{equation}
and goes to zero by \eqref{eq:step5a}. 

\textit{Step 4: Convergence of the optimal controls.}  Given $(x,t)\in Q_T$, we consider a sequence of grid points $(x_{i_n},t_{k_n})\in \Ixtn^*$ such that
$(x_{i_n},t_{k_n})\to(x,t)$.  For any $\xi^n_{i_n,k_n}\in \Lambda_{i_n,k_n}[\psi^n]$, we have  $\xi^n_{i_n,k_n}\to D_pH(x,D_x\psi(x,t))$ as $n\to \infty$. Indeed, by defining 
$\omega^n,\omega: \ov B_{\infty}(0, C_H)\to \RR$ as
\begin{equation*}
    \omega^n(a)\coloneqq \frac{I_{\Delta x_n}[\psi^n_{k_n+1}](x_{i_n}-a_n\Delta t_n )-\psi(x_{i_n},t_{k_n})}{\Delta t_n}+ L(x_{i_n},a)
\end{equation*} 
and $ \omega(a)\coloneqq -aD_x\psi (x,t)+L(x,a)$,  it follows that 
$\omega^n,\omega\in \CC(\ov B_{\infty}(0,C_H))$ and $\omega^n$ converges uniformly to $\omega$.  
According to \cref{Compact Lemma 2.4 CapuzzoDolcetta}, we conclude that   $\xi^n_{i_n,k_n}\to D_pH(x,D_x\psi(x,t))$ as $n\to \infty$, since $D_pH\big(x,D_x\psi (x,t)\big)=\amin_{a\in \ov{B}_{\infty}(0,C_H)} \omega(a)$. 

\textit{Step 5: Convergence of the related controls.} For any  $(x,t)\in Q_T$, we have that  $\nu_{\Delta_n}^{x,t}\to \delta_{D_pH(x,D_x\phi(x,t))}$ in $\P_1(\RR^d)$ as $n\to \infty$. Indeed, since by definition $\supp(\nu_{\Delta_n}^{x,t})\subseteq \ov B_{\infty}(0,C_H)$, $\nu_{\Delta_n}^{x,t}$ is a sequence of uniform tight measures with uniformly integrable first moments. Then, by Prokhorov's theorem (see \cite[Theorem 5.1.3]{AmbrosioGigliSavar}), $\nu_{\Delta_n}^{x,t}$ is relative compact in $\P_1(\RR^d)$ and by \cite[Proposition 7.1.5]{AmbrosioGigliSavar}, we conclude that there exists $\nu^{x,t}\in \P_1(\RR^d)$ such that, u.t.s., $\nu_{\Delta_n}^{x,t}\to \nu^{x,t}$. It remains to show that $\nu^{x,t}=\delta_{D_pH(x,D_x\psi(x,t))}$, i.e. $\supp(\nu^{x,t})=\{D_pH(x,D_x\psi(x,t))\}$. 
By definition, for any $n\in \NN$,  there exists a sequence of grid points $(i_n,k_n)\in \Ixtn^*$ such that $(x,t)\in E_{i_n}\times [t_{k_n},t_{k_n+1})$. Then, $\nu_{\Delta_n}^{x,t}=\nu^n_{i_n,k_n}$ and  $\supp(\nu_{\Delta_n}^{x,t})\subseteq\Lambda_{i_n,k_n}[\psi^n]$. By \cite[Proposition 5.1.3]{AmbrosioGigliSavar}, for any $a\in \supp(\nu^{x,t})$, there exists a sequence $a^n\in \supp(\nu_{\Delta_n}^{x,t})$ such that $a^n\to a$. By \emph{Step 4},  $a=D_pH(x,D_x\phi(x,t).$ Finally, since the limit is unique, then the whole sequence converges to $\delta_{D_pH(x,D_x\psi(x,t))}$. 

\textit{Step 6:  Definition of  $\mathcal{E}_3(\Delta_n)$ and proof that $\mathcal{E}_3(\Delta_n)\to 0$.}  We define
 \begin{equation*}
 \begin{aligned}
          \mathcal{E}_3(\Delta_n)\coloneqq  &\int_{Q_T}\Big(\partial_t\phi(x,t)-\diver\big(\phi(x,t)D_pH\big(x,D_x\psi(x,t)\big)\big)\Big)\big(v_{\Delta_n}(x,t)-\psi(x,t)\big)\dd x\dd t\\
          &+\sum_{k\in \Itns} \sum_{i\in\Ixn} \Big(- \phi^n_{i,k+1}  + \sum_{j\in\Ixn}  \phi^n_{j,k} \int_{\RR^d}\beta_i(x_j-\Delta t_n a )\dd[\nu^n_{j,k}](a) \Big) (v^n_{i,k+1} - \psi^n_{i,k+1} ).       
 \end{aligned}
 \end{equation*}
We define  the grid function   $l^n:= v^n-\psi^n$ and the function $l_{\Delta_n}\coloneqq v_{\Delta_n}-\psi$. We rewrite $\mathcal{E}_3(\Delta_n)$ as the sum of the following three terms.
The first term of $\mathcal{E}_3(\Delta_n)$ is
\begin{equation}\label{err3: term1}
    \begin{aligned}
       &  \Delta t_n \sum_{k\in \Itns} \sum_{i\in\Ixn} \left(- \frac{\phi^n_{i,k+1}-\phi^n_{i,k}}{\Delta t_n} \right) l_{\Delta_n}(x_i,t_{k+1}) +\int_{Q_T}\partial_t\phi(x,t)l_{\Delta_n}(x,t)\dd x\dd t\\
    \end{aligned}
\end{equation}
and it goes to zero. Indeed, 
 the regularity of $\psi$ and $\phi$, the definition of $R_1$, the Lipschitz property of $l_{\Delta_n}(\cdot, t)$ for any $t \in [0,T]$ (see \cref{properties decrete value function}),  and  \eqref{eq:step5b},  imply that the second term in  \eqref{err3: term1} is such that
\begin{equation*}
    \begin{aligned}
        &\sum_{k\in \Itns} \int_{\ov B(0,R_1)}\int_{t_k}^{t_{k+1}}\partial_t\phi(x,t)\big(v_{\Delta _n}(x,t_{k+1})-\psi(x,t)\big)\dd x\dd t \\
                & =\Delta t_n\sum_{k\in \Itns} \int_{\ov B(0,R_1)}\partial_t\phi(x,t_{k+1})l_{\Delta_n}(x,t_{k+1})\dd x+\mathcal{O}(\Delta t_n)\\
                   & =\Delta t_n\sum_{k\in \Itns} \int_{\ov B(0,R_1)}  \frac{\phi(x,t_{k+1})-\phi(x,t_{k+1})}{\Delta t_n}l_{\Delta_n}(x,t_{k+1})\dd x +\mathcal{O}(\Delta t_n)\\
          &=\Delta x_n^d \Delta t_n \sum_{k\in \Itns} \sum_{i\in\Jxn}\frac{\phi(x_i,t_{k+1})-\phi(x_i,t_{k})}{\Delta t_n}  l_{\Delta_n}(x_i,t_{k+1})  +\mathcal{O}\left(\Delta t_n+\frac{\Delta x_n}{\Delta t_n}\right)\\
          &=\Delta x_n^d \Delta t_n \sum_{k\in \Itns} \sum_{i\in\Jxn} \frac{\phi^n_{i,k+1}-\phi^n_{i,k}}{\Delta t_n}  l_{\Delta_n}(x_i,t_{k+1}) +\mathcal{O}\left(\Delta t_n+\frac{\Delta x_n}{\Delta t_n}\right). 
 \end{aligned}
 \end{equation*}
The second term of $\mathcal{E}_3(\Delta_n)$ is
\begin{equation}\label{err3: term2}
\begin{aligned}
&\sum_{k\in \Itns} \sum_{j\in\Ixn}\phi^n_{j,k}\Big(\sum_{i\in\Ixn} \beta_i(x_j-\Delta t_nD_pH(x_j,D_x \psi(x_j,t_{k+1})) )  l^n_{i,k+1}  -l^n_{j,k+1} \Big)\\ 
&-\int_{Q_T}\diver\big(\phi(x,t)D_pH(x,D_x \psi(x,t))\big)l_{\Delta_n}(x,t)\dd x\dd t,      
\end{aligned}
\end{equation}
and it goes to zero. Indeed, the definition of $R_1$, the regularity of $\phi$ and $\psi$, estimates \eqref{interperr} and \eqref{eq:step5b},
and the Lipschitz property of $l_{\Delta_n}(\cdot, t)$ for any $t \in [0,T]$, imply
that the first term in \eqref{err3: term2} is such that
\begin{equation*}\label{err3: term2 sum scrittura1}
    \begin{aligned}
      &\sum_{k\in \Itns} \sum_{j\in\Jxn}\phi^n_{j,k}\Big(\sum_{i\in\Jxn} \beta_i(x_j-\Delta t_nD_pH(x_j,D_x \psi(x_j,t_{k+1})) )  l^n_{i,k+1}  -l^n_{j,k+1} \Big)\\ 
     &=  \sum_{k\in \Itns} \sum_{j\in\Jxn}\phi^n_{j,k}\Big(I_{\Delta x_n}[l^n_{k+1}](x_j-\Delta t_n D_pH(x_j,D_x \psi(x_j,t_{k+1})))-l^n_{j,k+1}\Big) \\ 
    & = \sum_{k\in \Itns} \sum_{j\in\Jxn} \phi^n_{j,k}\Big( l_{\Delta_n}(x_j-\Delta t_n D_pH(x_j,D_x \psi(x_j,t_{k+1})),t_{k+1}) -l^n_{j,k+1}  \Big)  +\mathcal{O}\left(\frac{\Delta x_n^2}{\Delta t_n}\right) \\
    &        
      =\Delta x_n^d \sum_{\substack{k\in \Itns \\j\in\Jxn
      } }\phi(x_j,t_k)\Big( l_{\Delta_n}(x_j-\Delta t_n D_pH(x_j,D_x \psi(x_j,t_{k+1})) ,t_{k+1}) -l^n_{j,k+1} \Big) +\mathcal{O}\left(\frac{\Delta x_n^2}{\Delta t_n}\right) \\ 
    &= \int_{\ov B(0,R_1)\times [0,T]}\phi(x,t)  \frac{l_{\Delta_n}(x-\Delta t_nD_pH(x,D_x \psi (x,t)) ,t)-l_{\Delta_n}(x,t)}{\Delta t_n} \dd x\dd t  +\mathcal{O}\left(\frac{\Delta x_n}{\Delta t_n}+\Delta t_n\right).
    \end{aligned}
\end{equation*}
Moreover observing that,  again by the Lipschitz property of $l_{\Delta_n}(\cdot, t)$, 
\begin{equation*}
    \begin{aligned}
         & \int_{\ov B(0,R_1)\times [0,T]}\phi(x,t)  \frac{l_{\Delta_n}(x-\Delta t_nD_pH(x,D_x \psi (x,t)) ,t)-l_{\Delta_n}(x,t)}{\Delta t_n} \dd x\dd t  \\ 
         &=\int_{\ov B(0,R_1)\times[0,T]}\phi(x,t)D_pH(x,D_x \psi(x,t))\cdot D_x l_{\Delta_n}(x,t)\dd x\dd t +o(1),
    \end{aligned}
\end{equation*}
using integration by part and recalling the definition  of $R_1$, we conclude that \eqref{err3: term2} goes to 0.
The third term is
\begin{equation}\label{err3: term3}
\begin{aligned}
  &\sum_{k\in \Itns} \sum_{i\in\Ixn} \sum_{j\in\Ixn}  \phi^n_{j,k}   l_{\Delta_n}(x_i,t_{k+1})\int_{\RR^d}\beta_i(x_j-\Delta t_n a )\dd [\nu^n_{j,k}](a) \\
        &-\sum_{k\in \Itns} \sum_{i\in\Ixn} \sum_{j\in\Ixn} \beta_i(x_j-\Delta t_nD_pH(x_j,D_x \psi (x_j,t_{k+1})) ) \phi^n_{j,k}  l_{\Delta_n}(x_i,t_{k+1}) 
\end{aligned}
\end{equation}
and it goes to zero.
Indeed, by
 the definition of $R_1$, by the regularity of $\psi$ and$\phi$, by the estimate \eqref{interperr}, by the Lipschitz property of $l_{\Delta_n}(\cdot, t)$ (we denote  $\tilde C$ its Lipschitz constant),  and  by \eqref{eq:step5b}  
 we can approximate \eqref{err3: term3} as following,
\begin{equation*}\label{err3: term3 in last step}
    \begin{aligned}
         & \sum_{k\in \Itns} \sum_{j\in\Jxn}\phi^n_{j,k} \int_{\RR^d}I_{\Delta x_n}[ l^n_{k+1}](x_j-\Delta t_n a)\dd[\nu^n_{j,k}](a)\\ 
        & - \sum_{k\in \Itns} \sum_{j\in\Jxn}\phi^n_{j,k} I_{\Delta x_n}[l^n_{k+1}](x_j-\Delta t_nD_pH(x_j,D_x \psi(x_j,t_{k+1})))+ \mathcal{O}\left(\frac{\Delta x_n^2}{\Delta t_n}\right)\\
   &= \sum_{\substack{k\in \Itns \\j\in\Jxn
      } }\phi^n_{j,k} \int_{\RR^d}l_{\Delta_n}(x_j-\Delta t_n a,t_{k+1})-l_{\Delta_n}(x_j-\Delta t_nD_pH(x_j,D_x \psi(x_j,t_{k+1})),t_{k+1})\dd[\nu^n_{j,k}](a),
    \end{aligned}
 \end{equation*}  
 where the term
 \begin{equation*}
       \begin{aligned}  
        &\Big|\sum_{\substack{k\in \Itns \\j\in\Jxn
      } }\phi^n_{j,k} \int_{\RR^d} l_{\Delta_n}(x_j-\Delta t_n a,t_{k+1})-l_{\Delta_n}(x_j-\Delta t_nD_pH(x_j,D_x \psi(x_j,t_{k+1})),t_{k+1})\dd[\nu^n_{j,k}](a)\Big|\\
        &\leq \tilde C \Delta t_n \sum_{k\in \Itns} \sum_{j\in\Jxn}\phi^n_{j,k} \int_{\RR^d}|a-D_pH(x_j,D_x\psi (x_j,t_{k+1}))|\dd[\nu^n_{j,k}](a)\\
        &=\tilde C\Delta x_n^d \Delta t_n \sum_{k\in \Itns} \sum_{j\in\Jxn}\phi(x_j,t_k) \int_{\RR^d}|a-D_pH(x_j,D_x\psi (x_j,t_{k+1}))|\dd[\nu^n_{j,k}](a)+\mathcal{O}\left(\Delta x^2_n\right) \\
          &=\tilde C \int_{0}^{T}\int_{\ov B(0,R_1)}\phi(x,t) \int_{\RR^d}|a-D_pH(x,D_x\psi (x,t))|\dd[\nu_{\Delta_n}^{x,t}](a)\dd x \dd t+\mathcal{O}\left(\Delta x_n+\Delta t_n\right)
    \end{aligned}
\end{equation*}
goes to zero by the Dominated convergence theorem and {\textit{Step 5}}.
In conclusion, $\mathcal{E}_3({\Delta_n})\to 0$, since \eqref{err3: term1}, \eqref{err3: term2} and \eqref{err3: term3} go to zero.


\end{proof}
\begin{rem}
Let us note that an inverse CFL condition $\frac{\Delta x}{\Delta t}\to 0$ is required to ensure convergence,  as is typical in SL scheme,  allowing for large time steps.
A similar condition is required in
\cref{properties decrete value function} to guarantee the consistency of the scheme for the value function, and  in \cref{SLCEproperties}   to ensure the compact support of the discrete distribution.
\end{rem}

 \cref{rem: discrete monotonicity} and \cref{convergenceschemeMFGsD1} prove the following  result. 
\begin{cor}\label{existencewealsolution}
Let us assume  \onlyref{continuity,C2bounded,initialdensity,ass:lagrangian} and \ref{monoticityassumption} with the strict inequality. Then there exists a weak solution to   the MFGs system.
\end{cor}

\subsection{A semi-Lagrangian scheme \eqref{eq:MFGsdiscr2}  for MFGs}\label{sec: A semi-Lagrange scheme 2 for MFGs}
In the reminder of the article, we suppose verified the following assumption:
\begin{Hassum}[resume]
  \item \label{uniquecontrol}
For every $v\in \BB(\GG_{\Delta x})$, $(i,k)\in \Ixt^*$, the set of {discrete optimal controls} $\Lambda_{i,k}[v]$
is a singleton.
\end{Hassum}

Although the discrete optimal controls are not necessarily unique in general, the assumption \ref{uniquecontrol} of uniqueness of the minimizer is reasonable, as it is frequently observed in practice. 
   The authors of \cite{AshrafyanGomes} note that the minimizer is typically unique, except in particular cases such as those involving symmetry. This empirical observation suggests that, in most cases, the function to be minimized (the discrete cost) has a single minimum point.
Indeed, the strict convexity of the cost function generally favors the uniqueness of the minimum. However, the interpolation process introduces a piecewise linear structure that could, in principle, lead to multiple minima. 
Therefore, assuming uniqueness 
can be seen as a practical simplification that enhances computational efficiency. 

We consider the following simplified SL scheme to the MFGs system: find {$(m,v) \in \S(\GG_{\Delta})\times \BB(\GG_{\Delta})$ such that 
\begin{equation}\label{eq:MFGsdiscr2}\tag{$MFG_d^2$}
            \begin{aligned}
               &v_{i,k}=I_{\Delta x}[v_{k+1}](x_{i}-\Delta t q_{i,k})+\Delta tL(x_i,q_{i,k})  +\Delta t f(x_i,m_k)&&\text{for any   }(i,k)\in \Ixt^*, \\
                 &m_{i,k+1}=\sum_{j\in \Ix}\beta_{i}(x_{j}-\Delta tq_{j,k})m_{j,k}  &&\text{for any   }(i,k)\in \Ixt^*,\\
               &v_{i,N_T}=g (i, m_{N_T}), \qquad m_{i,0}=\int_{E_{i}}\dd [m^*_{0}](x)&&  \text{for any  }i\in \Ix \\  
            \end{aligned}
\end{equation}
 and $q \in \BB(\GG^*_{\Delta};\RR ^d)$ such that
\begin{equation}\label{eq:qMFGs}
        q_{i,k}=\amin_{a\in \ov{B}_{\infty}(0,C_H)}\left\{I_{\Delta x}[v_{k+1}](x_{i}-\Delta t a)+\Delta tL(x_i,a)\right\}\qquad \text{for any   }(i,k)\in \Ixt^*.
\end{equation}
\begin{rem}\label{rem equivalent schemes}
     We notice that, under \ref{uniquecontrol},  the schemes \eqref{eq:MFGsdiscr1} and \eqref{eq:MFGsdiscr2} are equivalent. In fact, \ref{uniquecontrol} implies that there exists a unique $q \in \Lambda_{\Delta}[v]$. Consequently, if $\mu \in \M_{\Delta}[v]$, then $\mu_{i,k}=\delta_{q_{i,k}}$ for any $(i,k)\in \Ixt^*.$ 
\end{rem}
Using the monotonicity property \cref{Adelta properties}, we can prove a uniqueness result as follows:\begin{prop}\label{uniquenessMFGsd2}
    Let us assume \ref{initialdensity} 
    and let $\Delta=(\Delta x,\Delta t)>0$ be such that \onlyref{uniquecontrol,DiscreteMonotonicity,condition dxdt for compact support discrete solution} hold. If $(m,v)$ and $(\tilde m,\tilde v)$  are two solutions to \eqref{eq:MFGsdiscr2}, then $(m,v)=(\tilde m,\tilde v)$.
\end{prop}
\begin{proof}
     The proof can be obtained similarly to \cite[Lemma 7.2]{AshrafyanGomes}. 
Let $w=(m,v)$ and $\tilde w=(\tilde m,\tilde v)$  be two solutions to \eqref{eq:MFGsdiscr2}, $q\in \Lambda_{\Delta}[v]$ and $\tilde q\in \Lambda_{\Delta}[\tilde v]$ be the respective unique grid functions of optimal controls, and $\mu\in \M_{\Delta}[v]$ and $\tilde \mu\in \M_{\Delta}[\tilde v]$ be the relaxed controls as in \cref{rem equivalent schemes}. Then $A_\Delta [w]=A_\Delta [\tilde w]$. According to \cref{SLCEproperties}, both $m_k$ and $\tilde m_k$ have compact support for any $k\in \It$. Using \eqref{eq:equality Adelta}, the initial and terminal condition in \eqref{eq:MFGsdiscr2}, \ref{DiscreteMonotonicity},  \eqref{minproperty} and the fact that $m_{i,k}, \tilde m_{i,k}\geq 0$ for any $(i,k)\in \Ixt$, we obtain 
       \begin{equation*}
        \begin{aligned}
           &0 = \langle  A_\Delta[\tilde w]-A_\Delta[ w], \tilde w-w \rangle_{\Delta} \\ 
            & = \sum_{i\in \Ix}\big(g(i,m_{N_T})-g(i,\tilde m_{N_T})\big)(m_{i,N_T}-\tilde m_{i,N_T}) \\
        &+\sum_{(i,k)\in\Ixt^*}m_{i,k}\big(I_{\Delta x}[ \tilde v_{i,k+1}](x_i- \Delta t q_{i,k})+\Delta tL(x_i,q_{i,k})-I_{\Delta x}[\tilde v_{i,k+1}](x_i-\Delta t \tilde q_{i,k})-\Delta tL(x_i,\tilde q_{i,k}) \big)\\ 
        &+\sum_{(i,k)\in\Ixt^*}\tilde m_{i,k}\big(I_{\Delta x}[  v_{i,k+1}](x_i-  \Delta t \tilde q_{i,k})+\Delta tL(x_i,\tilde q_{i,k})-I_{\Delta x}[v_{i,k+1}](x_i- \Delta t q_{i,k})-\Delta tL(x_i,q_{i,k})\big)\\
            &+\Delta t\sum_{(i,k)\in\Ixt^*}\big(f(x_i,m_k)-f(x_i,\tilde m_k)\big)(m_{i,k}-\tilde m_{i,k})\\ 
            &\geq  \sum_{(i,k)\in\Ixt^*}m_{i,k}\big(I_{\Delta x}[ \tilde v_{i,k+1}](x_i- \Delta t q_{i,k})+\Delta tL(x_i,q_{i,k})-I_{\Delta x}[\tilde v_{i,k+1}](x_i- \Delta t\tilde q_{i,k})-\Delta tL(x_i,\tilde q_{i,k}) \big)\\ 
        &+\sum_{(i,k)\in\Ixt^*}\tilde m_{i,k}\big(I_{\Delta x}[  v_{i,k+1}](x_i-  \Delta t \tilde q_{i,k})+\Delta tL(x_i,\tilde q_{i,k})-I_{\Delta x}[v_{i,k+1}](x_i- \Delta t q_{i,k})-\Delta tL(x_i,q_{i,k})\big)\\
               &\geq 0,
        \end{aligned}
\end{equation*}
and then
     \begin{equation*}
        \begin{aligned}
            &  \sum_{(i,k)\in\Ixt^*}m_{i,k}\big(I_{\Delta x}[ \tilde v_{i,k+1}](x_i- \Delta t q_{i,k})+\Delta tL(x_i,q_{i,k})-I_{\Delta x}[\tilde v_{i,k+1}](x_i- \Delta t \tilde q_{i,k})-\Delta tL(x_i,\tilde q_{i,k}) \big)\\ 
        &+\sum_{(i,k)\in\Ixt^*}\tilde m_{i,k}\big(I_{\Delta x}[  v_{i,k+1}](x_i-  \Delta t \tilde q_{i,k})+\Delta tL(x_i,\tilde q_{i,k})-I_{\Delta x}[v_{i,k+1}](x_i- \Delta t q_{i,k})-\Delta tL(x_i,q_{i,k})\big)\\
            &= 0.
        \end{aligned}
\end{equation*}
Once again using the non-negativity of $m_{i,k},\tilde m _{i,k}\geq 0$ for any $(i,k)\in \Ixt^*$, together with  \eqref{minproperty}, it follows that, for any $(i,k)\in \Ixt ^*$,
\begin{equation*}
    m_{i,k}\big( I_{\Delta x}[ \tilde v_{i,k+1}](x_i- \Delta t q_{i,k})+\Delta tL(x_i,q_{i,k})-I_{\Delta x}[\tilde v_{i,k+1}](x_i- \Delta t \tilde q_{i,k})-\Delta tL(x_i,\tilde q_{i,k}) \big)= 0 
\end{equation*}
and 
\begin{equation*}
   \tilde  m_{i,k}\big(I_{\Delta x}[  v_{i,k+1}](x_i-  \Delta t  \tilde q_{i,k})+\Delta tL(x_i,\tilde q_{i,k})-I_{\Delta x}[v_{i,k+1}](x_i- \Delta t q_{i,k})-\Delta tL(x_i,q_{i,k})\big) = 0. 
\end{equation*}
For $k=0$, we have $m_{i,0}=\tilde m_{i,0}$ for any $i\in \Ix$. Let $i\in\Ix$ be such that $m_{i,0}=\tilde m_{i,0}>0$. Therefore, we have that
    \begin{equation*}
  I_{\Delta x}[ \tilde v_{i,1}](x_i- \Delta tq_{i,0})+\Delta tL(x_i,q_{i,0})-I_{\Delta x}[\tilde v_{i,1}](x_i-\Delta t \tilde q_{i,0})-\Delta tL(x_i,\tilde q_{i,0})  = 0
\end{equation*}
implies, due to \ref{uniquecontrol}, that $q_{i,0}=\tilde q_{i,0}$ for all such  $i\in \Ix$. By definition of the scheme \eqref{eq:MFGsdiscr2},  this yields  $m_{1}=\tilde m_1$. Iterating over $k \in \It^*$, we conclude that  $m=\tilde m$ , and consequently $v=\tilde v$. 
\end{proof}
From \cref{rem equivalent schemes}, \cref{existenceMFGsd1}, and \cref{uniquenessMFGsd2} the following result holds true:
\begin{cor}\label{existence and uniqueness MFGsd2}
    Let us assume \onlyref{continuity,initialdensity,ass:lagrangian}  and   $(\Delta x,\Delta t)>0$ such that \cref{uniquecontrol,DiscreteMonotonicity,condition dxdt for compact support discrete solution} hold. Then there exists a unique  solution to \eqref{eq:MFGsdiscr2}.  
    \end{cor}
From \cref{rem equivalent schemes},  \cref{existence and uniqueness MFGsd2} and \cref{convergenceschemeMFGsD1}, a convergence result for \eqref{eq:MFGsdiscr2} holds: 
\begin{cor}\label{convergenceschemeMFGsD2}
Let us assume \onlyref{continuity,C2bounded,initialdensity,ass:lagrangian}.  Consider a sequence  $\Delta_n=(\Delta x_n,\Delta t_n)>0$  such that $(\Delta x_n,\Delta t_n)\to 0$ and $\frac{\Delta x_n}{\Delta t_n}\to 0$ as $n\to \infty$, and suppose \onlyref{DiscreteMonotonicity,condition dxdt for compact support discrete solution,uniquecontrol} hold for any $(\Delta x_n, \Delta t_n)$.  Let $(m^n,v^n)$  be the unique solution to \eqref{eq:MFGsdiscr2} for the corresponding grid parameters $(\Delta x_n,\Delta t_n)$. Let $m_{\Delta_n}:=M_{\Delta_n}[m^n]$ and $v_{\Delta_n}:=V_{\Delta_n}[v^n]$.
Then there  exists  a weak solution $(m^*,v^*)$ to  the MFGs system, with $m^*$ absolutely continuous, such that, u.t.s.,  subsequence, $m_{\Delta_n}(t)\to m^*(t)$ in $\P_1(\RR^d)\cap L^1(\RR^d)$ for any $t\in [0,T]$ and $v_{\Delta_n}\rightharpoonup^* v^*$ in $L^\infty(Q_T)$. 
\end{cor}

\section{Discrete Learning Value Iteration and Policy Iteration algorithms for \eqref{eq:MFGsdiscr2}}\label{sec:algo}

The  non-linear backward-forward structure of \eqref{eq:MFGsdiscr2} requires an effective procedure for the approximation of its solution.
We consider a Learning Value Iteration algorithm, we study its convergence, and propose an accelerated version based on a Policy Iteration procedure.

\subsection{Discrete Learning Value Iteration algorithm  (DLVI)}\label{sec: DLVI}
Under \ref{uniquecontrol}, we define a discrete Learning Value Iteration algorithm (\textbf{DLVI}) for \eqref{eq:MFGsdiscr2} inspired by the fictitious play procedure introduced in \cite{CardaliaguetHadikhanloo} for a continuous first and second order MFGs problem and in \cite{HadikhanlooSilva} for a discrete problem. 

Given  $\ov{m}^{(1)}\in \S(\GG_{\Delta})$, we iterate over  $n\geq 1$:
\begin{myenum}
\item Compute $v^{(n)}$ 
\begin{equation*}
            \begin{aligned}
               &v^{(n)}_{i,k}=\min_{a\in \ov{B}_{\infty}(0,C_H)}\left\{I_{\Delta x}[v^{(n)}_k](x_{i}-\Delta t a)+\Delta tL(x_i,a)\right\}+\Delta t  f(x_i,\ov m^{(n)}_k) \, \textrm{for any } (i,k)\in \Ixt^*,\\
               &v^{(n)}_{i,N_T}=g(x_i,\ov m^{(n)}_{N_T}) \quad\quad \textrm{for any } i\in \Ix.  
            \end{aligned}
\end{equation*}
\item Define $q^{(n)}$  
\begin{equation*}
    q^{(n)}_{i,k}\in \amin_{a\in \ov{B}_{\infty}(0,C_H)}\left\{I_{\Delta x}[v^{(n)}_{k+1}](x_{i}-\Delta t a)+\Delta tL(x_i,a)\right\}\qquad \textrm{for any }(i,k)\in \Ixt^*.
\end{equation*}
\item  Compute $m^{(n+1)}$ 
\begin{equation*}
            \begin{aligned}
               &m^{(n+1)}_{i,k+1}=\sum_{j\in \Ix}\beta_{i}(x_j-\Delta t q^{(n)}_{j,k})m^{(n+1)}_{j,k}  &&\textrm{for any } (i,k)\in \Ixt^*, \\
               &m^{(n+1)}_{i,0}=\int_{E_{i}} \dd [m^*_{0}](x) &&  \textrm{for any }i\in \Ix.
            \end{aligned}
\end{equation*}
\item Update  $\ov m^{(n+1)}$ 
\begin{equation*}
    \ov{m}^{(n+1)}_{i,k}=\left(1-\frac{1}{n+1}\right)\ov{m}^{(n)}_{i,k}+\frac{1}{n+1}m^{(n+1)}_{i,k} \qquad \textrm{for any }(i,k)\in \Ixt.
\end{equation*}
\end{myenum}
We consider the following stop criterion: given a tolerance $tol>0$,
\textbf{DLVI}  stops at  $n>1$ if  
    \begin{equation}\label{L1stopDLVI}
       E_{1}(m^{(n+1)},m^{(n)}) <tol \qquad  \text{and}\qquad E_{\infty}(v^{(n)},v^{(n-1)}) <tol.
\end{equation}
and the solution returned by  the algorithm is  $(m^{(n+1)},v^{(n)})$. The above errors
 are defined as 
\begin{equation*}
     E_{1}(m,\tilde m):=\text{Int}_{ \GG_{\Delta x}}|m_{N_T}-\tilde m_{N_T}| \qquad  \text{and}\qquad    E_{\infty}(v,\tilde v):=\max_{i\in\Ix}|v_{i,0}-\tilde v_{i,0}|,  
\end{equation*}
 for any  $m,\tilde m\in \S(\GG_{\Delta})$ and $v,\tilde v \in \BB(\GG_{\Delta})$, where \text{Int}$_{ \GG_{\Delta x}}$ denotes the approximation of the integral on $ \GG_{\Delta x}$ by using the rectangle Rule.

\subsubsection{Probabilistic notation}\label{sec: probabilistic notation}
To streamline the proof of \textbf{DLVI} convergence, we  slightly modify the notation, in order to apply the convergence result given in \cite{HadikhanlooSilva}. We  introduce a collection of definitions and give a probabilistic interpretation of \eqref{eq:MFGsdiscr2}.
Let $\S(\GG_{\Delta x})$ be the set of probability measure over $\Ix$, defined in  \cref{A_fully_discrete_scheme_for_the_continuity_equation}. 
   For any fixed  $j \in\Ix$ and $a \in \RR^d $, we define the map $p^j[a]:\Ix \to \RR $ by
\begin{equation*}
    p^j[a](i)\coloneqq \beta_i(x_j-\Delta t a) \qquad \text{ for any } i \in\Ix.
\end{equation*} 
    For any fixed  $q \in  \BB( \GG_{\Delta}^*;\RR^d)$, we define the map $P[q]:\Ix\times\Ixt^* \to \RR $ by
\begin{equation*}
    P[q](j,i,k)\coloneqq p^j[q_{j,k}](i) \qquad \text{ for any } j,i \in\Ix, k \in  \It^*.
\end{equation*} 
For any fixed  $i\in \Ix$, we define the map $c_{i}:\RR^d\times  \S(\GG_{\Delta})\to \RR$ by
\begin{equation}\label{runningcost}
    c_{i}(a,m)\coloneqq\Delta tL(x_i,a)+ \Delta tf(x_i,m).
\end{equation}
The scheme \eqref{eq:MFGsdiscr2} written with this new notation becomes: find $(m,v) \in \S(\GG_{\Delta})\times \BB(\GG_{\Delta})$ such that
\begin{equation}\label{eq:MFGsdiscrProb}
            \begin{aligned}
               &v_{i,k}=\sum_{j\in\Ix}P[\Tilde q](i,j,k)\big(v_{j,k+1}+c_{i}(\Tilde q_{i,k},m_k) \big) &&\text{for any   }(i,k)\in \Ixt^*, \\
                 &m_{i,k+1}=\sum_{j\in \Ix}P[\Tilde q](j,i,k)m_{j,k}  &&\text{for any   } (i,k)\in \Ixt ^*,\\
               &v_{i,N_T}=g(x_i, m_{N_T}), \qquad m_{i,0}=\int_{E_{i}} \dd [m^*_{0}](x)&&  \text{for any  }i\in \Ix, \\  
            \end{aligned}
\end{equation}
where  $\Tilde q \in  \BB( \GG_{\Delta}^*;\RR^d)$ is such that
\begin{equation}\label{eq:oprimalcontrol}
       \Tilde q_{i,k}= \amin_{a\in \ov{B}_{\infty}(0,C_H)}\left\{\sum_{j\in\Ix}p^i[a](j)\big(v_{j,k+1}+c_{i}(a,m_k)\big)\right\}\qquad \text{for any   }(i,k)\in \Ixt ^*.
\end{equation}
We observe that \eqref{eq:oprimalcontrol} does not depend on $m_k$.
\textbf{DLVI}, with this probabilistic notation, computes the sequences of marginal distributions $m^{(n)}\in\S_{\Delta }$ and value functions $v^{(n)}\in \BB( \GG_{\Delta})$ as follows. Given  $\ov{m}^{(1)}\in  \S(\GG_{\Delta})$, we iterate on  $n\geq 1$:
\begin{myenum}
\item Compute $v^{(n)}$ 
\begin{equation*}
            \begin{aligned}
               &v^{(n)}_{i,k}=\inf_{a\in \ov{B}_{\infty}(0,C_H)}\left\{\sum_{j\in\Ix}p^i[a](j)\big(v^{(n)}_{j,k+1}+c_{i}(a,\ov m^{(n)}_k)\big)\right\} &&\text{for any   }(i,k) \in \Ixt^*, \\
               &v^{(n)}_{i,N_T}=g(x_i, \ov m^{(n)}_{N_T}) &&  \text{for any  }i\in \Ix.  
            \end{aligned}
\end{equation*}


\item  Define $q^{(n)}$  
\begin{equation}\label{optimalcontrolDLVI}
    q^{(n)}_{i,k}\in  \amin_{a\in \ov{B}_{\infty}(0,C_H)}\left\{\sum_{j\in\Ix}p^i[a](j)\big(v^{(n)}_{j,k+1}+c_{i}(a,\ov m^{(n)}_k)\big)\right\}\qquad \text{for any   }(i,k)\in \Ixt ^*.
\end{equation}


\item   Compute $m^{(n+1)}$ 
\begin{equation*}
            \begin{aligned}
               &m^{(n+1)}_{i,k+1}=\sum_{j\in \Ix}P[q^{(n)}](j,i,k)m^{(n+1)}_{j,k}  &&\text{for any   }i\in \Ixt^*, \\
               &m^{(n+1)}_{i,0}=\int_{E_{i}} \dd [m^*_{0}](x) &&  \text{for any  }i\in \Ix.\\  
            \end{aligned}
\end{equation*}
\item  Update $\ov m^{(n+1)}$ 
\begin{equation*}
    \ov{m}^{(n+1)}_{i,k}=\left(1-\frac{1}{n+1}\right)\ov{m}^{(n)}_{i,k}+\frac{1}{n+1}m^{(n+1)}_{i,k} \qquad \text{for any } (i,k)\in \Ixt.
\end{equation*}
\end{myenum}
\subsubsection{Probabilistic interpretation of $(\text{MFGs}_d^2)$}
Given $q \in  \BB( \GG_{\Delta}^*;\RR^d)$ and $m_0^*\in \P_1(\RR^d)$, the pair $(m^*_0,P[q])$ induces a probability distribution over $\S(\GG_{\Delta})$ with marginal distribution given by 
\begin{equation*}\label{eq:definition_M_Q_recursive}
\begin{aligned}
m^{m^*_0}_{i,0}[q]&\coloneqq \int_{E_{i}} \dd [m^*_{0}](x) &&\text{for any } i\in \Ix.\\
m^{m^*_0}_{i,k+1}[q]&\coloneqq \sum_{j \in \Ix}P[q](j,i,k)m^{m^*_0}_{j,k}[q]  && \text{for any } (i,k)\in \Ixt^*.
\end{aligned}
\end{equation*}
Given $m\in \S(\GG_{\Delta})$, we define   $J_m :  \BB( \GG_{\Delta}^*;\RR^d)\to \RR$ by 
\begin{align*}
J_m(q)&\coloneqq \sum_{k=0}^{N_T-1} \sum_{j,i \in \Ix} m^{m^*_0}_{j,k}[q]P[q](j,i, k) c_{j} ( q_{j,k} , m_k) + \sum_{j\in \Ix} m^{m^*_0}_{j,N_T}[q]  g(j , m_{N_T}),  \\ 
&=\sum_{k=0}^{N_T-1} \sum_{j \in \Ix}m^{m^*_0}_{j,k}[q] c_{j} ( q_{j,k} , m_k) + \sum_{j\in \Ix} m^{m^*_0}_{j,N_T}[q]   g(j ,m_{N_T}).
\end{align*}
We consider the following  problem: find $\Tilde q  \in  \BB( \GG_{\Delta}^*;\RR^d)$ such that 
\begin{equation}\label{eq:MFGsdiscrJ}
   \Tilde  q \in \amin_{ \substack{q \in   \BB( \GG_{\Delta}^*;\RR^d)\\ ||q||_{L^\infty(\GG_{\Delta}^*)} \leq C_H}}J_m(q) \qquad \text{ with } \quad m=m^{m^*_0}[\Tilde  q].
\end{equation}
\begin{rem}
    Note that if $(v,m)$ is the solution to \eqref{eq:MFGsdiscrProb}, then $\Tilde q$ satisfying \eqref{eq:oprimalcontrol} solves \eqref{eq:MFGsdiscrJ}.
\end{rem}
\begin{rem}
    If $q^{(n)}$ solves \eqref{optimalcontrolDLVI}, then 
    \begin{equation*}
          q^{(n)} \in \amin_{ \substack{q \in   \BB( \GG_{\Delta}^*;\RR^d)\\ ||q||_{L^\infty(\GG^*_{\Delta})} \leq C_H}}J_{\ov m^{(n)}}(q).
    \end{equation*}
\end{rem}



\subsubsection{Convergence Analysis of DLVI}\label{Convergence Analysis of DLVI}
We show that the sequence $(m^{(n)},v^{(n)})$ generated  by \textbf{DLVI} converges to  the solution to \eqref{eq:MFGsdiscr2} (or, equivalently, \eqref{eq:MFGsdiscrProb}).
   To this end, we  recall  an abstract result established in \cite[Theorem 3.1]{HadikhanlooSilva}, that will allow us to prove the convergence of \textbf{DLVI}. 
Let $\mathcal{X}$ and $\mathcal{Y}$  be two Polish spaces and $\mathcal{Z} \subseteq \mathcal{X}$ be a compact set.
Let  $\mathcal{P}(\mathcal{Z})$  the set of probability measures on $\mathcal{Z}$. The set $\mathcal{P}(\mathcal{Z})$ is compact. Let $\mathcal{F}:\mathcal{Z} \times \mathcal{P}(\mathcal{Z}) \to \RR$ be a given continuous function. Given $x_1\in \mathcal{Z}$, set $\ov{\eta}_1:= \delta_{x_1}$ and for any $n\geq 1$ define
\begin{equation}\label{GenFP}
x_{n+1} \in \amin_{x \in \mathcal{Z}} \mathcal{F}(x,\ov \eta_n), \qquad \ov \eta_{n+1} = \frac{1}{n+1} \sum_{k=1}^{n+1} \delta_{x_{k}} = \frac{n}{n+1} \ov \eta_n + \frac{1}{n+1}\delta_{x_{n+1}}.
\end{equation}
We consider the convergence problem of  the sequence $(\ov \eta_{n})$  to some $\tilde{\eta}\in \mathcal{P}(\mathcal{Z})$ satisfying that
\begin{equation}\label{eq:convergentProblem}
\mbox{supp}(\tilde{\eta}) \subseteq \amin_{x\in \mathcal{Z}}\mathcal{F}(x,\tilde{\eta}).
\end{equation}
\begin{theo}\label{Generalisedfictitiousplay}\cite[Theorem 3.1]{HadikhanlooSilva}
Consider the sequence $(x_n,\ov{\eta}_n)$ defined by \eqref{GenFP} and assume:
\begin{itemize}
\item[{\rm(i)}]$\mathcal{F}$ is monotone, i.e. 
 \begin{equation}\label{monotonocityF}
    \int_{\mathcal{Z}}\Big(\mathcal{F}(x,\eta)-\mathcal{F}(x,\eta')\Big) \dd [\eta-\eta'](
x)\geq 0    \qquad \text{for any } \eta,\eta'\in \mathcal{P} (\mathcal{Z}).
\end{equation}
\item[{\rm(ii)}] $\mathcal{F}$ is Lipschitz, when  $ \mathcal{Z}$ is endowed with the distance $d$  and $\mathcal{P} (\mathcal{Z})$ is endowed with the distance $d_1$, and there exists $C>0$ such that 
\begin{equation*}
| \mathcal{F}(x , \eta) - \mathcal{F}(x , \eta') - \mathcal{F}(x' , \eta) + \mathcal{F}(x' , \eta') | \leq C   d(x,x')   d_1 (\eta,\eta'),
\end{equation*}
for any $x$, $x' \in \mathcal{Z}$, and  $\eta$, $\eta' \in \mathcal{P} (\mathcal{Z})$
\item[{\rm(iii)}] d$(x_{n+1},x_{n})\to 0$ as $n\to \infty$.
\end{itemize}
Then, every limit point $\Tilde{\eta}$ of $\ov{\eta}_n$(there exists at least one) solves \eqref{eq:convergentProblem}.
\end{theo}
In order to apply \cref{Generalisedfictitiousplay}, 
we define $\mathcal{Z}\coloneqq \{q :  \GG_{\Delta}^*\to \RR^d, ||q||_{L^\infty(\GG_{\Delta}^*)} \leq C_H\}$. Given $\eta \in  \mathcal{P} ( \mathcal{Z})$, we define $M^\eta\in   \S(\GG_{\Delta})$ and $\mathcal{F}:\mathcal{Z}\times \mathcal{P} ( \mathcal{Z}) \to \RR $ by
\begin{equation}\label{GenFormofCostFunction}
    M^{\eta}_k \coloneqq \int_{\mathcal{Z}} m^{m^*_0}_k[q]  \dd [\eta](q),  \,\,\, \text{for any }  k\in \mathcal{I}_{\Delta t},\quad \text{and}  \quad  \mathcal{F}(q,\eta)  \coloneqq  J_{M^\eta}(q).
\end{equation}
We define the fictitious play procedure: given $q^{(1)}\in \mathcal{Z}$ and $\eta \in  \mathcal{P} ( \mathcal{Z})$ such that $\ov{\eta}^{(1)}=\delta_{q^{(1)}}$, for $n\geq 1$, define 
\begin{equation}\label{ficitiousplayF}
q^{(n+1)} \in \amin_{q\in  \mathcal{Z}} \mathcal{F}(q,\ov \eta_n), \qquad \ov \eta_{n+1} = \frac{1}{n+1} \sum_{k=1}^{n+1} \delta_{q^{(k)}} = \frac{n}{n+1} \ov \eta_n + \frac{1}{n+1}\delta_{q^{(n+1)}}.
\end{equation}
\begin{rem}
    Notice that $M^{\ov{\eta}_n}=\ov{m}^{(n)}$.
\end{rem}

\subsubsection{Verification of the assumptions of \cref{Generalisedfictitiousplay}}
Let us consider the following assumption: 
\begin{Hassum}[resume]
    \item  \label{lipschitz in m}$F,G\colon\RR^d\times \P_1(\RR^d) \to \RR $ are Lipschitz continuous with respect to
their second argument.
\end{Hassum}


Similarly to the proof of \cite[Lemma 3.2, Lemma 3.3, Lemma 3.4]{HadikhanlooSilva}, we can verify that, under \onlyref{continuity,lipschitz in m,C2bounded,ass:lagrangian,DiscreteMonotonicity,uniquecontrol,initialdensity,condition dxdt for compact support discrete solution}, the problem \eqref{ficitiousplayF} satisfies the assumptions of \cref{Generalisedfictitiousplay}. By applying \cref{Generalisedfictitiousplay} to \eqref{ficitiousplayF}, the following convergence result for \textbf{DLVI} holds true. The proof employs the same technique as in the proof of \cite[Theorem 3.2]{HadikhanlooSilva}.
\begin{theo}\label{thm:convercenceDLVI}
    Let us assume \onlyref{continuity,C2bounded,lipschitz in m,ass:lagrangian,DiscreteMonotonicity,uniquecontrol,initialdensity,condition dxdt for compact support discrete solution}. Let $(q^{(n)},v^{(n)},m^{(n)}, \ov m^{(n)})$ be the sequences defined by {\rm \textbf{DLVI}}. Then $(q^{(n)},v^{(n)},m^{(n)}, \ov m^{(n)})\to ( q,v,m, m)$, where $(m,v)$ is the unique solution  to \eqref{eq:MFGsdiscr2} and $q$ the unique element in $\Lambda_{\Delta}[v]$, for any initial guess $\ov m^{(1)}\in \S(\GG_{\Delta})$.
\end{theo}

\subsection{Discrete Policy Iteration algorithm (DPI)}\label{DPI}
We consider a discrete Policy Iteration algorithm \textbf{(DPI)} to approximate \eqref{eq:MFGsdiscr2}. The algorithm is inspired by policy iteration procedure introduced in \cite{CacaceCamilliGoffi} for a continuous second order MFGs problem. In \textbf{DPI} the HJB equation is replaced by a linearized transport equation that we  discretize using  a classic SL scheme (see \cite{FalconeFerretti}).
 Let $\rho\in \mathcal{C}_{c}^{\infty}(\RR^d)$ be such that $\rho \geq 0 $ and $\int_{\RR^d} \rho(x)\text{d}x=1$. For $\epsilon>0$, we consider the mollifier $\rho_{\epsilon}(x)=\frac{1}{\epsilon^{d}}\rho(\frac{x}{\epsilon})$.

Given  ${q}^{(1)}\in \BB( \GG_{\Delta}^*;\RR^d)$, we iterate over  $n\geq 0$:
\begin{myenum}
    \item  Compute $m^{(n)}$
\begin{equation*} 
            \begin{aligned}
               m^{(n)}_{i,k+1}&=\sum_{j\in \Ix}\beta_{i}(x_j-\Delta t{q}^{(n)}_{j,k})m^{(n)}_{j,k}  &&\text{for any  }(i,k)\in \Ixt^*, \\
               m^{(n)}_{i,0}&=\int_{E_{i}}\text{d}[m^*_{0}](x) &&  \text{for any  }i\in \Ix.  
            \end{aligned}
\end{equation*}
\item Compute $v^{(n)}$ 
\begin{equation*}
            \begin{aligned}
               v^{(n)}_{i,k}&= I[v^{(n)}_{k+1}](x_{i}-q^{(n)}_{i,k}\Delta t)+\Delta tL(x_i,q^{(n)}_{i,k})  +\Delta t  f(x_i,m^{(n)}_k) &&\text{for any   }(i,k)\in \Ixt^*, \\
               v^{(n)}_{i,N_T}&=g(x_i,m^{(n)}_{N_T}) &&  \text{for any  }i\in \Ix.   
            \end{aligned}
\end{equation*}
\item Define $D_x v^{(n)}_{\Delta,\epsilon}(\cdot,t):=D_x \rho_{\epsilon}* V_{\Delta}[v^{(n)}](\cdot,t)$, for  $t\in[0,T]$ and set 

\begin{equation*}
     q^{(n+1)}_{i,k}= D_pH(x_i,D_x v^{(n)}_{\Delta,\epsilon}(x_i,t_k)) \qquad \text{for  any } (i,k)\in \Ixt^*.
\end{equation*}
\end{myenum}
We consider the following stop criterion: given a tolerance $tol>0$,
\textbf{DLVI}  stops at  $n>1$ if  
    \begin{equation}\label{L1stopDPI}
       E_{1}(m^{(n)},m^{(n-1)}) <tol \qquad  \text{and}\qquad E_{\infty}(v^{(n)},v^{(n-1)}) <tol.
\end{equation}
and the solution returned by  the algorithm is  $(m^{(n)},v^{(n)})$.
\begin{rem}\label{rem: advantage of DPI}
In the third step of \textbf{DPI}, in order to have a well defined gradient, the convolution with the mollifier is introduced as in  \cite{CarliniSilva2014}. 
The advantage of using the gradient directly for the policy update, rather than solving a minimization problem, is that it eliminates the minimization step, thereby speeding up the algorithm.
\end{rem}


\subsection{Accelerated Discrete Learning Value Iteration Algorithm (ADLVI)}\label{ADLVI} 
We present an accelerated iterative algorithm \textbf{ADLVI} for \eqref{eq:MFGsdiscr2}, which is constructed by coupling \textbf{DLVI} and \textbf{DPI}, and switching from a coarse grid to a fine grid. More specifically, the algorithm consists in implementing \textbf{DLVI} on a fine grid using as initial guess the distribution computed by the \textbf{DPI} implemented on a coarse grid. For this accelerated algorithm we need to have 
$(\Delta x_c,\Delta t _c,tol_c,\epsilon_c)>0$ for the first part of \textbf{ADLVI}, and $(\Delta x_f,\Delta t_f,tol_f)>0$ such that $\Delta x_f\geq \Delta x_c$ and $\Delta t_f\geq \Delta t_c$ for the last one. We set $\Delta_c:=(\Delta x_c,\Delta t _c)$ and $\Delta_f:=(\Delta x_f,\Delta t _f)$.
\textbf{ADLVI} is made up of these following three steps: 
\begin{myenum}
    \item Given an initial guess ${q}^{(1)}\in \mathcal{B}( \GG_{\Delta_c};\RR^d)$ and $\epsilon_c$, we iterate for  $n\geq 0$ using \textbf{DPI}  on the coarse mesh $\mathcal{G}_{\Delta_c}$, until the stop citerion in \eqref{L1stopDPI}, with tolerance $tol_c$, is satisfied at iteration $n_c$, returning the approximate solutions $(m^{(n_c)},v^{(n_c)},q^{(n_c+1)})$. 
   \item Define $\ov m^{(1)}\in \S(\GG_{\Delta_f})$ as  
   \begin{equation}\label{step 2 ADVI}
   \ov{m}^{(1)}=I_1[m^{(n_c)}] 
   \end{equation}
   where $I_1:\S(\GG_{\Delta_c})\to \S(\GG_{\Delta_f})$
is a  interpolation operator.
\item Given the initial guess $\ov 
m ^{(1)}\in \S(\GG_{\Delta_f})$ defined in \eqref{step 2 ADVI}, we iterate for   $n\geq 1$ using \textbf{DLVI} on the fine mesh $\GG_{\Delta_f}$, until the stop criterion in \eqref{L1stopDLVI},  with tolerance $tol_f$, is satisfied  at iteration $n_f$. 
\end{myenum}
The approximated solution given by \textbf{ADLVI} is $(m^{(n_f+1)},v^{(n_f)})$.


The goal of developing \textbf{ADLVI} is to exploit the low computational cost of \textbf{DPI} (see \Cref{rem: advantage of DPI}) to construct an initial guess 
$\ov m ^{(1)}$  for the convergent algorithm \textbf{DLVI} (see \cref{thm:convercenceDLVI}), so that it requires fewer iterations than it would with a random initialization. Numerically, we will observe that, for a fixed grid refinement, \textbf{DLVI} requires more iterations to converge than \textbf{ADLVI}, making \textbf{ADLVI} computationally more efficient.



\section{Numerical tests}\label{sec:tests}
We show the performance of the proposed algorithms
by approximating the solution to three different MFGs systems. In the first problem, the exact solution is known and it allows us to study the accuracy of \textbf{DLVI}. In this case, we focus on the one-dimensional setting.  
In the second and third problem, which are one and  two-dimensional respectively, we compare the performance of \textbf{DLVI} and \textbf{ADLVI}.
We denote by $(m^L,v^L)$ and $(m^{ACC},v^{ACC})$ the solutions computed by the two methods.
Given $(\Delta x,\Delta t, tol)>0$,
we implement \textbf{ADLVI} with  $\Delta x_f=\Delta x$,  $\Delta t_f=\Delta t$, $tol_f=tol_c=tol$, $\Delta x_c=2\Delta x$,  $\Delta t_c=2\Delta t$,  $\epsilon_c=3\sqrt{\Delta t_c}$ and we choose $\rho(x)=\frac{1}{(2\pi)^{(d/2)}}e^{-|x|^2/2}$ as mollifier in the convolution. 
We initialize the iterations of \textbf{DLVI} with $\overline m^{(1)}_{i,k}=\int_{E_i}\dd [m_0^*](x)$ for any $(i,k)\in \Ixt$, and the iterations of \textbf{ADLVI} with $q^{(1)}_{i,k}=0$ for any $(i,k)\in \mathcal{I}^*_{\Delta _c}$.
In all the proposed tests, we choose  $\Delta t=\Delta x^{2/3}/2$, $tol=1E-3$, and we test the algorithms for different choices of $\Delta x$.  Finally, the numerical simulations have been carried
out in MATLAB R2022a on a computer with processor AMD Ryzen 5 5600H with Radeon Graphics 3.30 GHz.




 \subsection{Example with analytical solution}\label{test1}
 We consider the MFGs system with quadratic Hamiltonian $H(x,p)=|p|^2/2$, coupling terms 
\begin{equation*}
    F(x,\nu)=\frac{1}{2}\left(x-\int_{\RR^d}y\dd[\nu](y) \right)^{2}, \quad G(x,\nu)=0,
\end{equation*}
and  initial measure $m^*_0$ given as  the density of a Gaussian random vector with mean $\mu^*_0\in\RR^d$ and covariance matrix $\Sigma_0\in\ \RR^{d\times d}$, assumed, for simplicity,
to be diagonal. 
This problem does not satisfy \ref{C2bounded} and \ref{initialdensity}, however, it admits a unique explicit solution $(m^*,v^*)$ (see \cite{CalzolaCarliniSilva2024}) that allows us to study the numerical convergence rates of \textbf{DLVI}.


In the following simulations, we consider this example set in the domain $[-2,2]^d\times[0,T]$,  and we choose $d=1$, $T=0.25$, $\mu_0=0.1$ and $\Sigma _{0}=0.105$. We test \textbf{DLVI} for several refinements of the space-time grid. In \Cref{table: test with analytical solution}, we display the space grid step $\Delta x$ (column 1), the error of the density $E_1(m^L,\hat m^*)$ (column 2), the error of the value function $E_\infty(v^L,\hat v^*)$ (column 3) and the number of iterations $n$ (column 4).  

Columns 2–3  show that \textbf{DLVI} improves accuracy as $\Delta x$ decreases, with a numerical convergence rate of approximately order one with respect to both errors.
In addition, column 4 reveals that \textbf{DLVI} verifies the stopping criterion in just two iterations.  Consequently, there is no motivation to apply \textbf{ADLVI} in this simple example to further reduce the iteration count.
