\begin{proof}[Proof of \cref{Adelta properties}] 
Let $w=(m,v),\tilde w=(\tilde m,\tilde v),q,\tilde q, \mu ,\tilde \mu$ be as in the statement. Since $m$ and $\tilde m$ have compact support, there exists $\tilde C>0$ such that if $x_i\notin \ov B(0,\tilde C)$ then $m_{i,k}=\tilde m_{i,k}=0$ for any $k\in\It$. As a consequence, the sum over $i\in \Ix$ appearing in $ \langle  A_{\Delta }[\tilde w]-A_{\Delta }[ w], \tilde w-w \rangle_{\Delta }$, is effectively restricted to the finite set $ 
\{i\in\Ix | x_i\in  B(0,\tilde C+\sqrt{d}TC_H)\neq \emptyset \}$.
Combining this observation with \eqref{optimalrelaxedcontrolproperty}, we can write $ \langle  A_{\Delta }[\tilde w]-A_{\Delta }[ w], \tilde w-w \rangle_{\Delta }$ as follows 
\begin{equation*}
    \begin{aligned}
          \langle  A_{\Delta }[\tilde w]-A_{\Delta }[ w], \tilde w-w \rangle_{\Delta }&= \sum_{i\in \Ix} \big((\tilde v_{i,0}-v_{i,0})(m_{i,0}-\tilde m_{i,0}) +(v_{i,N_T}-\tilde v_{i,N_T})(m_{i,N_T}-\tilde m_{i,N_T}) \big)\\ 
         &+\Delta t\sum_{k\in\It^*}\sum_{i\in \Ix}\big(f(x_i,m_k)-f(x_i,\tilde m_k)\big)(m_{i,k}-\tilde m_{i,k})\\
        &+ \sum_{k\in \It^*} \sum_{i\in\Ix} \Big[
		   \int_{\RR^d}\Big(I_{\Delta x}[v_{k+1}](x_i - \Delta t a) + \Delta tL(x_i,a)\Big)\dd [\mu_{i,k}](a)\Big. \Big. \\
		& -\int_{\RR^d}\Big(I_{\Delta x}[\tilde{v}_{k+1}](x_i - \Delta t a) +  \Delta tL(x_i,a)\Big)\dd [\tilde \mu_{i,k}](a) \Big]  (m_{i,k} - \tilde{m}_{i,k})
		\\
		&+  \sum_{k\in \It^*} \sum_{i\in\Ix}\Big[  - \sum_{j\in\Ix}  m_{j,k}\int_{\RR^d}\beta_i(x_j-\Delta t a)\dd [\mu_{j,k}](a) \\ &  + \sum_{j\in\Ix} \tilde{m}_{j,k}\int_{\RR^d} \beta_i(x_j-\Delta t a)\dd[\tilde \mu_{j,k}](a)  \Big] (v_{i,k+1} - \tilde{v}_{i,k+1} ). \\
    \end{aligned}
\end{equation*}
Finally, \eqref{eq:equality Adelta} is proved by recalling  the definition of the interpolation operator \eqref{interpolation operator} and by observing that we can commute the summations, since they are finite. 
In addition,
using  \eqref{minproperty} and the fact that $m_{i,k},\tilde m _{i,k}\geq 0$ for any $(i,k)\in \Ixt$,  we obtain that 
 \begin{equation*}
        \begin{aligned}
           & \langle  A_\Delta[\tilde w]-A_\Delta[ w], \tilde w-w \rangle_{\Delta} \\
            &\geq  \sum_{i\in \Ix}\big((-v_{i,0}+\tilde v_{i,0})(m_{i,0}-\tilde m_{i,0}) +(v_{i,N_T}-\tilde v_{i,N_T})(m_{i,N_T}-\tilde m_{i,N_T}) \big)+\\
            &+\Delta t\sum_{k\in\It^*}\sum_{i\in \Ix}\big(f(x_i,m_k)-f(x_i,\tilde m_k)\big)(m_{i,k}-\tilde m_{i,k}).
        \end{aligned}
    \end{equation*}
If \cref{DiscreteMonotonicity} holds,  this  inequality implies \eqref{eq:  inequality Adelta discrmon}.



\end{proof}
\begin{lem}\label{Compact Lemma 2.4 CapuzzoDolcetta}
 Let  $\Omega\subset\RR^d$ be a compact space, $w\in\CC(\Omega)$ and suppose that $x^0$ is the strict minimum point of $w$ in $\Omega$. If  $w^n\in \CC(\Omega)$ converges  uniformly to $w$ in $\Omega$, then for any  $\{x^n\}$ such that
    \begin{equation*}
        w^n(x_n)\leq w^n(x) \quad \forall x \in   \Omega
        \end{equation*}
        (there exists at least one), the following holds true 
    \begin{equation*}
       \lim_{n\to \infty} x^{n}= x^0.
        \end{equation*}
\end{lem}
 \begin{lem}\label{Compact nostrict Lemma 2.4 CapuzzoDolcetta} 
      Let $\Omega\subset\RR^d$ be a compact space and $w\in \CC(\Omega)$. If $w_n\in \CC(\Omega)$ converges  uniformly to $w$ in $\Omega$, then for any sequence  $\{x_n\}_n$ such that
    \begin{equation*}
        w_n(x_n)\leq w_n(x) \quad \forall x \in   \Omega
        \end{equation*}
    (at least one exists) and, for any convergent subsequences $\{x_{n_k}\}_k$ (at least one exists), there exists a point $\tilde x \in \Omega$ such that
    \begin{equation*}
       \lim_{k\to \infty} x_{n_k}=\tilde x, \quad and  \quad w(\tilde x)\leq w(x) \quad \text{for any } x \in \Omega.
        \end{equation*}
\end{lem}
\cref{Compact Lemma 2.4 CapuzzoDolcetta} and \cref{Compact nostrict Lemma 2.4 CapuzzoDolcetta} are proved as \cite[Lemma 2.4]{BardiDolcetta}.


