               \State {\bf Input:} Graph $\mathcal{G} = (\mathcal{V}, \mathcal{E})$, feature matrix $\mathbf{X}$, learning rate $\eta_\xi$, perturbation bound $\epsilon$, ascent steps $T$, step size $\alpha$, decay rate $\beta$.
               \State {\bf Initialize:} Teacher parameters $\xi$; EMA $\theta \gets \xi$.
               \For{each training epoch}
               \State Given two views $\hat{\mathcal{G}}_1, \hat{\mathcal{G}}_2$ via \cref{alg1:laplace_augmentations}:
               \State {\bf Forward Pass (Teacher Encoder with MLP Projector):}
               \State $\hat{\mathbf{T}} = \text{MLP}_{\xi}(q_\xi(g_\xi(\hat{\mathcal{G}}_1, \mathbf{X})))$
               \State {\bf Forward Pass (Student Encoder):}
               \State $\hat{\mathbf{Z}} = p_\theta(f_\theta(\hat{\mathcal{G}}_2, \mathbf{X}))$
               \State {\bf Compute the bootstrapped loss:}
               \[
               \mathcal{L}_{\text{boot}} = -\frac{2}{N} \sum_{i=0}^{N-1} \frac{\hat{\mathbf{T}}^{(i)} \hat{\mathbf{Z}}^{(i)\top}}{\|\hat{\mathbf{T}}^{(i)}\| \|\hat{\mathbf{Z}}^{(i)}\|}
               \]
               \State {\bf Adversarial Training for Teacher Model:}
               \State Initialize perturbation $\boldsymbol{\delta}_0 \sim \mathcal{U}(-\epsilon, \epsilon)$.
               \State $\mathbf{H} = g_\xi(\hat{\mathcal{G}_1}, \mathbf{X})$ (hidden features of the teacher encoder)
               \For{$t = 1, \ldots, N_\text{epoch}/T$}
               \State Compute: $\mathbf{g}_{t} \gets \mathbf{g}_{t-1} +\frac{1}{T}\nabla_\xi \mathcal{L}_{\text{boot}}(\hat{\mathcal{G}}_1, \mathbf{H} + \boldsymbol{\delta}_{t-1})$
               \State Compute gradient: $\mathbf{g}_{\delta} = \nabla_{\boldsymbol{\delta}} \mathcal{L}_{\text{boot}}(\hat{\mathcal{G}}_1, \mathbf{H} + \boldsymbol{\delta}_{t-1})$
               \State Update perturbation:
               \[
               \boldsymbol{\delta}_t = \text{Proj}_{\epsilon} \left(\boldsymbol{\delta}_{t-1} + \alpha \frac{\mathbf{g}_{\delta}}{\|\mathbf{g}_{\delta}\|_F}\right)
               \]
               \EndFor
               \State {\bf Update Parameters:}
               \State Teacher Update: $\xi \gets \xi - \eta_\xi\mathbf{g}_T$
               \State EMA Update: $\theta \gets \beta \theta + (1 - \beta) \xi$
               \EndFor
            \end{algorithmic}
        \end{algorithm}
