\textbf{Chaotic Keystream Generation (CKG).}%
\label{subsec:ckg-description}
%
The CKG module initializes the two–dimensional Lorenz–inspired recurrent neural map (MHDNN) with the secret key~$K$, discards its transient behaviour, and continuously samples the orbit to build a high-entropy chaotic sequence.  
Through deterministic scaling and modular operations, this sequence is transformed into three pixel–permutation vectors $(X,\,X_1,\,X_2)$ and a diffusion keystream $SBT$, which jointly serve as the cryptographic key material for subsequent stages.  
The complete procedure is presented in Algorithm~\Cref{Algorithm:1}.


\begin{algorithm}[H]
\caption{Chaotic Keystream Generation (CKG)}
\label{Algorithm:1}
\begin{algorithmic}[1]           % [1] 开启行号
  \Require Secret key $K$; image size $M\times N$
  \Ensure  Permutation sequences $X,X_1,X_2$ and diffusion keystream $SBT$
  \State Initialize the MHDNN system with key $K$
  \For{$i \gets 1$ \textbf{to} $1000$}
        \State Iterate MHDNN once and discard the output                 \Comment{remove transient}
  \EndFor
  \For{$i \gets 1$ \textbf{to} $3MN + 512$}
        \State $s(i) \gets$ next MHDNN output                            \Comment{collect chaos}
  \EndFor
  \For{$i \gets 1$ \textbf{to} $MN$}
        \State $X(i)   \gets \operatorname{mod}\!\bigl(\lfloor(s_i+100)10^{10}\rfloor , MN\bigr) + 1$
        \State $X_1(i) \gets \operatorname{mod}\!\bigl(\lfloor(s_{i+MN}+100)10^{10}\rfloor , MN\bigr) + 1$
        \State $X_2(i) \gets \operatorname{mod}\!\bigl(\lfloor(s_{i+2MN}+100)10^{10}\rfloor , MN\bigr) + 1$
        \State $SBT(i)\gets \operatorname{mod}\!\bigl(\lfloor(s_{i+3MN}+100)10^{10}\rfloor , 256\bigr) + 1$
  \EndFor
  \State \Return $X, X_1, X_2, SBT$
\end{algorithmic}
\end{algorithm}
\textbf{Dynamic S-Box Construction (DSB).}%
To reinforce the non-linearity of the cipher, a data-dependent $16\times16$ substitution box is generated on-the-fly.  
Specifically, a fresh chaotic subsequence is partitioned, sorted to obtain index vectors, and reshaped into an intermediate matrix that is further permuted by double–swap operations.  
The resulting lookup table~$S$ exhibits good statistical properties and thwarts differential attacks.  
The step-by-step routine is given in\Cref{Algorithm2}.

\begin{algorithm}[H]
\caption{Dynamic S-Box Construction (DSB)}
\label{Algorithm2}
\begin{algorithmic}[1]
  \Require Chaotic sequence $q$ (first $3000$ iterations already discarded)
  \Ensure  $S$ — final $16 \times 16$ S-Box
  \State $\textit{list}  \gets q(1{:}256)$
  \State $\textit{list}_1\gets q(257{:}384)$
  \State $\textit{list}_2\gets q(385{:}512)$
  \State $[L,\;\_]   \gets \text{sort}(\textit{list})$
  \State $[L_1,\;\_] \gets \text{sort}(\textit{list}_1)$
  \State $[L_2,\;\_] \gets \text{sort}(\textit{list}_2)$
  \State $S_1 \gets \text{reshape}(L,16,16)^\top$
  \State $s_1 \gets \text{vec}(S_1)$
  \For{$i \gets 1$ \textbf{to} $128$}
        \State swap$(s_1,L_1(i),L_2(i))$
  \EndFor
  \State $S \gets \text{reshape}(s_1,16,16)$
  \State \Return $S$
\end{algorithmic}
\end{algorithm}

\textbf{Color Image Encryption (CIE).}
With the permutation vectors, diffusion keystream, and dynamic S-Box at hand, the CIE stage encrypts each colour channel independently.  
The plaintext vector is first scrambled by forward permutation, followed by bidirectional diffusion in which the S-Box output and keystream are XOR-combined with the running cipher state.  
A reverse permutation finalises the confusion process before the channel is reshaped back to its two-dimensional form.  
The operations for all three channels collectively constitute the overall cipher, as detailed in Algorithm~\ref{Algorithm.3}.
\begin{algorithm}[H]
\caption{Color Image Encryption (CIE)}
\label{Algorithm.3}
\begin{algorithmic}[1]
  \Require Plain image $P \in \mathbb{Z}_{256}^{M \times N \times 3}$
  \Statex \hspace{\algorithmicindent}Keystreams $X, X_1, X_2, SBT$
  \Statex \hspace{\algorithmicindent}S-Box $S$
  \Ensure  Cipher image $C$

  \State $sx \gets \text{vec}(S)$ 
  \For{\textbf{each} channel $ch \in \{R,G,B\}$}
        \State $A \gets \text{vec}(P(:,:,ch))$; \quad $T \gets MN$

        \For{$i \gets 1$ \textbf{to} $\lfloor T/2 \rfloor$}
              \State swap$(A,X(i),X(T-i+1))$
        \EndFor

        \State $B(1) \gets A(1)$
        \For{$i \gets 2$ \textbf{to} $T$}
              \State $B(i) \gets A(i) \oplus \bigl(B(i-1) \oplus sx(SBT(i))\bigr)$
        \EndFor

        \State $C_{\text{tmp}}(T) \gets B(T)$
        \For{$i \gets T-1$ \textbf{downto} $1$}
              \State $C_{\text{tmp}}(i) \gets B(i) \oplus \bigl(C_{\text{tmp}}(i+1) \oplus sx(SBT(i))\bigr)$
        \EndFor

        \For{$i \gets 1$ \textbf{to} $\lfloor T/2 \rfloor$}
              \State swap$(C_{\text{tmp}}, X_2(i), X_2(T-i+1))$
        \EndFor
        \State $C(:,:,ch) \gets \text{reshape}(C_{\text{tmp}}, M, N)$
  \EndFor
  \State \Return $C$
\end{algorithmic}
\end{algorithm}



